    fn refresh_movement_speed(&mut self) {
        let revision = self.inventory.revision();
        let speed = self
            .fall
            .effects()
            .speed
            .as_ref()
            .map(|effect| effect.amplifier);
        let slowness = self
            .fall
            .effects()
            .slowness
            .as_ref()
            .map(|effect| effect.amplifier);
        if self
            .movement_speed_cache
            .as_ref()
            .is_some_and(|cache| (cache.0, cache.1, cache.2) == (revision, speed, slowness))
        {
            return;
        }
        let registry = self
            .oxygen_equipment
            .as_ref()
            .map(|(_, registry)| Arc::clone(registry))
            .unwrap_or_default();
        let result = crate::equipment_attributes::equipped_attribute(
            &self.movement_speed_attribute,
            &self.inventory,
            &registry,
            "movement_speed",
        )
        .and_then(|attribute| {
            Ok([
                attribute.movement_speed(None, None, false)?,
                attribute.movement_speed(None, None, true)?,
            ])
        });
        let values = match result {
            Ok(values) => values,
            Err(error) => {
                self.stream_errors
                    .push(format!("player movement speed equipment: {error:#}"));
                [
                    0.1_f32,
                    (f64::from(0.1_f32) * (1.0 + f64::from(0.3_f32))) as f32,
                ]
            }
        };
        self.movement_speed_cache = Some((revision, speed, slowness, values));
    }

    fn movement_speed(&self, sprinting: bool) -> f32 {
        self.movement_speed_cache
            .as_ref()
            .map_or(0.1, |cache| cache.3[usize::from(sprinting)])
    }

    fn update_movement_effect_modifiers(&mut self, transitions: [bool; 2]) {
        use native_resources::enchantments::{AttributeModifier, AttributeOperation};
        use native_resources::packs::ResourceId;
        for (transition, current, name, base) in [
            (
                transitions[0],
                &self.fall.effects().speed,
                "effect.speed",
                f64::from(0.2_f32),
            ),
            (
                transitions[1],
                &self.fall.effects().slowness,
                "effect.slowness",
                f64::from(-0.15_f32),
            ),
        ] {
            if transition {
                let id = ResourceId::parse(&format!("minecraft:{name}"))
                    .expect("vanilla effect identifier");
                self.movement_speed_attribute.remove_modifier(&id);
                if let Some(effect) = current {
                    self.movement_speed_attribute.apply(AttributeModifier {
                        id,
                        operation: AttributeOperation::AddMultipliedTotal,
                        amount: base * (f64::from(effect.amplifier) + 1.0),
                    });
                }
                self.movement_speed_cache = None;
            }
        }
    }

    /// Restore the persistent fall attributes and active status effects.
    pub fn set_saved_fall(
        &mut self,
        safe: crate::player_data::SavedAttribute,
        multiplier: crate::player_data::SavedAttribute,
        effects: crate::survival::FallEffects,
    ) -> anyhow::Result<()> {
        let registry = self
            .oxygen_equipment
            .as_ref()
            .map(|(_, registry)| Arc::clone(registry))
            .ok_or_else(|| anyhow::anyhow!("active enchantment registry is unavailable"))?;
        self.effect_save_invalid |= self.tick != 0;
        self.fall.configure(safe, multiplier, effects, registry);
        Arc::make_mut(&mut self.snapshot).active_effects =
            crate::survival::display_effects(self.fall.effects(), &self.breathing_effects);
        Arc::make_mut(&mut self.snapshot).hunger_effect = self.fall.effects().hunger.is_some();
        Arc::make_mut(&mut self.snapshot).poison_effect = self.fall.effects().poison.is_some();
        Arc::make_mut(&mut self.snapshot).night_vision_duration = self
            .fall
            .effects()
            .night_vision
            .as_ref()
            .map(|effect| effect.duration);
        self.movement_speed_cache = None;
        Ok(())
    }

    fn refresh_equipment_oxygen(&mut self) {
        let Some((attribute, enchantments)) = &self.oxygen_equipment else {
            return;
        };
        let revision = self.inventory.revision();
        if self.oxygen_inventory_revision == Some(revision) {
            return;
        }
        self.oxygen_inventory_revision = Some(revision);
        match crate::equipment_attributes::oxygen_bonus(attribute, &self.inventory, enchantments) {
            Ok(value) => {
                self.oxygen_bonus = value;
                self.oxygen_valid = true;
            }
            Err(error) => {
                self.oxygen_valid = false;
                self.stream_errors
                    .push(format!("player oxygen equipment: {error:#}"));
            }
        }
    }

    /// Restore the exact position and movement before the first simulation tick.
    /// The renderer's f32 snapshot is separate from the f64 physics state.
    pub fn restore_saved_motion(
        &mut self,
        position: DVec3,
        saved: crate::player_data::SavedPlayerMotion,
    ) -> Result<(), &'static str> {
        if self.tick != 0 || self.accumulated != Duration::ZERO {
            return Err("saved player motion must be restored before the first tick");
        }
        if !position.is_finite()
            || !position.as_vec3().is_finite()
            || !saved.velocity.is_finite()
            || !saved.fall_distance.is_finite()
            || !((saved.velocity.y * 20.0) as f32).is_finite()
        {
            return Err("invalid saved player motion");
        }
        self.motion.position = position;
        self.ground_support = None;
        self.ground_without_support = false;
        self.motion.velocity = saved.velocity;
        self.motion.on_ground = saved.on_ground;
        self.fall_distance = saved.fall_distance;
        self.player.position = position.as_vec3();
        self.player.vertical_velocity = (saved.velocity.y * 20.0) as f32;
        self.player.on_ground = saved.on_ground;
        self.camera = crate::camera::CameraMotion::new(position, self.player.pose.eye_height());
        let snapshot = Arc::make_mut(&mut self.snapshot);
        snapshot.player = self.player;
        snapshot.camera = self.camera;
        Ok(())
    }

    /// Restore the player's saved flight speed before starting the session.
    pub fn restore_saved_flight_speed(&mut self, speed: f32) -> Result<(), &'static str> {
        if self.tick != 0 || self.accumulated != Duration::ZERO {
            return Err("saved flight speed must be restored before the first tick");
        }
        if !speed.is_finite() {
            return Err("invalid saved flight speed");
        }
        self.flight_speed = speed;
        Ok(())
    }

    pub fn restore_saved_walking_speed(&mut self, speed: f32) -> Result<(), &'static str> {
        if self.tick != 0 || self.accumulated != Duration::ZERO {
            return Err("saved walking speed must be restored before the first tick");
        }
        if !speed.is_finite() {
            return Err("invalid saved walking speed");
        }
        self.walking_speed = speed;
        Ok(())
    }

    pub fn restore_saved_flying(&mut self, flying: bool) -> Result<(), &'static str> {
        if self.tick != 0 || self.accumulated != Duration::ZERO {
            return Err("saved flight state must be restored before the first tick");
        }
        self.flight.flying = self.game_mode == GameMode::Spectator
            || (self.game_mode == GameMode::Creative && flying);
        Ok(())
    }

    /// Capture simulated player data at a tick boundary. This draft cannot be
    /// written until changed chunks, entities, ticks and other state are handled.
    pub fn draft_player_state(
        &self,
        original: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<crate::player_data::PlayerStateDraft> {
        anyhow::ensure!(
            self.chest_dirty_chunks.is_empty(),
            "changed chest inventories require a coordinated world save"
        );
        anyhow::ensure!(
            self.random_sequences
                .as_ref()
                .is_none_or(|sequences| !sequences.data.is_dirty()),
            "changed random sequences require a coordinated world save"
        );
        self.draft_player_state_inner(original)
    }

    /// Build player and all changed chest drafts together. Chunk drafts here
    /// cover inventory only and remain ineligible for a durable world write.
    pub fn draft_player_and_chests(
        &self,
        player: &native_persistence::nbt::NamedTag,
        chunks: &BTreeMap<ChunkPos, native_persistence::nbt::NamedTag>,
    ) -> anyhow::Result<PlayerChestDraft> {
        self.validate_player_draft_source(player)?;
        anyhow::ensure!(
            chunks.len() == self.chest_dirty_chunks.len()
                && self
                    .chest_dirty_chunks
                    .iter()
                    .all(|pos| chunks.contains_key(pos)),
            "all changed chest chunks must be supplied exactly once"
        );
        let chests = chunks
            .iter()
            .map(|(&pos, source)| Ok((pos, self.draft_chest_inventory_chunk(pos, source)?)))
            .collect::<anyhow::Result<BTreeMap<_, _>>>()?;
        let player = self.draft_player_state_inner(player)?;
        Ok(PlayerChestDraft { player, chests })
    }

    /// Verify a closed-container transfer did not create or discard item
    /// stacks. This is one prerequisite, not authorization for a world save:
    /// callers still need to validate every changed chunk and other world state.
    pub fn validate_closed_chest_item_balance(
        &self,
        player_source: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<()> {
        self.validate_player_draft_source(player_source)?;
        anyhow::ensure!(
            self.commands.is_empty(),
            "pending commands have not reached a tick"
        );
        anyhow::ensure!(
            self.inventory.ready_for_player_save(),
            "an inventory or cursor is still open"
        );
        anyhow::ensure!(
            self.placed_chests.is_empty() && self.removed_chests.is_empty(),
            "chest creation or removal requires separate accounting"
        );
        self.validate_generated_chest_loot()?;
        let original = crate::player_data::read_saved_player(player_source)?;
        let before = crate::player_data::saved_slots(&original).chain(
            self.chest_contents
                .values()
                .flat_map(|chest| chest.transfer_baseline().iter().flatten()),
        );
        let after = crate::player_data::saved_slots(&self.inventory).chain(
            self.chest_contents
                .values()
                .flat_map(|chest| chest.slots.iter().flatten()),
        );
        crate::inventory::validate_item_balance(before, after)
    }

    /// Replay all generated chest loot in its actual order and confirm that
    /// each named stream begins at the captured world source and ends at the
    /// current session state. Untracked use of the same stream fails closed.
    fn validate_generated_chest_loot(&self) -> anyhow::Result<()> {
        use crate::saved_chest::LootRandomTrace;
        use anyhow::{Context, ensure};
        let mut visited = BTreeSet::new();
        let mut streams = BTreeMap::<
            native_resources::packs::ResourceId,
            native_core::random::XoroshiroRandom,
        >::new();
        let mut initial_sequences = None;
        for position in &self.loot_events {
            ensure!(
                visited.insert(position.to_array()),
                "duplicate generated chest event"
            );
            let chest = self
                .chest_contents
                .get(&(position.x, position.y, position.z))
                .context("generated chest is no longer available")?;
            let trace = chest
                .loot_trace()
                .context("generated chest has no random trace")?;
            let table_id = match trace {
                LootRandomTrace::Fixed { table, .. }
                | LootRandomTrace::Named { table, .. }
                | LootRandomTrace::Level { table, .. } => table,
            };
            let table = self
                .chest_loot
                .as_ref()
                .and_then(|tables| tables.get(table_id))
                .context("generated chest loot table is unavailable")?;
            let registry = self
                .item_registry
                .as_ref()
                .context("item registry is unavailable")?;
            ensure!(
                !matches!(trace, LootRandomTrace::Level { .. }),
                "level-random chest loot requires a complete world-random audit"
            );
            if let LootRandomTrace::Named {
                sequence,
                before,
                after,
                ..
            } = trace
            {
                let saved = self
                    .random_sequences
                    .as_ref()
                    .context("world random sequences are unavailable")?;
                if !streams.contains_key(sequence) {
                    if initial_sequences.is_none() {
                        initial_sequences =
                            Some(native_persistence::random_sequences::RandomSequences::read(
                                saved.data.source().cloned(),
                            )?);
                    }
                    let name = format!("{}:{}", sequence.namespace, sequence.path);
                    streams.insert(
                        sequence.clone(),
                        initial_sequences
                            .as_ref()
                            .unwrap()
                            .get(&name, saved.world_seed)?,
                    );
                }
                let random = streams.get_mut(sequence).unwrap();
                ensure!(
                    random.state() == *before,
                    "generated chest random sequence order differs"
                );
                *random = native_core::random::XoroshiroRandom::from_state(after.0, after.1);
            }
            chest.verify_generated_loot(table_id, table, |item| {
                Self::resolve_chest_loot_item(item, registry)
            })?;
        }
        ensure!(
            self.chest_contents
                .values()
                .filter(|chest| chest.has_generated_loot())
                .count()
                == visited.len(),
            "generated chest event is missing"
        );
        for (sequence, random) in streams {
            let saved = self
                .random_sequences
                .as_ref()
                .context("world random sequences are unavailable")?;
            let name = format!("{}:{}", sequence.namespace, sequence.path);
            ensure!(
                saved.data.get(&name, saved.world_seed)?.state() == random.state(),
                "world random sequence changed outside tracked loot events"
            );
        }
        Ok(())
    }

    /// Stage the player and every dirty terrain chunk, including known block,
    /// heightmap, scheduled tick, chest inventory and completed light changes.
    /// Entity regions, clocks and unsupported effects are still separate.
    pub fn draft_player_and_dirty_chunks(
        &self,
        player: &native_persistence::nbt::NamedTag,
        sources: &BTreeMap<ChunkPos, &native_persistence::nbt::NamedTag>,
        tags: &HeightmapTags,
        air_and_fluid: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<(bool, bool)>,
    ) -> anyhow::Result<PlayerWorldDraft> {
        anyhow::ensure!(
            self.random_sequences
                .as_ref()
                .is_none_or(|sequences| !sequences.data.is_dirty()),
            "changed random sequences require a coordinated world save"
        );
        self.draft_player_and_dirty_chunks_inner(player, sources, tags, air_and_fluid)
    }

    fn draft_player_and_dirty_chunks_inner(
        &self,
        player: &native_persistence::nbt::NamedTag,
        sources: &BTreeMap<ChunkPos, &native_persistence::nbt::NamedTag>,
        tags: &HeightmapTags,
        mut air_and_fluid: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<(bool, bool)>,
    ) -> anyhow::Result<PlayerWorldDraft> {
        self.validate_player_draft_source(player)?;
        anyhow::ensure!(
            self.pending_light.is_empty() && self.sky_lighting.settled(),
            "lighting updates are not complete"
        );
        let dirty = self.dirty_chunk_positions();
        anyhow::ensure!(
            sources.len() == dirty.len() && dirty.iter().all(|pos| sources.contains_key(pos)),
            "all dirty terrain chunks must be supplied exactly once"
        );
        let player = self.draft_player_state_inner(player)?;
        let chunks = sources
            .iter()
            .map(|(&pos, source)| {
                Ok((
                    pos,
                    self.draft_dirty_chunk_with_lighting(pos, source, tags, &mut air_and_fluid)?,
                ))
            })
            .collect::<anyhow::Result<BTreeMap<_, _>>>()?;
        Ok(PlayerWorldDraft { player, chunks })
    }

    /// Snapshot player, terrain, tracked entity chunks and clocks at the
    /// same tick boundary. This remains incomplete for a playable world save.
    pub fn draft_player_terrain_entities_and_clocks(
        &self,
        player: &native_persistence::nbt::NamedTag,
        terrain: &BTreeMap<ChunkPos, &native_persistence::nbt::NamedTag>,
        clock: &native_persistence::nbt::NamedTag,
        tags: &HeightmapTags,
        air_and_fluid: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<(bool, bool)>,
    ) -> anyhow::Result<PartialSessionSaveDraft> {
        let player_and_terrain =
            self.draft_player_and_dirty_chunks_inner(player, terrain, tags, air_and_fluid)?;
        if !self.loot_events.is_empty()
            || player_and_terrain
                .chunks
                .values()
                .any(|chunk| chunk.checked_chest_inventory_count() != 0)
        {
            self.validate_closed_chest_item_balance(player)?;
        }
        let entity_chunks = self.draft_tracked_entity_chunks()?;
        let clocks = self.draft_world_clocks(clock)?;
        anyhow::ensure!(
            self.can_have_weather != Some(true) || self.weather.is_some(),
            "saved weather is unavailable for this dimension"
        );
        Ok(PartialSessionSaveDraft {
            dimension: native_persistence::world::DimensionId::parse(&self.world.dimension)?,
            player_and_terrain,
            entity_chunks,
            clocks,
            weather: if let Some(weather) = &self.weather {
                Some(WeatherSaveDraft {
                    source: self
                        .weather_source
                        .as_ref()
                        .ok_or_else(|| {
                            anyhow::anyhow!(
                                "saved weather source was not captured at session start"
                            )
                        })?
                        .clone(),
                    weather: weather.data,
                })
            } else {
                None
            },
            level_time: if self.initial_game_time_set {
                Some(LevelTimeSaveDraft {
                    source: Arc::clone(self.level_time_source.as_ref().ok_or_else(|| {
                        anyhow::anyhow!("level time source was not captured at session start")
                    })?),
                    time: self.game_time,
                })
            } else {
                None
            },
            random_sequences: self
                .random_sequences
                .as_ref()
                .filter(|sequences| sequences.data.is_dirty())
                .map(|sequences| sequences.data.clone()),
        })
    }

    /// Include POI transitions in the same immutable tick-boundary draft as
    /// the player, terrain, tracked entities and clocks. Registry callbacks
    /// must validate all supplied data. This is not a complete gameplay save.
    pub fn draft_player_terrain_entities_clocks_and_poi(
        &self,
        player: &native_persistence::nbt::NamedTag,
        terrain: &BTreeMap<ChunkPos, &native_persistence::nbt::NamedTag>,
        clock: &native_persistence::nbt::NamedTag,
        tags: &HeightmapTags,
        air_and_fluid: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<(bool, bool)>,
        mut resolve_saved_state: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<BlockState>,
        mut validate_state: impl FnMut(&BlockState) -> anyhow::Result<()>,
        mut validate_poi_type: impl FnMut(&native_persistence::nbt::JavaString) -> anyhow::Result<()>,
    ) -> anyhow::Result<PartialSessionPoiSaveDraft> {
        use anyhow::Context;
        let session = self.draft_player_terrain_entities_and_clocks(
            player,
            terrain,
            clock,
            tags,
            air_and_fluid,
        )?;
        let mut poi = BTreeMap::new();
        for position in self.dirty_poi_chunk_positions() {
            let source = terrain
                .get(&position)
                .context("POI terrain source is missing from the session snapshot")?;
            let draft = self.draft_reconciled_poi_chunk(
                position,
                source,
                &mut resolve_saved_state,
                &mut validate_state,
                &mut validate_poi_type,
            )?;
            poi.insert(position, draft);
        }
        Ok(PartialSessionPoiSaveDraft { session, poi })
    }

    fn validate_player_draft_source(
        &self,
        source: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<()> {
        let initial = self.saved_player_inventory_source.as_ref().ok_or_else(|| {
            anyhow::anyhow!("saved player inventory source was not captured at session start")
        })?;
        anyhow::ensure!(
            native_persistence::nbt::write(source)? == *initial,
            "saved player source differs from the session source"
        );
        Ok(())
    }

    fn draft_player_state_inner(
        &self,
        original: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<crate::player_data::PlayerStateDraft> {
        anyhow::ensure!(
            !self.unresolved_player_damage,
            "player damage could not be resolved during this session"
        );
        anyhow::ensure!(
            !self.unresolved_player_fire_contact,
            "player lava and fire interactions are not yet supported for saving"
        );
        if self.tick > 0 {
            let fire = crate::player_data::read_saved_fire_for_preservation(original)?;
            anyhow::ensure!(
                fire <= 0,
                "saved player fire is not yet simulated and cannot be saved after ticking"
            );
        }
        anyhow::ensure!(
            self.commands.is_empty(),
            "pending player commands have not reached a tick"
        );
        anyhow::ensure!(
            crate::player_data::read_saved_walking_speed(original)? == self.walking_speed,
            "saved walking speed does not match the session"
        );
        let initial_movement = self
            .effect_save_tracking
            .as_ref()
            .map_or(&self.movement_speed_attribute, |tracking| {
                &tracking.movement_speed
            });
        anyhow::ensure!(
            crate::player_data::read_loaded_movement_speed_attribute(original)?
                == *initial_movement,
            "saved movement attribute does not match the initial session state"
        );
        let initial_safe_fall = self
            .effect_save_tracking
            .as_ref()
            .map_or(self.fall.safe_attribute(), |tracking| &tracking.safe_fall);
        anyhow::ensure!(
            crate::player_data::read_saved_fall_attributes(original)?.0 == *initial_safe_fall,
            "saved safe fall attribute does not match the initial session state"
        );
        anyhow::ensure!(
            crate::player_data::read_saved_no_gravity(original) == self.no_gravity,
            "saved no-gravity state does not match the session"
        );
        let initial_gravity = self
            .effect_save_tracking
            .as_ref()
            .map_or(&self.gravity_attribute, |tracking| &tracking.gravity);
        anyhow::ensure!(
            crate::player_data::read_saved_gravity_attribute(original)? == *initial_gravity,
            "saved gravity attribute does not match the initial session state"
        );
        let initial_water_efficiency = self
            .effect_save_tracking
            .as_ref()
            .map_or(&self.water_efficiency_attribute, |tracking| {
                &tracking.water_efficiency
            });
        anyhow::ensure!(
            crate::player_data::read_saved_water_movement_efficiency_attribute(original)?
                == *initial_water_efficiency,
            "saved water movement efficiency does not match the initial session state"
        );
        let initial_mining = self
            .effect_save_tracking
            .as_ref()
            .map_or(&self.mining_attributes, |tracking| {
                &tracking.mining_attributes
            });
        anyhow::ensure!(
            crate::player_data::read_saved_mining_attributes(original)? == *initial_mining,
            "saved mining attributes do not match the initial session state"
        );
        let effect_draft = if self.tick != 0 {
            anyhow::ensure!(
                !self.effect_save_invalid,
                "player effects changed outside the tracked tick sequence"
            );
            let (initial_breathing, initial_fall, effect_ticks, updates) =
                match &self.effect_save_tracking {
                    Some(tracking) => (
                        &tracking.breathing,
                        &tracking.fall,
                        tracking.ticks,
                        tracking.status_updates.as_slice(),
                    ),
                    None => (&self.breathing_effects, self.fall.effects(), 0, &[][..]),
                };
            anyhow::ensure!(
                crate::player_data::read_saved_breathing_effects(original)? == *initial_breathing
                    && crate::player_data::read_saved_fall_effects(original)? == *initial_fall,
                "saved player effects do not match the initial session state"
            );
            let effects =
                crate::player_data::replay_saved_status_effects(original, effect_ticks, updates)?;
            let advanced = native_persistence::nbt::NamedTag {
                name: "".into(),
                value: native_persistence::nbt::Tag::Compound(
                    effects
                        .clone()
                        .map(|tag| ("active_effects".into(), tag))
                        .into_iter()
                        .collect(),
                ),
            };
            anyhow::ensure!(
                crate::player_data::read_saved_breathing_effects(&advanced)?
                    == self.breathing_effects
                    && crate::player_data::read_saved_fall_effects(&advanced)?
                        == *self.fall.effects(),
                "saved effect draft does not match the current session state"
            );
            Some(effects)
        } else {
            None
        };
        let mut yaw = self.player.yaw.to_degrees() - 180.0;
        let mut pitch = -self.player.pitch.to_degrees();
        // Preserve the exact source angles when the player's view has not moved;
        // converting degrees through radians can otherwise change their last bits.
        if let Some(native_persistence::nbt::Tag::List { values, .. }) =
            original.value.get("Rotation")
            && let [
                native_persistence::nbt::Tag::Float(source_yaw),
                native_persistence::nbt::Tag::Float(source_pitch),
            ] = values.as_slice()
        {
            if self.player.yaw == (*source_yaw + 180.0).to_radians() {
                yaw = *source_yaw;
            }
            if self.player.pitch
                == (-*source_pitch)
                    .to_radians()
                    .clamp(-crate::MAX_PITCH, crate::MAX_PITCH)
            {
                pitch = *source_pitch;
            }
        }
        let state = crate::player_data::PlayerSaveState {
            position: self.motion.position + self.origin.as_dvec3(),
            motion: crate::player_data::SavedPlayerMotion {
                velocity: self.motion.velocity,
                on_ground: self.motion.on_ground,
                fall_distance: self.fall_distance,
            },
            yaw,
            pitch,
            dimension: self.world.dimension.clone(),
            game_mode: self.game_mode,
            vitals: self.vitals,
            experience: self.experience,
            score: self.score,
        };
        let mut draft = crate::player_data::draft_player_state(original, &state, &self.inventory)?;
        if self.tick > 0 {
            draft.set_fire(original, self.player_fire_ticks)?;
        }
        if self.last_death_dirty {
            let crate::LastDeathLocation::At(target) = &self.snapshot.last_death else {
                anyhow::bail!("last-death position is unavailable");
            };
            draft.set_last_death_location(original, target)?;
        }
        draft.set_flying(original, self.flight.flying)?;
        if let Some(effects) = effect_draft {
            draft.set_effects(effects)?;
        }
        draft.set_movement_effect_modifiers(
            original,
            initial_movement,
            &self.movement_speed_attribute,
        )?;
        draft.set_jump_effect_modifier(original, initial_safe_fall, self.fall.safe_attribute())?;
        Ok(draft)
    }

    /// Construct a block-state-only draft from a dirty resident or parked chunk.
    /// Lighting, heightmaps, entities and scheduled ticks are not rebuilt here,
    /// so the result is not sufficient to write a playable world.
    pub fn draft_changed_chunk(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        use anyhow::Context;
        anyhow::ensure!(
            self.commands.is_empty(),
            "pending player commands have not reached a tick"
        );
        let edits = self
            .block_edits
            .get(&position)
            .context("chunk has no recorded block edits")?;
        let chunk = self
            .world
            .chunks
            .get(&position)
            .or_else(|| self.parked_chunks.get(&position))
            .context("edited chunk is no longer available")?;
        anyhow::ensure!(
            chunk.position == position,
            "edited chunk position does not match its key"
        );
        let state = |id: BlockStateId| -> anyhow::Result<native_persistence::palette::BlockState> {
            let value = self
                .world
                .state(id)
                .context("edited chunk references an unknown block state")?;
            Ok(native_persistence::palette::BlockState {
                name: value.name.as_str().into(),
                properties: value
                    .properties
                    .iter()
                    .map(|(name, value)| (name.as_str().into(), value.as_str().into()))
                    .collect(),
            })
        };
        let mut changes = Vec::with_capacity(edits.len());
        for (&(x, y, z), edit) in edits {
            let original_id = edit
                .original
                .context("edited block had no known source block data")?;
            let section_y =
                i8::try_from(y.div_euclid(16)).context("edited section is out of range")?;
            let index = x.rem_euclid(16) as usize
                + z.rem_euclid(16) as usize * 16
                + y.rem_euclid(16) as usize * 256;
            let current = chunk
                .sections
                .get(&section_y)
                .and_then(|section| section.blocks.as_ref())
                .context("edited block data is no longer available")?[index];
            anyhow::ensure!(
                current == edit.current,
                "edited block changed outside the recorded session history"
            );
            changes.push(native_persistence::edit::BlockChange {
                x,
                y,
                z,
                expected: state(original_id)?,
                replacement: state(edit.current)?,
            });
        }
        native_persistence::edit::draft_chunk_blocks(
            original,
            native_persistence::world::ChunkPos {
                x: position.x,
                z: position.z,
            },
            &changes,
        )
    }

    /// Chunks with recorded POI transitions, including changes later undone.
    pub fn dirty_poi_chunk_positions(&self) -> BTreeSet<ChunkPos> {
        self.poi_edits.keys().copied().collect()
    }

    /// Stage recorded POI transitions against a valid saved POI chunk and a
    /// verified terrain source. The caller must supply the POI captured at
    /// session load and validate every block state against its registry. This
    /// draft does not include villager ticket changes or authorize saving.
    pub fn draft_poi_chunk(
        &self,
        position: ChunkPos,
        terrain_source: &native_persistence::nbt::NamedTag,
        poi_source: &native_persistence::world::SavedPoiChunk,
        mut validate_state: impl FnMut(&BlockState) -> anyhow::Result<()>,
    ) -> anyhow::Result<native_persistence::poi::PoiDraft> {
        use anyhow::ensure;
        ensure!(
            poi_source.position
                == native_persistence::world::ChunkPos {
                    x: position.x,
                    z: position.z
                },
            "POI source belongs to another chunk"
        );
        let captured = match self.poi_chunks.get(&position) {
            Some(SavedPoiData::Present(chunk)) => chunk,
            Some(SavedPoiData::Missing) => {
                anyhow::bail!("saved POI chunk was absent and needs reconstruction")
            }
            Some(SavedPoiData::Unavailable) | None => {
                anyhow::bail!("saved POI source is unavailable")
            }
        };
        ensure!(
            native_persistence::nbt::write(&captured.document)?
                == native_persistence::nbt::write(&poi_source.document)?,
            "POI source differs from the captured session source"
        );
        let changes = self.recorded_poi_changes(position, terrain_source, &mut validate_state)?;
        native_persistence::poi::draft_ordered_block_changes(poi_source, &changes, validate_state)
    }

    fn recorded_poi_changes(
        &self,
        position: ChunkPos,
        terrain_source: &native_persistence::nbt::NamedTag,
        mut validate_state: impl FnMut(&BlockState) -> anyhow::Result<()>,
    ) -> anyhow::Result<Vec<native_persistence::poi::PoiBlockChange>> {
        use anyhow::{Context, ensure};
        let events = self
            .poi_edits
            .get(&position)
            .context("chunk has no recorded POI transitions")?;
        // This checks every edited block against the original terrain and the
        // currently resident or parked chunk before constructing POI changes.
        self.draft_changed_chunk(position, terrain_source)?;
        let edits = self
            .block_edits
            .get(&position)
            .context("POI terrain history is unavailable")?;
        let mut first = BTreeSet::new();
        let mut last = BTreeMap::new();
        let mut changes = Vec::with_capacity(events.len());
        for event in events {
            let key = (event.position.x, event.position.y, event.position.z);
            let edit = edits
                .get(&key)
                .context("POI block history is unavailable")?;
            let old = self
                .world
                .state(
                    event
                        .original
                        .context("POI transition has no original state")?,
                )
                .context("POI transition old state is unavailable")?;
            let new = self
                .world
                .state(event.replacement)
                .context("POI transition new state is unavailable")?;
            if first.insert(key) {
                let initial = self
                    .world
                    .state(edit.original.context("POI block source is unavailable")?)
                    .context("POI block source state is unavailable")?;
                validate_state(initial)?;
                validate_state(old)?;
                ensure!(
                    native_world::poi::for_state(initial) == native_world::poi::for_state(old),
                    "initial POI transition does not match terrain source"
                );
            }
            last.insert(key, event.replacement);
            changes.push(native_persistence::poi::PoiBlockChange {
                position: [key.0, key.1, key.2],
                expected: old.clone(),
                replacement: new.clone(),
            });
        }
        for (key, final_state) in last {
            ensure!(
                edits[&key].current == final_state,
                "POI history does not match current terrain"
            );
        }
        Ok(changes)
    }

    /// Reconcile missing or invalid POI sections against source-verified
    /// terrain before replaying the session's ordered block transitions.
    /// The saved-state resolver must apply registry defaults and reject unknown
    /// or noncanonical states. Other world effects still prohibit gameplay save.
    pub fn draft_reconciled_poi_chunk(
        &self,
        position: ChunkPos,
        terrain_source: &native_persistence::nbt::NamedTag,
        mut resolve_saved_state: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<BlockState>,
        mut validate_state: impl FnMut(&BlockState) -> anyhow::Result<()>,
        mut validate_poi_type: impl FnMut(&native_persistence::nbt::JavaString) -> anyhow::Result<()>,
    ) -> anyhow::Result<native_persistence::poi::ReconciledPoiDraft> {
        use anyhow::{Context, ensure};
        let captured = match self.poi_chunks.get(&position) {
            Some(SavedPoiData::Present(chunk)) => {
                Some(native_persistence::world::SavedPoiChunk::from_document(
                    (*chunk.document).clone(),
                    chunk.position,
                )?)
            }
            Some(SavedPoiData::Missing) => None,
            Some(SavedPoiData::Unavailable) | None => {
                anyhow::bail!("saved POI source is unavailable")
            }
        };
        let changes = self.recorded_poi_changes(position, terrain_source, &mut validate_state)?;
        let edits = self
            .block_edits
            .get(&position)
            .context("POI terrain history is unavailable")?;
        let mut original_world = (*self.world).clone();
        if !original_world.chunks.contains_key(&position) {
            original_world.chunks.insert(
                position,
                Arc::clone(
                    self.parked_chunks
                        .get(&position)
                        .context("POI terrain chunk is unavailable")?,
                ),
            );
        }
        for (&(x, y, z), edit) in edits {
            let old = edit
                .original
                .context("POI terrain source state is unavailable")?;
            original_world
                .set_block_id(x, y, z, old)
                .map_err(|error| anyhow::anyhow!("cannot reconstruct POI terrain: {error}"))?;
        }
        let sections: BTreeSet<i8> = changes
            .iter()
            .filter(|change| {
                native_world::poi::change(&change.expected, &change.replacement).is_some()
            })
            .map(|change| {
                i8::try_from(change.position[1].div_euclid(16))
                    .context("POI section is out of range")
            })
            .collect::<anyhow::Result<_>>()?;
        let source_sections = native_persistence::palette::decode_sections(&terrain_source.value)?;
        let chunk = original_world
            .chunks
            .get(&position)
            .context("POI terrain chunk is unavailable")?;
        for y in sections {
            if captured
                .as_ref()
                .and_then(|chunk| chunk.sections.get(&i32::from(y)))
                .is_some_and(|section| section.valid)
            {
                continue;
            }
            let palette = source_sections
                .iter()
                .find(|section| section.y == y)
                .and_then(|section| section.blocks.as_ref())
                .context("POI source terrain section is incomplete")?;
            let mut resolved = Vec::with_capacity(palette.states.len());
            for state in &palette.states {
                let state = resolve_saved_state(state)?;
                validate_state(&state)?;
                resolved.push(state);
            }
            let blocks = chunk
                .sections
                .get(&y)
                .and_then(|section| section.blocks.as_ref())
                .context("POI runtime terrain section is incomplete")?;
            for (index, id) in blocks.iter().enumerate() {
                let runtime = original_world
                    .state(*id)
                    .context("POI runtime terrain state is unavailable")?;
                let saved = resolved
                    .get(palette.indices[index] as usize)
                    .context("POI terrain palette index is invalid")?;
                ensure!(
                    runtime == saved,
                    "POI source terrain section differs from the session source"
                );
            }
        }
        native_persistence::poi::reconcile_and_draft_block_changes(
            captured.as_ref(),
            native_persistence::world::ChunkPos {
                x: position.x,
                z: position.z,
            },
            &original_world,
            &changes,
            &mut validate_state,
            &mut validate_poi_type,
        )
    }

    /// Combine block edits and supported block ticks in memory only.
    /// The result is not yet safe to write as a playable chunk.
    pub fn draft_changed_chunk_with_block_ticks(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        let ticks = self.draft_block_ticks(position)?;
        let mut draft = self.draft_changed_chunk(position, original)?;
        draft.replace_block_ticks(&ticks)?;
        Ok(draft)
    }

    /// Combine changed blocks and the currently supported block and fluid ticks.
    /// Lighting, entities, other tick types and durable writes remain unfinished.
    pub fn draft_changed_chunk_with_simulated_ticks(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        let fluids = self.draft_fluid_ticks(position)?;
        let mut draft = self.draft_changed_chunk_with_block_ticks(position, original)?;
        draft.replace_fluid_ticks(&fluids)?;
        Ok(draft)
    }

    /// Rebuild known heightmaps in a block draft with active data-pack tags and
    /// caller-provided, authoritative air/fluid state semantics. Other chunk
    /// data still requires coordinated validation before any world write.
    pub fn draft_changed_chunk_with_heightmaps(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
        tags: &native_resources::heightmap_tags::HeightmapTags,
        mut air_and_fluid: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<(bool, bool)>,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        use anyhow::Context;
        let mut draft = self.draft_changed_chunk(position, original)?;
        draft.rebuild_heightmaps(
            native_persistence::heightmap::HeightBounds {
                min_y: self.bounds.min_y,
                max_y: self.bounds.max_y,
            },
            |state| {
                let name = String::from_utf16(&state.name.0)
                    .context("block state name is not valid UTF-16")?;
                let motion = tags.for_block(&name)?;
                let (is_air, has_fluid) = air_and_fluid(state)?;
                Ok(native_persistence::heightmap::BlockHeightFlags {
                    is_air,
                    has_fluid,
                    blocks_motion: motion.blocks_motion,
                    blocks_motion_no_leaves: motion.blocks_motion_no_leaves,
                })
            },
        )?;
        Ok(draft)
    }

    /// Combine block edits, known heightmaps, and the simulated block/fluid
    /// schedules into one chunk draft. Lighting, block entities, POI, and other
    /// unsupported world effects still require separate
    /// validation before a playable-world write is safe.
    pub fn draft_dirty_chunk_with_heightmaps_and_simulated_ticks(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
        tags: &native_resources::heightmap_tags::HeightmapTags,
        air_and_fluid: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<(bool, bool)>,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        anyhow::ensure!(
            self.dirty_chunk_positions().contains(&position),
            "chunk has no recorded changes"
        );
        anyhow::ensure!(
            !matches!(self.inventory.menu(), Some(InventoryMenu::Chest { position: p, other }) if [Some(p), other].into_iter().flatten().any(|p| p.x.div_euclid(16) == position.x && p.z.div_euclid(16) == position.z)),
            "chest inventory is still open"
        );
        let block_ticks = self.draft_block_ticks(position)?;
        let fluid_ticks = self.draft_fluid_ticks(position)?;
        let has_block_edits = self
            .block_edits
            .get(&position)
            .is_some_and(|edits| !edits.is_empty());
        let mut draft = if has_block_edits {
            self.draft_changed_chunk_with_heightmaps(position, original, tags, air_and_fluid)?
        } else {
            self.draft_unchanged_chunk(position, original)?
        };
        draft.replace_block_ticks(&block_ticks)?;
        draft.replace_fluid_ticks(&fluid_ticks)?;
        if self.chest_dirty_chunks.contains(&position) {
            self.stage_chest_inventories(position, original, &mut draft)?;
        }
        self.stage_chest_lifecycle(position, original, &mut draft)?;
        self.stage_banner_lifecycle(position, original, &mut draft)?;
        Ok(draft)
    }

    /// Extend a dirty-chunk draft with completed light-array changes. Pending
    /// relights, entities and other world effects still prevent a safe save.
    pub fn draft_dirty_chunk_with_lighting(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
        tags: &native_resources::heightmap_tags::HeightmapTags,
        air_and_fluid: impl FnMut(
            &native_persistence::palette::BlockState,
        ) -> anyhow::Result<(bool, bool)>,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        use anyhow::{Context, ensure};
        use native_persistence::edit::{LightLayerChange, SectionLightChange};
        ensure!(
            self.pending_light.is_empty() && self.sky_lighting.settled(),
            "lighting updates are not complete"
        );
        let mut draft = self.draft_dirty_chunk_with_heightmaps_and_simulated_ticks(
            position,
            original,
            tags,
            air_and_fluid,
        )?;
        let Some(before) = self.original_light_chunks.get(&position) else {
            return Ok(draft);
        };
        let current = self
            .world
            .chunks
            .get(&position)
            .or_else(|| self.parked_chunks.get(&position))
            .context("light-dirty chunk is unavailable")?;
        ensure!(
            before.block_light_correct && current.block_light_correct,
            "chunk light source is incomplete"
        );
        let native_persistence::nbt::Tag::Compound(fields) = &original.value else {
            anyhow::bail!("chunk must be a compound")
        };
        let markers: Vec<_> = fields
            .iter()
            .filter(|(name, _)| name.matches("isLightOn"))
            .collect();
        ensure!(
            matches!(
                markers.as_slice(),
                [(_, native_persistence::nbt::Tag::Byte(1))]
            ),
            "source light is not known complete"
        );
        let source_sections = native_persistence::palette::decode_sections(&original.value)?;
        let source_ys: BTreeSet<_> = before
            .sections
            .keys()
            .copied()
            .chain(source_sections.iter().map(|section| section.y))
            .collect();
        for y in source_ys {
            let before_section = before.sections.get(&y);
            let source = source_sections.iter().find(|section| section.y == y);
            ensure!(
                before_section
                    .and_then(|section| section.block_light.as_deref())
                    .map(|layer| layer.as_slice())
                    == source.and_then(|section| section.block_light.as_deref())
                    && before_section
                        .and_then(|section| section.sky_light.as_deref())
                        .map(|layer| layer.as_slice())
                        == source.and_then(|section| section.sky_light.as_deref()),
                "original chunk light differs from session source"
            );
        }
        let sections: BTreeSet<i8> = before
            .sections
            .keys()
            .chain(current.sections.keys())
            .copied()
            .collect();
        let mut changes = Vec::new();
        for y in sections {
            let old = before.sections.get(&y);
            let new = current.sections.get(&y);
            let block_before = old.and_then(|section| section.block_light.as_ref());
            let block_after = new.and_then(|section| section.block_light.as_ref());
            let sky_before = old.and_then(|section| section.sky_light.as_ref());
            let sky_after = new.and_then(|section| section.sky_light.as_ref());
            let block = (block_before != block_after).then(|| LightLayerChange {
                expected: block_before.cloned(),
                replacement: block_after.cloned(),
            });
            let sky = (sky_before != sky_after).then(|| LightLayerChange {
                expected: sky_before.cloned(),
                replacement: sky_after.cloned(),
            });
            if block.is_some() || sky.is_some() {
                changes.push(SectionLightChange { y, block, sky });
            }
        }
        draft.replace_section_lights(&changes)?;
        Ok(draft)
    }

    fn draft_unchanged_chunk(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        use anyhow::{Context, ensure};
        ensure!(
            self.commands.is_empty(),
            "pending player commands have not reached a tick"
        );
        let chunk = self
            .world
            .chunks
            .get(&position)
            .or_else(|| self.parked_chunks.get(&position))
            .context("dirty chunk is no longer available")?;
        ensure!(
            chunk.position == position,
            "dirty chunk position does not match its key"
        );
        native_persistence::edit::draft_chunk_blocks(
            original,
            native_persistence::world::ChunkPos {
                x: position.x,
                z: position.z,
            },
            &[],
        )
    }

    /// Chunks containing chest inventories awaiting a coordinated save.
    pub fn dirty_chest_chunk_positions(&self) -> &BTreeSet<ChunkPos> {
        &self.chest_dirty_chunks
    }

    /// Stage closed chest inventories in a source-checked chunk draft. This is
    /// only one part of a save: player, block and entity changes remain separate.
    pub fn draft_chest_inventory_chunk(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
    ) -> anyhow::Result<native_persistence::edit::ChunkDraft> {
        anyhow::ensure!(
            !self
                .placed_chests
                .iter()
                .chain(&self.removed_chests)
                .any(|&(x, _, z)| x.div_euclid(16) == position.x && z.div_euclid(16) == position.z),
            "chest creation or removal requires a coordinated terrain draft"
        );
        anyhow::ensure!(
            !self.chest_contents.values().any(|chest| {
                let p = chest.position;
                p.x.div_euclid(16) == position.x
                    && p.z.div_euclid(16) == position.z
                    && chest.inventory_changed()
                    && self
                        .block_edits
                        .get(&position)
                        .is_some_and(|edits| edits.contains_key(&(p.x, p.y, p.z)))
            }),
            "changed chest block requires a coordinated terrain draft"
        );
        let mut draft = self.draft_unchanged_chunk(position, original)?;
        self.stage_chest_inventories(position, original, &mut draft)?;
        Ok(draft)
    }

    fn stage_chest_inventories(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
        draft: &mut native_persistence::edit::ChunkDraft,
    ) -> anyhow::Result<()> {
        use anyhow::{Context, ensure};
        use native_persistence::edit::BlockEntityMutation;
        ensure!(
            self.chest_dirty_chunks.contains(&position),
            "chunk has no changed chest inventories"
        );
        ensure!(
            !matches!(self.inventory.menu(), Some(InventoryMenu::Chest { position: p, other }) if [Some(p), other].into_iter().flatten().any(|p| p.x.div_euclid(16) == position.x && p.z.div_euclid(16) == position.z)),
            "chest inventory is still open"
        );
        ensure!(
            draft.matches_source(original)?,
            "chunk draft source differs"
        );
        let chunk = self
            .world
            .chunks
            .get(&position)
            .or_else(|| self.parked_chunks.get(&position))
            .context("chest chunk is unavailable")?;
        let sections = native_persistence::palette::decode_sections(&original.value)?;
        let mut changes = Vec::new();
        let mut proofs = Vec::new();
        let mut loot_verifiable = true;
        for chest in self.chest_contents.values().filter(|chest| {
            chest.position.x.div_euclid(16) == position.x
                && chest.position.z.div_euclid(16) == position.z
                && !self.placed_chests.contains(&(
                    chest.position.x,
                    chest.position.y,
                    chest.position.z,
                ))
        }) {
            let edited = chest.draft_inventory(&chest.slots)?;
            if &edited == chest.source() {
                continue;
            }
            let p = chest.position;
            let section_y =
                i8::try_from(p.y.div_euclid(16)).context("chest section out of range")?;
            let index = p.x.rem_euclid(16) as usize
                + p.z.rem_euclid(16) as usize * 16
                + p.y.rem_euclid(16) as usize * 256;
            let current_id = *chunk
                .sections
                .get(&section_y)
                .and_then(|s| s.blocks.as_ref())
                .and_then(|b| b.get(index))
                .context("chest block is unavailable")?;
            let current = self
                .world
                .state(current_id)
                .context("chest block state is unavailable")?;
            let original_state = if let Some(edit) = self
                .block_edits
                .get(&position)
                .and_then(|edits| edits.get(&(p.x, p.y, p.z)))
            {
                ensure!(
                    edit.current == current_id,
                    "chest block changed outside session history"
                );
                let previous = edit
                    .original
                    .and_then(|id| self.world.state(id))
                    .context("original chest block is unavailable")?;
                ensure!(
                    previous.name == current.name
                        && matches!(
                            current.name.as_str(),
                            "minecraft:chest" | "minecraft:trapped_chest"
                        ),
                    "chest block type changed"
                );
                previous
            } else {
                current
            };
            let source = sections
                .iter()
                .find(|s| s.y == section_y)
                .and_then(|s| s.blocks.as_ref())
                .and_then(|blocks| {
                    blocks.block(
                        p.x.rem_euclid(16) as usize,
                        p.y.rem_euclid(16) as usize,
                        p.z.rem_euclid(16) as usize,
                    )
                })
                .context("source chest block is unavailable")?;
            ensure!(
                source.name.matches(&original_state.name),
                "source chest block differs"
            );
            if source.properties.is_empty() {
                ensure!(
                    original_state.properties.len() == 3
                        && original_state
                            .properties
                            .get("facing")
                            .is_some_and(|v| v == "north")
                        && original_state
                            .properties
                            .get("type")
                            .is_some_and(|v| v == "single")
                        && original_state
                            .properties
                            .get("waterlogged")
                            .is_some_and(|v| v == "false"),
                    "source default chest state differs"
                );
            } else {
                ensure!(
                    source.properties.len() == original_state.properties.len()
                        && source.properties.iter().all(|(key, value)| original_state
                            .properties
                            .iter()
                            .any(|(k, v)| key.matches(k) && value.matches(v))),
                    "source chest state differs"
                );
            }
            if let Some(trace) = chest.loot_trace() {
                let proof = (|| -> anyhow::Result<_> {
                    let table = match trace {
                        crate::saved_chest::LootRandomTrace::Fixed { table, .. }
                        | crate::saved_chest::LootRandomTrace::Named { table, .. }
                        | crate::saved_chest::LootRandomTrace::Level { table, .. } => table,
                    };
                    let loot = self
                        .chest_loot
                        .as_ref()
                        .and_then(|tables| tables.get(table))
                        .context("chest loot table is unavailable")?;
                    let registry = self
                        .item_registry
                        .as_ref()
                        .context("item registry is unavailable")?;
                    chest.verify_generated_loot(table, loot, |item| {
                        Self::resolve_chest_loot_item(item, registry)
                    })?;
                    let resolve = |item: &native_resources::chest_loot::ChestLootItem| {
                        crate::saved_chest::loot_prototype(&Self::resolve_chest_loot_item(
                            item, registry,
                        )?)
                    };
                    match trace {
                        crate::saved_chest::LootRandomTrace::Fixed { luck, .. } => match luck {
                            Some(bits) => {
                                native_persistence::chest_loot::VerifiedChestLoot::replay_with_luck(
                                    chest.source(),
                                    table,
                                    loot,
                                    f32::from_bits(*bits),
                                    resolve,
                                )
                            }
                            None => native_persistence::chest_loot::VerifiedChestLoot::replay(
                                chest.source(),
                                table,
                                loot,
                                resolve,
                            ),
                        },
                        crate::saved_chest::LootRandomTrace::Named { before, luck, .. } => {
                            let seed = self
                                .random_sequences
                                .as_ref()
                                .context("world random sequences are unavailable")?
                                .world_seed;
                            match luck {
                                Some(bits) => native_persistence::chest_loot::VerifiedChestLoot::replay_named_with_luck(chest.source(), table, loot, seed, *before, f32::from_bits(*bits), resolve),
                                None => native_persistence::chest_loot::VerifiedChestLoot::replay_named(chest.source(), table, loot, seed, *before, resolve),
                            }
                        }
                        crate::saved_chest::LootRandomTrace::Level { .. } => anyhow::bail!(
                            "level-random chest loot requires a complete world-random audit"
                        ),
                    }
                })();
                match proof {
                    Ok(proof) => proofs.push(proof),
                    Err(_) => loot_verifiable = false,
                }
            }
            changes.push(BlockEntityMutation {
                expected: Some(chest.source().clone()),
                replacement: Some(edited),
            });
        }
        let inventory_changes: Vec<_> = changes
            .iter()
            .filter_map(|change| {
                Some(native_persistence::edit::BlockEntityChange {
                    expected: change.expected.clone()?,
                    replacement: change.replacement.clone()?,
                })
            })
            .collect();
        if !loot_verifiable
            || inventory_changes.len() != changes.len()
            || draft
                .stage_checked_chest_inventories_with_loot(&inventory_changes, &proofs)
                .is_err()
        {
            draft.stage_block_entity_mutations(&changes)?;
        }
        Ok(())
    }

    /// Include created and destroyed chests in the same partial draft as their
    /// block changes. This still cannot authorize a playable-world write.
    fn stage_chest_lifecycle(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
        draft: &mut native_persistence::edit::ChunkDraft,
    ) -> anyhow::Result<()> {
        use anyhow::{Context, ensure};
        use native_persistence::edit::BlockEntityMutation;
        let keys: BTreeSet<_> = self
            .placed_chests
            .iter()
            .chain(&self.removed_chests)
            .copied()
            .filter(|(x, _, z)| x.div_euclid(16) == position.x && z.div_euclid(16) == position.z)
            .collect();
        if keys.is_empty() {
            return Ok(());
        }
        ensure!(
            !matches!(self.inventory.menu(), Some(InventoryMenu::Chest { position: p, other }) if [Some(p), other].into_iter().flatten().any(|p| p.x.div_euclid(16) == position.x && p.z.div_euclid(16) == position.z)),
            "chest inventory is still open"
        );
        ensure!(
            draft.matches_source(original)?,
            "chunk draft source differs"
        );
        let payload = self
            .world
            .saved_block_entities
            .get(&position)
            .context("chest source block entities are unavailable")?;
        let edits = self
            .block_edits
            .get(&position)
            .context("chest lifecycle block edits are unavailable")?;
        let mut changes = Vec::new();
        for key @ (x, y, z) in keys {
            let edit = edits
                .get(&key)
                .context("chest lifecycle block edit is unavailable")?;
            let current = self
                .world
                .state(edit.current)
                .context("chest block state is unavailable")?;
            let source = crate::saved_chest::read(payload, position, IVec3::new(x, y, z))?;
            let expected = if self.removed_chests.contains(&key) {
                Some(
                    source
                        .context("removed chest source is missing")?
                        .source()
                        .clone(),
                )
            } else {
                ensure!(
                    source.is_none(),
                    "new chest position already has a block entity"
                );
                None
            };
            let replacement = if self.placed_chests.contains(&key) {
                let chest = self
                    .chest_contents
                    .get(&key)
                    .context("placed chest data is unavailable")?;
                ensure!(
                    matches!(
                        current.name.as_str(),
                        "minecraft:chest" | "minecraft:trapped_chest"
                    ) && matches!(chest.source().get("id"), Some(native_persistence::nbt::Tag::String(id)) if id.matches(&current.name)),
                    "placed chest block and entity differ"
                );
                Some(chest.draft_inventory(&chest.slots)?)
            } else {
                ensure!(
                    !matches!(
                        current.name.as_str(),
                        "minecraft:chest" | "minecraft:trapped_chest"
                    ),
                    "removed chest block is still present"
                );
                None
            };
            changes.push(BlockEntityMutation {
                expected,
                replacement,
            });
        }
        draft.stage_block_entity_mutations(&changes)
    }

    fn stage_banner_lifecycle(
        &self,
        position: ChunkPos,
        original: &native_persistence::nbt::NamedTag,
        draft: &mut native_persistence::edit::ChunkDraft,
    ) -> anyhow::Result<()> {
        use anyhow::{Context, ensure};
        use native_persistence::edit::BlockEntityMutation;
        let mut changes = Vec::new();
        let keys: BTreeSet<_> = self
            .placed_banners
            .keys()
            .chain(self.removed_banners.keys())
            .copied()
            .collect();
        for (x, y, z) in keys {
            if x.div_euclid(16) != position.x || z.div_euclid(16) != position.z {
                continue;
            }
            ensure!(
                draft.matches_source(original)?,
                "chunk draft source differs"
            );
            let edit = self
                .block_edits
                .get(&position)
                .and_then(|edits| edits.get(&(x, y, z)))
                .context("banner block edit is unavailable")?;
            let state = self
                .world
                .state(edit.current)
                .context("banner state is unavailable")?;
            let replacement = self.placed_banners.get(&(x, y, z)).cloned();
            ensure!(
                native_world::collision::banner_item_id(state).is_some() == replacement.is_some(),
                "banner block and entity differ"
            );
            changes.push(BlockEntityMutation {
                expected: self.removed_banners.get(&(x, y, z)).cloned(),
                replacement,
            });
        }
        draft.stage_block_entity_mutations(&changes)
    }

    /// Chunks whose blocks, chest inventories, or modeled scheduled ticks changed.
    /// The set is retained until a coordinated world save acknowledges it.
    pub fn dirty_chunk_positions(&self) -> BTreeSet<ChunkPos> {
        self.dirty_chunks
            .union(&self.tick_dirty_chunks)
            .copied()
            .chain(self.chest_dirty_chunks.iter().copied())
            .collect()
    }

    fn mark_tick_chunk_dirty(&mut self, x: i32, z: i32) {
        self.tick_dirty_chunks.insert(ChunkPos {
            x: x.div_euclid(16),
            z: z.div_euclid(16),
        });
    }

    /// The first world tick changes the serialized delay of saved schedules.
    /// Track only chunks whose original scheduled ticks have not advanced yet.
    fn mark_advanced_saved_tick_chunks_dirty(&mut self) {
        self.tick_dirty_chunks
            .append(&mut self.tick_chunks_needing_dirty);
    }

    fn has_unsaved_chunk_changes(&self, position: ChunkPos) -> bool {
        self.dirty_chunks.contains(&position)
            || self.tick_dirty_chunks.contains(&position)
            || self.tick_chunks_needing_dirty.contains(&position)
            || self.chest_dirty_chunks.contains(&position)
            || matches!(self.inventory.menu(), Some(InventoryMenu::Chest { position: p, other }) if [Some(p), other].into_iter().flatten().any(|p| p.x.div_euclid(16) == position.x && p.z.div_euclid(16) == position.z))
    }

    // Activated entity data is the source for drafts even when its terrain is
    // no longer resident. Empty chunks only need retaining when occupied.
    fn retain_entity_chunk(&self, pos: ChunkPos) -> bool {
        let occupied = || {
            self.dropped_items.has_in_chunk(pos)
                || self.experience_orbs.has_in_chunk(pos)
                || self.falling_sand.iter().any(|entity| {
                    let at = entity.motion.position.floor().as_ivec3();
                    at.x.div_euclid(16) == pos.x && at.z.div_euclid(16) == pos.z
                })
        };
        match self.entity_chunks.get(&pos) {
            Some(SavedEntityData::Present(chunk)) => {
                (self.item_chunks_seen.contains(&pos) && !chunk.entities().is_empty()) || occupied()
            }
            Some(SavedEntityData::Empty) => occupied(),
            _ => false,
        }
    }

    pub fn set_game_mode(&mut self, mode: GameMode) {
        self.mining.release();
        self.game_mode = mode;
        if mode == GameMode::Spectator {
            self.flight.flying = true;
        } else if mode != GameMode::Creative {
            self.flight.flying = false;
        }
        Arc::make_mut(&mut self.snapshot).game_mode = mode;
    }

    /// Visual setting applied when the camera next advances.
    pub fn set_fov_effect_scale(&mut self, scale: f32) {
        if scale.is_finite() {
            self.fov_effect_scale = scale.clamp(0.0, 1.0);
        }
    }

    pub fn set_sprint_window(&mut self, ticks: u8) {
        self.sprint_window = ticks.min(10);
    }

    pub fn set_game_master_permission(&mut self, allowed: bool) {
        self.mining.release();
        self.game_master_permission = allowed;
    }

    pub fn set_world_seed(&mut self, seed: Option<i64>) {
        self.world_seed = seed;
    }

    fn execute_time_command(
        &mut self,
        command: &crate::time_command::TimeCommand,
    ) -> crate::SystemMessageKind {
        use crate::{SystemMessageKind as Message, time_command::TimeAction};
        if !self.game_master_permission {
            return Message::TimePermissionDenied;
        }
        if command.action == TimeAction::QueryGameTime {
            return if command.clock.is_none() {
                Message::TimeGame(self.game_time)
            } else {
                Message::CommandUnavailable
            };
        }
        let id = if let Some(clock) = &command.clock {
            let id = native_persistence::world::DimensionId {
                namespace: clock.namespace.clone(),
                path: clock.path.clone(),
            };
            let Some(registered) = &self.registered_clocks else {
                return Message::CommandUnavailable;
            };
            if !registered.contains(&id) {
                return Message::TimeUnknownClock(format!("{}:{}", id.namespace, id.path).into());
            }
            id
        } else {
            let Some(default_clock) = &self.default_clock else {
                return Message::CommandUnavailable;
            };
            let Some(id) = default_clock else {
                return self
                    .clock_dimension_type
                    .clone()
                    .map_or(Message::CommandUnavailable, Message::TimeNoDefaultClock);
            };
            id.clone()
        };
        let name: Arc<str> = format!("{}:{}", id.namespace, id.path).into();
        if self
            .registered_clocks
            .as_ref()
            .is_some_and(|registered| !registered.contains(&id))
        {
            return Message::CommandUnavailable;
        }
        let can_save_clock = self.saved_clock_source.is_some();
        let selected_timeline = if let TimeAction::QueryTimeline { timeline, .. } = &command.action
        {
            let Some(timelines) = &self.timelines else {
                return Message::TimeTimelineDataUnavailable;
            };
            let timeline_name: Arc<str> =
                format!("{}:{}", timeline.namespace, timeline.path).into();
            let Some(definition) = timelines.get(timeline) else {
                return Message::TimeUnknownTimeline(timeline_name);
            };
            if definition.period.is_some_and(|period| period <= 0) {
                return Message::TimeTimelineDataUnavailable;
            }
            if definition.clock.namespace != id.namespace || definition.clock.path != id.path {
                return Message::TimeWrongTimeline {
                    clock: name,
                    timeline: timeline_name,
                };
            }
            Some((timeline_name, definition.period))
        } else {
            None
        };
        let selected_marker = if let TimeAction::SetMarker(marker) = &command.action {
            let Some(markers) = &self.time_markers else {
                return Message::TimeMarkerDataUnavailable;
            };
            let clock_id = native_resources::packs::ResourceId {
                namespace: id.namespace.clone(),
                path: id.path.clone(),
            };
            let marker_name: Arc<str> = format!("{}:{}", marker.namespace, marker.path).into();
            match markers.get(&(clock_id, marker.clone())) {
                Some(marker) => Some((marker_name, *marker)),
                None => {
                    return Message::TimeMarker {
                        name,
                        marker: marker_name,
                        already: false,
                        missing: true,
                    };
                }
            }
        } else {
            None
        };
        let Some(clock) = self.world_clocks.get_mut(&id) else {
            return Message::CommandUnavailable;
        };
        match &command.action {
            TimeAction::QueryGameTime => unreachable!(),
            TimeAction::QueryClock => Message::TimeClock {
                name,
                ticks: clock.total_ticks,
            },
            TimeAction::QueryTimeline { repetitions, .. } => {
                let (timeline, period) = selected_timeline.expect("timeline was resolved");
                Message::TimeTimeline {
                    name: timeline,
                    ticks: crate::time_command::timeline_value(
                        clock.total_ticks,
                        period,
                        *repetitions,
                    ),
                    repetitions: *repetitions,
                }
            }
            TimeAction::SetRate(bits) => {
                let rate = f32::from_bits(*bits);
                if !(0.00001..=1000.0).contains(&rate) {
                    return Message::CommandUnavailable;
                }
                let already = clock.rate == rate;
                if !already && !can_save_clock {
                    return Message::TimeSaveUnavailable;
                }
                clock.rate = rate;
                Message::TimeRate {
                    name,
                    rate_bits: *bits,
                    already,
                }
            }
            TimeAction::Set(ticks) if *ticks < 0 => Message::CommandUnavailable,
            TimeAction::Set(ticks) if clock.total_ticks == i64::from(*ticks) => {
                Message::TimeAlreadySet {
                    name,
                    ticks: *ticks,
                }
            }
            TimeAction::Set(ticks) => {
                if !can_save_clock {
                    return Message::TimeSaveUnavailable;
                }
                crate::time_command::set_clock(clock, *ticks);
                Message::TimeSet {
                    name,
                    ticks: clock.total_ticks,
                }
            }
            TimeAction::SetMarker(_) => {
                let (marker_name, marker) = selected_marker.expect("marker was resolved");
                let target = crate::time_command::resolve_marker(marker, clock.total_ticks);
                if let Some(target) = target {
                    if !can_save_clock {
                        return Message::TimeSaveUnavailable;
                    }
                    clock.total_ticks = target;
                    clock.partial_tick = 0.0;
                }
                Message::TimeMarker {
                    name,
                    marker: marker_name,
                    already: target.is_none(),
                    missing: false,
                }
            }
            TimeAction::Add(ticks) => {
                let result = clock.total_ticks.wrapping_add(i64::from(*ticks)).max(0);
                if result != clock.total_ticks && !can_save_clock {
                    return Message::TimeSaveUnavailable;
                }
                crate::time_command::add_clock(clock, *ticks);
                Message::TimeSet {
                    name,
                    ticks: clock.total_ticks,
                }
            }
            TimeAction::Pause | TimeAction::Resume => {
                let paused = command.action == TimeAction::Pause;
                let already = clock.paused == paused;
                if !already && !can_save_clock {
                    return Message::TimeSaveUnavailable;
                }
                clock.paused = paused;
                Message::TimePaused {
                    name,
                    paused,
                    already,
                }
            }
        }
    }

    pub fn set_default_clock(
        &mut self,
        dimension_type: Arc<str>,
        clock: Option<native_persistence::world::DimensionId>,
    ) {
        self.clock_dimension_type = Some(dimension_type);
        self.default_clock = Some(clock);
    }

    pub fn set_registered_clocks(
        &mut self,
        clocks: Arc<BTreeSet<native_persistence::world::DimensionId>>,
    ) {
        self.registered_clocks = Some(clocks);
    }

    pub fn set_timelines(
        &mut self,
        timelines: Arc<
            BTreeMap<
                native_resources::packs::ResourceId,
                native_resources::world_clock::TimelineDefinition,
            >,
        >,
    ) {
        self.timelines = Some(timelines);
    }

    pub fn set_time_markers(
        &mut self,
        markers: Arc<
            BTreeMap<
                (
                    native_resources::packs::ResourceId,
                    native_resources::packs::ResourceId,
                ),
                native_resources::world_clock::TimeMarker,
            >,
        >,
    ) {
        self.time_markers = Some(markers);
    }

    pub fn set_falling_fire_tag(&mut self, tag: Arc<BTreeSet<String>>) {
        self.falling_fire_tag = Some(tag);
        self.sand_deferred_revision = None;
    }

    pub fn set_snow_support_tags(
        &mut self,
        tags: Arc<native_resources::respawn_tags::SnowSupportTags>,
    ) {
        self.snow_support_tags = Some(tags);
    }

    pub fn set_snowy_tag(&mut self, tag: Arc<BTreeSet<String>>) {
        self.snowy_tag = Some(tag);
    }

    pub fn set_bounce_suppression_tag(&mut self, tag: Arc<BTreeSet<String>>) {
        self.bounce_suppression_tag = Some(tag);
    }

    pub fn set_farmland_maintainers(&mut self, tag: Arc<BTreeSet<String>>) {
        self.farmland_maintainers = Some(tag);
        self.soil_deferred_revision = None;
    }

    pub fn set_farmland_water_tag(&mut self, tag: Arc<BTreeSet<String>>) {
        let bits = [
            "minecraft:empty",
            "minecraft:water",
            "minecraft:flowing_water",
            "minecraft:lava",
            "minecraft:flowing_lava",
        ]
        .into_iter()
        .enumerate()
        .fold(0_u8, |bits, (index, name)| {
            bits | (u8::from(tag.contains(name)) << index)
        });
        self.farmland_water_tag = Some(bits);
    }

    /// Unknown dimension or weather data prevents speculative precipitation decisions.
    pub fn set_weather(
        &mut self,
        can_have_weather: Option<bool>,
        data: Option<native_persistence::world::SavedWeather>,
        advance_weather: bool,
    ) {
        self.can_have_weather = can_have_weather;
        self.weather_tick_order.clear();
        if can_have_weather == Some(true) {
            self.weather_tick_order.push(WeatherTickLevel::Current);
        }
        self.weather = data.map(crate::weather::Weather::new);
        self.weather_source = None;
        self.advance_weather = advance_weather;
        let visual = self.weather_visual();
        Arc::make_mut(&mut self.snapshot).weather = visual;
    }

    /// Install the server's weather-capable level order; each other level has
    /// its own random source, independent of the player's current level.
    pub fn set_weather_tick_order(&mut self, current_levels: &[bool]) -> Result<(), &'static str> {
        if self.tick != 0 || self.accumulated != Duration::ZERO {
            return Err("weather tick order must be set before simulation begins");
        }
        let current_count = current_levels.iter().filter(|&&current| current).count();
        if current_count != usize::from(self.can_have_weather == Some(true)) {
            return Err("weather tick order does not match the current dimension");
        }
        self.weather_tick_order = current_levels
            .iter()
            .map(|&current| {
                if current {
                    WeatherTickLevel::Current
                } else {
                    WeatherTickLevel::Background(native_core::random::LegacyRandom::new(
                        fresh_breathing_seed(),
                    ))
                }
            })
            .collect();
        Ok(())
    }

    /// Capture the exact document (or its absence) before any weather ticks.
    pub fn capture_weather_source(
        &mut self,
        source: Option<&native_persistence::nbt::NamedTag>,
    ) -> anyhow::Result<()> {
        anyhow::ensure!(
            self.tick == 0 && self.accumulated == Duration::ZERO,
            "weather source must be captured before simulation begins"
        );
        anyhow::ensure!(
            self.weather_source.is_none(),
            "weather source was already captured"
        );
        let expected = source
            .map(native_persistence::world::parse_weather_data)
            .transpose()?
            .unwrap_or_default();
        anyhow::ensure!(
            self.weather
                .as_ref()
                .is_some_and(|weather| weather.data == expected),
            "weather source differs from the initialized state"
        );
        self.weather_source = Some(source.cloned());
        Ok(())
    }

    fn weather_visual(&self) -> Option<crate::weather::WeatherVisual> {
        match self.can_have_weather? {
            false => Some(crate::weather::WeatherVisual::default()),
            true => self.weather.as_ref().map(crate::weather::Weather::visual),
        }
    }

    fn weather_terrain(&self) -> Option<crate::weather::WeatherTerrain> {
        Some(crate::weather::WeatherTerrain {
            heightmaps: Arc::clone(&self.spawn_heightmaps),
            climates: Arc::clone(self.biome_climates.as_ref()?),
            sea_level: self.generator_sea_level,
            has_skylight: self.sky_lighting.capability(),
            min_y: self.bounds.min_y,
            max_y: self.bounds.max_y,
        })
    }

    /// Publish the initial heightmap set after the world-loading worker has
    /// finished preparing its chunks, avoiding a map clone per loaded chunk.
    pub fn publish_initial_weather_terrain(&mut self) -> Result<(), &'static str> {
        if self.tick != 0 || self.accumulated != Duration::ZERO {
            return Err("initial weather terrain must be published before simulation begins");
        }
        let terrain = self.weather_terrain();
        Arc::make_mut(&mut self.snapshot).weather_terrain = terrain;
        Ok(())
    }

    pub fn set_initial_game_time(&mut self, value: i64) -> Result<(), &'static str> {
        if self.tick != 0 || self.accumulated != Duration::ZERO {
            return Err("game time must be restored before simulation begins");
        }
        self.game_time = value;
        self.initial_game_time_set = true;
        self.level_time_source = None;
        Arc::make_mut(&mut self.snapshot).game_time = value;
        Ok(())
    }

    /// Capture the original level.dat document before advancing the session.
    pub fn capture_level_time_source(
        &mut self,
        source: Arc<native_persistence::nbt::NamedTag>,
    ) -> anyhow::Result<()> {
        anyhow::ensure!(
            self.tick == 0 && self.accumulated == Duration::ZERO,
            "level source must be captured before simulation begins"
        );
        anyhow::ensure!(
            self.initial_game_time_set && self.level_time_source.is_none(),
            "initial level time is not ready or source was already captured"
        );
        let time = native_persistence::world::WorldReader::validate_level_game_time(&source)?;
        anyhow::ensure!(
            time == self.game_time,
            "level source differs from the initialized time"
        );
        self.level_time_source = Some(source);
        Ok(())
    }

    fn global_rain(&self) -> Option<bool> {
        match self.can_have_weather? {
            false => Some(false),
            true => self
                .weather
                .as_ref()
                .map(|weather| weather.is_raining(true)),
        }
    }

    pub fn set_precipitation_environment(
        &mut self,
        climates: Arc<BTreeMap<String, native_resources::biome_climate::BiomeClimate>>,
        sea_level: Option<i32>,
    ) {
        self.biome_climates = Some(climates);
        self.generator_sea_level = sea_level;
    }

    /// Level.isRainingAt checks the sky, motion-blocking height and biome.
    /// Unknown or pending light and missing biome data are never guessed.
    fn rain_at(&self, relative: IVec3) -> Option<bool> {
        RainView {
            raining: self.global_rain(),
            origin: self.origin,
            world: &self.world,
            light_current: self.sky_lighting.is_current(),
            heightmaps: &self.spawn_heightmaps,
            climates: self.biome_climates.as_deref(),
            sea_level: self.generator_sea_level,
        }
        .at(relative)
    }

