    #[test]
    fn loaded_weather_advances_before_block_ticks_and_honors_the_game_rule() {
        let mut session = session();
        let data = native_persistence::world::SavedWeather {
            rain_time: 1,
            thunder_time: 100,
            ..Default::default()
        };
        session.set_weather(Some(true), Some(data), true);
        session.set_random_tick_speed(0);
        session.update(TICK);
        let weather = session.weather.as_ref().unwrap();
        assert!(weather.data.raining);
        assert_eq!(weather.data.rain_time, 0);
        assert_eq!(weather.rain_level, 0.01_f32);
        assert_eq!(session.global_rain(), Some(false));
        for _ in 0..20 {
            session.update(TICK);
        }
        assert_eq!(session.global_rain(), Some(true));

        session.set_weather(Some(true), Some(data), false);
        session.update(TICK);
        assert_eq!(session.weather.as_ref().unwrap().data, data);
        assert_eq!(session.global_rain(), Some(false));
    }

    #[test]
    fn shared_weather_follows_level_order_without_changing_other_visuals() {
        use native_persistence::world::SavedWeather;
        let data = SavedWeather {
            rain_time: 2,
            thunder_time: 100,
            ..Default::default()
        };
        let mut nether = session();
        nether.set_weather(Some(false), Some(data), true);
        assert!(nether.set_weather_tick_order(&[false]).is_ok());
        nether.set_random_tick_speed(0);
        nether.update(TICK);
        assert_eq!(nether.weather.as_ref().unwrap().data.rain_time, 1);
        assert_eq!(
            nether.weather_visual(),
            Some(crate::weather::WeatherVisual::default())
        );
        assert!(nether.set_weather_tick_order(&[false]).is_err());

        let mut before = session();
        before.set_weather(Some(true), Some(data), true);
        assert!(before.set_weather_tick_order(&[false, true]).is_ok());
        before.set_random_tick_speed(0);
        before.update(TICK);
        assert!(before.weather.as_ref().unwrap().data.raining);
        assert_eq!(before.weather_visual().unwrap().rain, 0.01);

        let mut after = session();
        after.set_weather(Some(true), Some(data), true);
        assert!(after.set_weather_tick_order(&[true, false]).is_ok());
        after.set_random_tick_speed(0);
        after.update(TICK);
        assert!(after.weather.as_ref().unwrap().data.raining);
        assert_eq!(after.weather_visual().unwrap().rain, 0.0);
        assert!(self::session().set_weather_tick_order(&[true]).is_err());
    }

    #[test]
    fn weather_snapshots_are_immutable_and_independent_of_frame_rate() {
        let mut fast = session();
        let mut slow = session();
        let weather = native_persistence::world::SavedWeather {
            rain_time: 1,
            thunder_time: 1,
            ..Default::default()
        };
        for session in [&mut fast, &mut slow] {
            session.set_initial_game_time(i64::MAX).unwrap();
            session.set_weather(Some(true), Some(weather), true);
            session.set_random_tick_speed(0);
        }
        let before = fast.snapshot();
        for _ in 0..20 {
            fast.update(Duration::from_millis(5));
        }
        slow.update(Duration::from_millis(100));
        assert_eq!(fast.snapshot().weather, slow.snapshot().weather);
        assert_eq!(before.weather.unwrap().rain, 0.0);
        let visual = fast.snapshot().weather.unwrap();
        assert_eq!(fast.snapshot().game_time, i64::MIN + 1);
        assert_eq!(before.game_time, i64::MAX);
        assert!(fast.set_initial_game_time(0).is_err());
        assert_eq!(visual.previous_rain, 0.01);
        assert_eq!(visual.rain, 0.02);
        fast.set_weather(None, None, true);
        assert_eq!(fast.snapshot().weather, None);
        fast.set_weather(Some(false), None, true);
        assert_eq!(
            fast.snapshot().weather,
            Some(crate::weather::WeatherVisual::default())
        );
    }

    #[test]
    fn weather_snapshot_reports_configured_skylight_capability() {
        let mut session = session();
        session.set_precipitation_environment(Arc::new(BTreeMap::new()), None);
        session.publish_initial_weather_terrain().unwrap();
        let unknown = session.snapshot();
        assert_eq!(unknown.weather_terrain.as_ref().unwrap().has_skylight, None);
        session.set_has_skylight(false).unwrap();
        session.publish_initial_weather_terrain().unwrap();
        let no_sky = session.snapshot();
        assert_eq!(
            no_sky.weather_terrain.as_ref().unwrap().has_skylight,
            Some(false)
        );
        session.set_has_skylight(true).unwrap();
        session.publish_initial_weather_terrain().unwrap();
        assert_eq!(
            session
                .snapshot()
                .weather_terrain
                .as_ref()
                .unwrap()
                .has_skylight,
            Some(true)
        );
        assert_eq!(unknown.weather_terrain.as_ref().unwrap().has_skylight, None);
        assert_eq!(
            no_sky.weather_terrain.as_ref().unwrap().has_skylight,
            Some(false)
        );
    }

    #[test]
    fn weather_terrain_shares_unchanged_heightmaps_and_preserves_old_snapshots() {
        use native_resources::biome_climate::{BiomeClimate, TemperatureModifier};
        let mut session = session();
        let home = session.player_chunk().unwrap();
        session
            .set_spawn_heightmap_tags(test_heightmap_tags())
            .unwrap();
        session
            .prepare_initial_spawn_heightmaps(&saved_heightmap_chunk(home, None))
            .unwrap();
        session.set_precipitation_environment(
            Arc::new(BTreeMap::from([(
                "minecraft:plains".into(),
                BiomeClimate {
                    has_precipitation: true,
                    temperature: 0.8,
                    modifier: TemperatureModifier::None,
                },
            )])),
            Some(63),
        );
        session.publish_initial_weather_terrain().unwrap();
        let before = session.snapshot();
        let prior = before.weather_terrain.as_ref().unwrap();
        session.set_random_tick_speed(0);
        session.update(TICK);
        let unchanged = session.snapshot();
        assert!(Arc::ptr_eq(
            &prior.heightmaps,
            &unchanged.weather_terrain.as_ref().unwrap().heightmaps
        ));
        let x = session.origin.x + 8;
        let z = session.origin.z + 8;
        let old_height = prior.heightmaps[&home]
            .highest(SpawnHeightmapKind::MotionBlocking, x, z)
            .unwrap();
        let stone = session.intern_block(state("minecraft:stone", &[]));
        assert!(session.set(IVec3::new(8, 5, 8), stone));
        session.update(TICK);
        let after = session.snapshot();
        let current = after.weather_terrain.as_ref().unwrap();
        assert!(!Arc::ptr_eq(&prior.heightmaps, &current.heightmaps));
        assert_eq!(
            prior.heightmaps[&home].highest(SpawnHeightmapKind::MotionBlocking, x, z),
            Some(old_height)
        );
        assert_eq!(
            current.heightmaps[&home].highest(SpawnHeightmapKind::MotionBlocking, x, z),
            Some(5)
        );
    }

    #[test]
    fn rain_requires_known_sky_height_and_zoomed_biome() {
        use native_resources::biome_climate::{BiomeClimate, TemperatureModifier};
        let mut session = session();
        let chunk_pos = session.player_chunk().unwrap();
        {
            let world = Arc::make_mut(&mut session.world);
            let biome = world.intern_biome("minecraft:plains".into());
            let chunk = Arc::make_mut(world.chunks.get_mut(&chunk_pos).unwrap());
            chunk.block_light_correct = true;
            let section = Arc::make_mut(chunk.sections.get_mut(&0).unwrap());
            section.sky_light = Some(Box::new([0xff; LIGHT_BYTES]));
            section.biomes = Some(Box::new([biome; native_world::loaded::BIOME_COUNT]));
        }
        let soil = IVec3::new(8, 3, 8);
        let farmland = session.intern_block(state("minecraft:farmland", &[("moisture", "2")]));
        {
            let world = Arc::make_mut(&mut session.world);
            let chunk = Arc::make_mut(world.chunks.get_mut(&chunk_pos).unwrap());
            let section = Arc::make_mut(chunk.sections.get_mut(&0).unwrap());
            section.blocks.as_mut().unwrap()[8 + 8 * 16 + 3 * 256] = farmland;
        }
        session
            .set_spawn_heightmap_tags(test_heightmap_tags())
            .unwrap();
        session
            .prepare_initial_spawn_heightmaps(&saved_heightmap_chunk(chunk_pos, None))
            .unwrap();
        session.set_has_skylight(true).unwrap();
        session.set_weather(
            Some(true),
            Some(native_persistence::world::SavedWeather {
                raining: true,
                ..Default::default()
            }),
            false,
        );
        let climate = BiomeClimate {
            has_precipitation: true,
            temperature: 0.8,
            modifier: TemperatureModifier::None,
        };
        let configure = |session: &mut LoadedSession, climate, sea| {
            session.set_precipitation_environment(
                Arc::new(BTreeMap::from([("minecraft:plains".into(), climate)])),
                sea,
            );
        };
        configure(&mut session, climate, Some(63));
        let pos = IVec3::new(8, 4, 8);
        assert_eq!(session.rain_at(pos), None, "biome zoom seed is required");
        Arc::make_mut(&mut session.world).set_biome_world_seed(Some(42));
        assert_eq!(session.rain_at(pos), Some(true));
        assert_eq!(
            session.rain_at(IVec3::new(8, 2, 6)),
            Some(false),
            "motion-blocking height obstructs rain"
        );
        configure(
            &mut session,
            BiomeClimate {
                temperature: 0.0,
                ..climate
            },
            Some(63),
        );
        assert_eq!(
            session.rain_at(pos),
            Some(false),
            "snow does not hydrate farmland"
        );
        configure(
            &mut session,
            BiomeClimate {
                has_precipitation: false,
                ..climate
            },
            None,
        );
        assert_eq!(
            session.rain_at(pos),
            Some(false),
            "dry biome needs no sea level"
        );
        configure(&mut session, climate, None);
        assert_eq!(
            session.rain_at(pos),
            None,
            "unknown sea level is not guessed"
        );
        {
            let world = Arc::make_mut(&mut session.world);
            let chunk = Arc::make_mut(world.chunks.get_mut(&chunk_pos).unwrap());
            Arc::make_mut(chunk.sections.get_mut(&0).unwrap()).sky_light =
                Some(Box::new([0; LIGHT_BYTES]));
        }
        assert_eq!(session.rain_at(pos), Some(false), "blocked sky is dry");
        Arc::make_mut(
            Arc::make_mut(&mut session.world)
                .chunks
                .get_mut(&chunk_pos)
                .unwrap(),
        )
        .block_light_correct = false;
        assert_eq!(session.rain_at(pos), None, "uncertain light is not used");
        {
            let world = Arc::make_mut(&mut session.world);
            let chunk = Arc::make_mut(world.chunks.get_mut(&chunk_pos).unwrap());
            chunk.block_light_correct = true;
            Arc::make_mut(chunk.sections.get_mut(&0).unwrap()).sky_light =
                Some(Box::new([0xff; LIGHT_BYTES]));
        }
        configure(&mut session, climate, Some(63));
        assert!(session.random_tick_farmland_at(soil));
        let soil_state = session
            .world
            .block(session.origin.x + soil.x, soil.y, session.origin.z + soil.z)
            .unwrap();
        assert_eq!(
            soil_state.properties.get("moisture").map(String::as_str),
            Some("7")
        );
        assert_eq!(
            session.rain_at(pos),
            None,
            "pending sky-light work is not trusted"
        );
    }

    #[test]
    fn player_break_waits_for_neighbor_before_dropping_boundary_banner() {
        use native_persistence::nbt::{self, NamedTag, Tag, TagType};
        use native_resources::{loot::BlockLootTables, packs::ResourceProvider};
        use native_world::loaded::SavedBlockEntities;
        struct Loot;
        impl ResourceProvider for Loot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok((path == "data/minecraft/loot_table/blocks/white_banner.json").then(|| br#"{"type":"minecraft:block","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:white_banner","modifier":{"type":"minecraft:copy_components","source":"block_entity","include":["minecraft:custom_name"]}}]}]}"#.to_vec()))
            }
        }
        let (mut world, origin, mut player) = fixture();
        player.position = Vec3::new(15.5, 1.0, 6.5);
        let home = ChunkPos {
            x: origin.x.div_euclid(16),
            z: origin.z.div_euclid(16),
        };
        let east = ChunkPos {
            x: home.x + 1,
            z: home.z,
        };
        let mut adjacent = (*world.chunks[&home]).clone();
        adjacent.position = east;
        world.chunks.insert(east, Arc::new(adjacent));
        let support = origin + IVec3::new(15, 2, 4);
        let banner = support + IVec3::X;
        let stone = world.intern_state(state("minecraft:stone", &[]));
        world
            .set_block_id(support.x, support.y, support.z, stone)
            .unwrap();
        let banner_id =
            world.intern_state(state("minecraft:white_wall_banner", &[("facing", "east")]));
        world
            .set_block_id(banner.x, banner.y, banner.z, banner_id)
            .unwrap();
        let entity = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:banner".into())),
            ("x".into(), Tag::Int(banner.x)),
            ("y".into(), Tag::Int(banner.y)),
            ("z".into(), Tag::Int(banner.z)),
            ("CustomName".into(), Tag::String("Boundary".into())),
        ]);
        let bytes = nbt::write(&NamedTag {
            name: "".into(),
            value: Tag::List {
                element_type: TagType::Compound,
                values: vec![entity.clone()],
            },
        })
        .unwrap();
        world
            .saved_block_entities
            .insert(east, SavedBlockEntities::Encoded(bytes.into()));
        let incoming = world.clone();
        world.chunks.remove(&east);
        world.saved_block_entities.remove(&east);
        let mut session = LoadedSession::new(
            world,
            origin,
            BuildBounds {
                min_y: 0,
                max_y: 32,
            },
            player,
        )
        .unwrap();
        session.set_game_mode(GameMode::Creative);
        session.set_block_loot(Arc::new(BlockLootTables::load(&mut Loot).unwrap()));

        assert_eq!(session.ray_hit().unwrap().position, IVec3::new(15, 2, 4));
        session.submit_command(PlayerCommand::Break);
        session.update(TICK);
        assert_eq!(
            session
                .world
                .block(support.x, support.y, support.z)
                .unwrap()
                .name,
            "minecraft:stone"
        );
        assert!(session.dropped_items.snapshot().is_empty());
        assert!(session.removed_banners.is_empty());

        session.queue_chunk_window(home, 1);
        session.queue_loaded_chunk(east, incoming);
        session.apply_streaming();
        for _ in 0..10 {
            session.update(TICK);
            if session
                .world
                .block(support.x, support.y, support.z)
                .unwrap()
                .name
                == "minecraft:air"
            {
                break;
            }
        }
        assert_eq!(
            session
                .world
                .block(support.x, support.y, support.z)
                .unwrap()
                .name,
            "minecraft:air"
        );
        assert_eq!(
            session
                .world
                .block(banner.x, banner.y, banner.z)
                .unwrap()
                .name,
            "minecraft:air"
        );
        assert_eq!(
            session.removed_banners[&(banner.x, banner.y, banner.z)],
            entity
        );
        let drops = session.dropped_items.snapshot();
        assert_eq!(drops.len(), 1);
        assert_eq!(
            drops[0].stack.components().get("minecraft:custom_name"),
            Some(&Tag::String("Boundary".into()))
        );
    }

