    #[test]
    #[cfg(target_os = "windows")]
    #[ignore = "requires Minecraft 26.3 and Java 25 JDK"]
    fn falling_entity_placement_collisions_match_java() {
        use std::{path::PathBuf, process::Command};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        native_resources::packs::ResourceStack::open(&game).unwrap();
        let temp = tempfile::tempdir().unwrap();
        let version = game.join("versions/26.3");
        let manifest: serde_json::Value =
            serde_json::from_slice(&std::fs::read(version.join("26.3.json")).unwrap()).unwrap();
        let mut paths = vec![version.join("26.3.jar"), temp.path().to_path_buf()];
        for library in manifest["libraries"].as_array().unwrap() {
            if let Some(path) = library["downloads"]["artifact"]["path"].as_str() {
                let path = game.join("libraries").join(path);
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
        let cp = std::env::join_paths(paths).unwrap();
        let java = std::env::var_os("MINECRAFT_JAVA_HOME").or_else(|| std::env::var_os("JAVA_HOME")).map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from(std::env::var_os("USERPROFILE").unwrap()).join("AppData/Local/Packages/Microsoft.4297127D64EC6_8wekyb3d8bbwe/LocalCache/Local/runtime/java-runtime-epsilon/windows-x64/java-runtime-epsilon")).join("bin");
        let source = temp.path().join("FallingPlacementCollisionOracle.java");
        let output = temp.path().join("collisions.json");
        std::fs::write(
            &source,
            include_str!("../tests/java/FallingPlacementCollisionOracle.java"),
        )
        .unwrap();
        for command in [
            Command::new(java.join("javac.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg(&source),
            Command::new(java.join("java.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg("FallingPlacementCollisionOracle")
                .arg(&output),
        ] {
            let result = command.output().unwrap();
            assert!(
                result.status.success(),
                "falling collision oracle failed:\n{}\n{}",
                String::from_utf8_lossy(&result.stdout),
                String::from_utf8_lossy(&result.stderr)
            );
        }
        let rows: Vec<serde_json::Value> =
            serde_json::from_slice(&std::fs::read(output).unwrap()).unwrap();
        assert_eq!(rows.len(), 10 * 2 * 12 * 9);
        let mut session = session();
        session.origin = IVec3::ZERO;
        for row in rows {
            let block = row["block"].as_u64().unwrap();
            let state = match block {
                0 => state("minecraft:stone", &[]),
                9 => state(
                    "minecraft:chest",
                    &[
                        ("type", "single"),
                        ("facing", "north"),
                        ("waterlogged", "false"),
                    ],
                ),
                _ => state("minecraft:snow", &[("layers", &block.to_string())]),
            };
            let shape = block_shape(&state).unwrap();
            let position = DVec3::new(row["x"].as_f64().unwrap(), row["y"].as_f64().unwrap(), 0.5);
            let motion = crate::falling_block::AirborneMotion {
                position,
                velocity: DVec3::ZERO,
                age: 0,
                no_gravity: false,
            };
            session.falling_sand.clear();
            session.falling_sand.push(FallingSand {
                motion,
                previous: position,
                fall_distance: 0.0,
                fall_distance_verified: true,
                kind: FallingKind::Sand,
                drop_item: true,
                cancel_drop: false,
                on_ground: false,
                source: if row["fresh"].as_bool().unwrap() {
                    None
                } else {
                    Some(Arc::new(native_persistence::nbt::Tag::Compound(vec![])))
                },
                created: None,
            });
            assert_eq!(
                session.falling_blocks_clear_placement(IVec3::ZERO, &shape),
                row["clear"].as_bool().unwrap(),
                "{row}"
            );
        }
    }

    #[test]
    fn created_falling_block_prevents_player_placement() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        for fresh in [false, true] {
            let mut session = session();
            let target = IVec3::new(8, 2, 7);
            let position = (session.origin + target).as_dvec3() + DVec3::new(0.5, 0.0, 0.5);
            let motion = crate::falling_block::AirborneMotion {
                position,
                velocity: DVec3::ZERO,
                age: 1,
                no_gravity: true,
            };
            session.falling_sand.push(FallingSand {
                motion,
                previous: position,
                fall_distance: 0.0,
                fall_distance_verified: true,
                kind: FallingKind::Sand,
                drop_item: true,
                cancel_drop: false,
                on_ground: false,
                source: if fresh {
                    None
                } else {
                    Some(Arc::new(Tag::Compound(vec![])))
                },
                created: None,
            });
            let mut inventory = PlayerInventory::default();
            assert!(inventory.set_slot(
                PlayerSlot::Storage(0),
                ItemStack::new("minecraft:stone".into(), 2, 64, Tag::Compound(vec![]))
            ));
            session.set_player_inventory(inventory);
            session.submit_command(PlayerCommand::Place);
            session.update(TICK);
            let Cell::State(id) = cell(
                &session.world,
                session.origin,
                session.bounds,
                target,
                session.states[0],
            ) else {
                panic!("missing target")
            };
            assert_eq!(
                session.world.state(id).unwrap().name,
                if fresh {
                    "minecraft:air"
                } else {
                    "minecraft:stone"
                }
            );
            assert_eq!(
                session
                    .inventory
                    .slot(PlayerSlot::Storage(0))
                    .unwrap()
                    .count(),
                if fresh { 2 } else { 1 }
            );
        }
    }

    #[test]
    fn falling_blocks_respect_special_placement_shapes() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        use native_world::loaded::SavedBlockEntities;
        for item in [
            "minecraft:snow",
            "minecraft:snow_block",
            "minecraft:redstone_block",
            "minecraft:chest",
        ] {
            let mut session = session();
            session.set_snow_support_tags(fixture_snow_tags(&[], &[]));
            let position = IVec3::new(4, 1, 4);
            let absolute = session.origin + position;
            let chunk = ChunkPos {
                x: absolute.x.div_euclid(16),
                z: absolute.z.div_euclid(16),
            };
            Arc::make_mut(&mut session.world)
                .saved_block_entities
                .insert(chunk, SavedBlockEntities::Empty);
            let entity_pos = absolute.as_dvec3() + DVec3::new(0.5, 0.0, 0.5);
            let motion = crate::falling_block::AirborneMotion {
                position: entity_pos,
                velocity: DVec3::ZERO,
                age: 0,
                no_gravity: true,
            };
            session.falling_sand.push(FallingSand {
                motion,
                previous: entity_pos,
                fall_distance: 0.0,
                fall_distance_verified: true,
                kind: FallingKind::Sand,
                drop_item: true,
                cancel_drop: false,
                on_ground: false,
                source: None,
                created: None,
            });
            let mut inventory = PlayerInventory::default();
            assert!(inventory.set_slot(
                PlayerSlot::Storage(0),
                ItemStack::new(item.into(), 2, 64, Tag::Compound(vec![]))
            ));
            session.set_player_inventory(inventory);
            let hit = ShapeRayHit {
                position: position + IVec3::NEG_Y,
                face: IVec3::Y,
                location: DVec3::ZERO,
                inside: false,
            };
            if item == "minecraft:snow" {
                assert!(session.place_snow(hit).is_some());
                let layer = ShapeRayHit { position, ..hit };
                assert!(session.place_snow(layer).is_none());
            } else {
                let placed = match item {
                    "minecraft:snow_block" => session.place_snow_block(hit),
                    "minecraft:redstone_block" => session.place_redstone(hit),
                    "minecraft:chest" => session.place_chest(hit),
                    _ => unreachable!(),
                };
                assert!(placed.is_none(), "{item}");
                session.falling_sand.clear();
                let placed = match item {
                    "minecraft:snow_block" => session.place_snow_block(hit),
                    "minecraft:redstone_block" => session.place_redstone(hit),
                    "minecraft:chest" => session.place_chest(hit),
                    _ => unreachable!(),
                };
                assert_eq!(placed, Some(PlayerSlot::Storage(0)), "{item}");
            }
        }
    }

    #[test]
    #[cfg(target_os = "windows")]
    #[ignore = "requires Minecraft 26.3 and Java 25 JDK"]
    fn ordinary_placement_targets_match_java() {
        use std::{path::PathBuf, process::Command};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        native_resources::packs::ResourceStack::open(&game).unwrap();
        let temp = tempfile::tempdir().unwrap();
        let version = game.join("versions/26.3");
        let manifest: serde_json::Value =
            serde_json::from_slice(&std::fs::read(version.join("26.3.json")).unwrap()).unwrap();
        let mut paths = vec![version.join("26.3.jar"), temp.path().to_path_buf()];
        for library in manifest["libraries"].as_array().unwrap() {
            if let Some(path) = library["downloads"]["artifact"]["path"].as_str() {
                let path = game.join("libraries").join(path);
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
        let cp = std::env::join_paths(paths).unwrap();
        let java = std::env::var_os("MINECRAFT_JAVA_HOME").or_else(|| std::env::var_os("JAVA_HOME")).map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from(std::env::var_os("USERPROFILE").unwrap()).join("AppData/Local/Packages/Microsoft.4297127D64EC6_8wekyb3d8bbwe/LocalCache/Local/runtime/java-runtime-epsilon/windows-x64/java-runtime-epsilon")).join("bin");
        let source = temp.path().join("OrdinaryPlacementOracle.java");
        let output = temp.path().join("placement.json");
        std::fs::write(
            &source,
            include_str!("../tests/java/OrdinaryPlacementOracle.java"),
        )
        .unwrap();
        for command in [
            Command::new(java.join("javac.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg(&source),
            Command::new(java.join("java.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg("OrdinaryPlacementOracle")
                .arg(&output),
        ] {
            let result = command.output().unwrap();
            assert!(
                result.status.success(),
                "placement oracle failed:\n{}\n{}",
                String::from_utf8_lossy(&result.stdout),
                String::from_utf8_lossy(&result.stderr)
            );
        }
        let rows: Vec<serde_json::Value> =
            serde_json::from_slice(&std::fs::read(output).unwrap()).unwrap();
        assert_eq!(rows.len(), 4 * 21 * 21 * 6);
        let mut session = session();
        let pos = IVec3::new(4, 8, 4);
        for row in rows {
            let face = match row["face"].as_str().unwrap() {
                "up" => IVec3::Y,
                "down" => IVec3::NEG_Y,
                "east" => IVec3::X,
                "west" => IVec3::NEG_X,
                "south" => IVec3::Z,
                "north" => IVec3::NEG_Z,
                _ => unreachable!(),
            };
            let make_state = |name: &str| {
                if let Some(layers) = name.strip_prefix("snow_") {
                    state("minecraft:snow", &[("layers", layers)])
                } else if name == "water" || name == "lava" {
                    state(&format!("minecraft:{name}"), &[("level", "0")])
                } else {
                    state(&format!("minecraft:{name}"), &[])
                }
            };
            let clicked = session.intern_block(make_state(row["clicked"].as_str().unwrap()));
            let adjacent = session.intern_block(make_state(row["adjacent"].as_str().unwrap()));
            session.set_with_notify(pos, clicked, false);
            session.set_with_notify(pos + face, adjacent, false);
            let hit = ShapeRayHit {
                position: pos,
                face,
                location: DVec3::ZERO,
                inside: false,
            };
            let actual = session.ordinary_placement_target(hit);
            assert_eq!(
                actual.is_some(),
                row["can_place"].as_bool().unwrap(),
                "{row}"
            );
            if let Some(actual) = actual {
                let expected = IVec3::new(
                    row["x"].as_i64().unwrap() as i32,
                    row["y"].as_i64().unwrap() as i32,
                    row["z"].as_i64().unwrap() as i32,
                );
                assert_eq!(actual - pos, expected, "{row}");
            }
        }
    }

    #[test]
    fn ordinary_block_placement_replaces_water_and_consumes_held_stack() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        for hand in [PlayerSlot::Storage(0), PlayerSlot::Offhand] {
            for mode in [
                GameMode::Survival,
                GameMode::Creative,
                GameMode::Adventure,
                GameMode::Spectator,
            ] {
                let mut session = session();
                session.set_game_mode(mode);
                let pos = IVec3::new(8, 2, 7);
                let water = session.intern_block(state("minecraft:water", &[("level", "0")]));
                assert!(session.set_with_notify(pos, water, false));
                let mut inventory = PlayerInventory::default();
                assert!(inventory.set_slot(
                    hand,
                    ItemStack::new("minecraft:stone".into(), 2, 64, Tag::Compound(vec![]))
                ));
                session.set_player_inventory(inventory);
                session.submit_command(PlayerCommand::Place);
                session.update(TICK);
                let Cell::State(id) = cell(
                    &session.world,
                    session.origin,
                    session.bounds,
                    pos,
                    session.states[0],
                ) else {
                    panic!("missing target")
                };
                assert_eq!(
                    session.world.state(id).unwrap().name,
                    if matches!(mode, GameMode::Survival | GameMode::Creative) {
                        "minecraft:stone"
                    } else {
                        "minecraft:water"
                    },
                    "{mode:?} {hand:?}"
                );
                assert_eq!(
                    session.inventory.slot(hand).unwrap().count(),
                    if mode == GameMode::Survival { 1 } else { 2 }
                );
            }
        }
    }

    #[test]
    #[cfg(target_os = "windows")]
    #[ignore = "requires Minecraft 26.3 and Java 25 JDK"]
    fn cauldron_contents_and_inventory_match_java() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        use std::{path::PathBuf, process::Command};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let version = game.join("versions/26.3");
        let metadata: serde_json::Value =
            serde_json::from_slice(&std::fs::read(version.join("26.3.json")).unwrap()).unwrap();
        let temp = tempfile::tempdir().unwrap();
        let mut paths = vec![version.join("26.3.jar"), temp.path().to_path_buf()];
        for entry in metadata["libraries"].as_array().unwrap() {
            if let Some(path) = entry["downloads"]["artifact"]["path"].as_str() {
                let path = game.join("libraries").join(path);
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
        let cp = std::env::join_paths(paths).unwrap();
        let java = std::env::var_os("MINECRAFT_JAVA_HOME").or_else(|| std::env::var_os("JAVA_HOME")).map(PathBuf::from).unwrap_or_else(|| PathBuf::from(std::env::var_os("USERPROFILE").unwrap()).join("AppData/Local/Packages/Microsoft.4297127D64EC6_8wekyb3d8bbwe/LocalCache/Local/runtime/java-runtime-epsilon/windows-x64/java-runtime-epsilon")).join("bin");
        let source = temp.path().join("CauldronOracle.java");
        let output = temp.path().join("cauldrons.json");
        std::fs::write(&source, include_str!("../tests/java/CauldronOracle.java")).unwrap();
        for command in [
            Command::new(java.join("javac.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg(&source),
            Command::new(java.join("java.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg("CauldronOracle")
                .arg(&output),
        ] {
            let result = command.output().unwrap();
            assert!(
                result.status.success(),
                "{}\n{}",
                String::from_utf8_lossy(&result.stdout),
                String::from_utf8_lossy(&result.stderr)
            );
        }
        let rows: Vec<serde_json::Value> =
            serde_json::from_slice(&std::fs::read(output).unwrap()).unwrap();
        assert_eq!(rows.len(), 240);
        for row in rows {
            let mut session = session();
            let creative = row["creative"].as_bool().unwrap();
            if creative {
                session.set_game_mode(GameMode::Creative);
            }
            let initial = row["initial"].as_u64().unwrap();
            let block = match initial {
                0 => state("minecraft:cauldron", &[]),
                1 => state("minecraft:water_cauldron", &[("level", "1")]),
                2 => state("minecraft:water_cauldron", &[("level", "2")]),
                3 => state("minecraft:water_cauldron", &[("level", "3")]),
                4 => state("minecraft:lava_cauldron", &[]),
                _ => state("minecraft:powder_snow_cauldron", &[("level", "1")]),
            };
            let pos = IVec3::new(8, 2, 7);
            let id = session.intern_block(block);
            session.set_with_notify(pos, id, false);
            if row["above_water"].as_bool().unwrap() {
                let water = session.intern_block(state("minecraft:water", &[("level", "0")]));
                session.set_with_notify(pos + IVec3::Y, water, false);
            }
            let hand = if row["off"].as_bool().unwrap() {
                PlayerSlot::Offhand
            } else {
                PlayerSlot::Storage(0)
            };
            let (id, max, contents) = match row["item"].as_u64().unwrap() {
                0 => ("minecraft:glass_bottle", 64, Tag::Compound(vec![])),
                1 => (
                    "minecraft:potion",
                    1,
                    Tag::Compound(vec![(
                        "minecraft:potion_contents".into(),
                        Tag::Compound(vec![(
                            "potion".into(),
                            Tag::String("minecraft:water".into()),
                        )]),
                    )]),
                ),
                2 => ("minecraft:bucket", 16, Tag::Compound(vec![])),
                3 => ("minecraft:water_bucket", 1, Tag::Compound(vec![])),
                _ => ("minecraft:lava_bucket", 1, Tag::Compound(vec![])),
            };
            let mut inventory = PlayerInventory::default();
            inventory.set_slot(hand, ItemStack::new(id.into(), 1, max, contents));
            session.set_player_inventory(inventory);
            assert_eq!(
                session.use_cauldron(hand, pos),
                row["handled"].as_bool().unwrap(),
                "{row}"
            );
            let p = session.origin + pos;
            let block = session.world.block(p.x, p.y, p.z).unwrap();
            assert_eq!(block.name, row["block"].as_str().unwrap(), "{row}");
            assert_eq!(
                block
                    .properties
                    .get("level")
                    .map_or(0, |s| s.parse::<u64>().unwrap()),
                row["level"].as_u64().unwrap(),
                "{row}"
            );
            let describe = |item: Option<&ItemStack>| {
                item.map_or_else(|| "-".to_owned(), |item| item.id().to_owned())
            };
            assert_eq!(
                describe(session.inventory.slot(hand)),
                row["hand"].as_str().unwrap(),
                "{row}"
            );
            let next = PlayerSlot::Storage(if hand == PlayerSlot::Offhand { 0 } else { 1 });
            assert_eq!(
                describe(session.inventory.slot(next)),
                row["slot1"].as_str().unwrap(),
                "{row}"
            );
            let sounds = session.take_bucket_sounds();
            if let Some(sound) = row["sound"].as_str() {
                assert_eq!(sounds.len(), 1, "{row}");
                assert_eq!(
                    format!("minecraft:{}", sounds[0].kind.event()),
                    sound,
                    "{row}"
                );
                assert!(!sounds[0].kind.is_player_sound() && !sounds[0].kind.is_neutral_sound());
                assert_eq!(row["category"].as_str(), Some("BLOCKS"));
            } else {
                assert!(sounds.is_empty(), "{row}");
            }
        }
    }

    #[test]
    #[cfg(target_os = "windows")]
    #[ignore = "requires Minecraft 26.3 and Java 25 JDK"]
    fn cauldron_banner_cleaning_matches_java_inventory() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{Tag, TagType};
        use std::{path::PathBuf, process::Command};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let version = game.join("versions/26.3");
        let metadata: serde_json::Value =
            serde_json::from_slice(&std::fs::read(version.join("26.3.json")).unwrap()).unwrap();
        let temp = tempfile::tempdir().unwrap();
        let mut paths = vec![version.join("26.3.jar"), temp.path().to_path_buf()];
        for entry in metadata["libraries"].as_array().unwrap() {
            if let Some(path) = entry["downloads"]["artifact"]["path"].as_str() {
                let path = game.join("libraries").join(path);
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
        let cp = std::env::join_paths(paths).unwrap();
        let java=std::env::var_os("MINECRAFT_JAVA_HOME").or_else(||std::env::var_os("JAVA_HOME")).map(PathBuf::from).unwrap_or_else(||PathBuf::from(std::env::var_os("USERPROFILE").unwrap()).join("AppData/Local/Packages/Microsoft.4297127D64EC6_8wekyb3d8bbwe/LocalCache/Local/runtime/java-runtime-epsilon/windows-x64/java-runtime-epsilon")).join("bin");
        let source = temp.path().join("CauldronBannerOracle.java");
        let base = temp.path().join("CauldronOracle.java");
        let output = temp.path().join("banners.json");
        std::fs::write(
            &source,
            include_str!("../tests/java/CauldronBannerOracle.java"),
        )
        .unwrap();
        std::fs::write(&base, include_str!("../tests/java/CauldronOracle.java")).unwrap();
        for command in [
            Command::new(java.join("javac.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg(&source)
                .arg(&base),
            Command::new(java.join("java.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg("CauldronBannerOracle")
                .arg(&output),
        ] {
            let result = command.output().unwrap();
            assert!(
                result.status.success(),
                "{}\n{}",
                String::from_utf8_lossy(&result.stdout),
                String::from_utf8_lossy(&result.stderr)
            );
        }
        let output: serde_json::Value =
            serde_json::from_slice(&std::fs::read(output).unwrap()).unwrap();
        assert_eq!(output["max"], 16);
        assert_eq!(output["default_patterns"], true);
        let rows = output["rows"].as_array().unwrap();
        assert_eq!(rows.len(), 192);
        let layer = |pattern: &str, color: &str| {
            Tag::Compound(vec![
                ("pattern".into(), Tag::String(pattern.into())),
                ("color".into(), Tag::String(color.into())),
            ])
        };
        let components = |layers: u64, cleaned: bool| {
            let direct = Tag::Compound(vec![
                (
                    "pattern".into(),
                    Tag::Compound(vec![
                        ("asset_id".into(), Tag::String("example:custom".into())),
                        (
                            "translation_key".into(),
                            Tag::String("example.banner".into()),
                        ),
                    ]),
                ),
                ("color".into(), Tag::String("green".into())),
            ]);
            let mut values = match layers {
                0 => vec![],
                1 => vec![layer("minecraft:stripe_bottom", "red")],
                2 => vec![
                    layer("minecraft:stripe_bottom", "red"),
                    layer("minecraft:cross", "blue"),
                ],
                _ => vec![
                    layer("minecraft:stripe_bottom", "red"),
                    direct,
                    layer("minecraft:cross", "blue"),
                ],
            };
            if cleaned && layers > 0 {
                values.pop();
            }
            if values.is_empty() {
                Tag::Compound(vec![])
            } else {
                Tag::Compound(vec![(
                    "minecraft:banner_patterns".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values,
                    },
                )])
            }
        };
        let describe = |item: Option<&ItemStack>| -> serde_json::Value {
            let Some(item) = item else {
                return serde_json::Value::Null;
            };
            let mut json = serde_json::json!({"id":item.id(),"count":item.count()});
            if crate::inventory::is_banner_item(item.id()) {
                let values = match item.components().get("minecraft:banner_patterns") {
                    Some(Tag::List { values, .. }) => values.as_slice(),
                    _ => &[],
                };
                let layers: Vec<_> = values
                    .iter()
                    .map(|layer| {
                        let text = |key| match layer.get(key).unwrap() {
                            Tag::String(value) => String::from_utf16(&value.0).unwrap(),
                            _ => panic!("invalid layer"),
                        };
                        let pattern = match layer.get("pattern").unwrap() {
                            Tag::String(value) => serde_json::json!(String::from_utf16(&value.0).unwrap()),
                            Tag::Compound(_) => { let value=layer.get("pattern").unwrap(); let get=|key| match value.get(key).unwrap(){Tag::String(s)=>String::from_utf16(&s.0).unwrap(),_=>panic!("invalid pattern")}; serde_json::json!({"asset_id":get("asset_id"),"translation_key":get("translation_key")}) },
                            _ => panic!("invalid pattern"),
                        };
                        serde_json::json!({"pattern":pattern,"color":text("color")})
                    })
                    .collect();
                json["patterns"] = serde_json::json!(layers);
            }
            json
        };
        for row in rows {
            let mut session = session();
            let creative = row["creative"].as_bool().unwrap();
            if creative {
                session.set_game_mode(GameMode::Creative);
            }
            let pos = IVec3::new(8, 2, 7);
            let state = session.intern_block(state("minecraft:water_cauldron", &[("level", "2")]));
            session.set_with_notify(pos, state, false);
            let hand = if row["off"].as_bool().unwrap() {
                PlayerSlot::Offhand
            } else {
                PlayerSlot::Storage(0)
            };
            let layers = row["layers"].as_u64().unwrap();
            let mut inventory = PlayerInventory::default();
            if row["full"].as_bool().unwrap() {
                for i in 0..36 {
                    inventory.set_slot(
                        PlayerSlot::Storage(i),
                        ItemStack::new("minecraft:stone".into(), 64, 64, Tag::Compound(vec![])),
                    );
                }
            }
            if row["existing"].as_bool().unwrap() {
                inventory.set_slot(
                    PlayerSlot::Storage(5),
                    ItemStack::new(
                        "minecraft:white_banner".into(),
                        1,
                        16,
                        components(layers, true),
                    ),
                );
            }
            inventory.set_slot(
                hand,
                ItemStack::new(
                    "minecraft:white_banner".into(),
                    row["count"].as_u64().unwrap() as u32,
                    16,
                    components(layers, false),
                ),
            );
            session.set_player_inventory(inventory);
            assert_eq!(
                session.use_cauldron(hand, pos),
                row["handled"].as_bool().unwrap(),
                "{row}"
            );
            let p = session.origin + pos;
            let block = session.world.block(p.x, p.y, p.z).unwrap();
            assert_eq!(
                block.properties["level"].parse::<u64>().unwrap(),
                row["level"].as_u64().unwrap(),
                "{row}"
            );
            for i in 0..36 {
                assert_eq!(
                    describe(session.inventory.slot(PlayerSlot::Storage(i))),
                    row["slots"][i as usize],
                    "slot {i}: {row}"
                );
            }
            assert_eq!(
                describe(session.inventory.slot(PlayerSlot::Offhand)),
                row["offhand"],
                "{row}"
            );
            let drops = session.dropped_items.snapshot();
            assert_eq!(
                describe(drops.first().map(|drop| &drop.stack)),
                row["dropped"],
                "{row}"
            );
            assert!(drops.len() <= 1);
            assert!(session.take_bucket_sounds().is_empty());
        }
    }

