    #[test]
    fn held_stair_mining_uses_fixed_ticks_and_tool_progress() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        use native_resources::{loot::BlockLootTables, packs::ResourceProvider};
        struct Loot;
        impl ResourceProvider for Loot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(path.ends_with("/oak_stairs.json").then(|| br#"{"type":"minecraft:block","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:oak_stairs"}]}]}"#.to_vec()))
            }
        }
        for split_frames in [false, true] {
            let mut session = session();
            session.set_block_loot(Arc::new(BlockLootTables::load(&mut Loot).unwrap()));
            session.set_vanilla_block_ids(Arc::new(BTreeSet::from([
                "minecraft:air".into(),
                "minecraft:stone".into(),
                "minecraft:oak_stairs".into(),
            ])));
            session.set_block_drops(false);
            let tool =
                ItemStack::new("minecraft:iron_axe".into(), 1, 1, Tag::Compound(vec![])).unwrap();
            Arc::make_mut(&mut session.inventory).set_slot(PlayerSlot::Storage(0), Some(tool));
            let pos = IVec3::new(8, 2, 6);
            let stair = session.intern_block(state(
                "minecraft:oak_stairs",
                &[
                    ("facing", "south"),
                    ("half", "top"),
                    ("shape", "straight"),
                    ("waterlogged", "false"),
                ],
            ));
            session.set_with_notify(pos, stair, false);
            session.update(TICK * 3);
            assert!(session.player.on_ground);
            session.submit_command(PlayerCommand::Break);
            for tick in 1..=10 {
                if split_frames {
                    session.update(TICK / 2);
                    session.update(TICK / 2);
                } else {
                    session.update(TICK);
                }
                let after = session
                    .world
                    .block(session.origin.x + pos.x, pos.y, session.origin.z + pos.z)
                    .unwrap();
                assert_eq!(
                    after.name,
                    if tick == 10 {
                        "minecraft:air"
                    } else {
                        "minecraft:oak_stairs"
                    },
                    "tick={tick} split={split_frames}"
                );
            }
            assert_eq!(
                session
                    .inventory
                    .slot(PlayerSlot::Storage(0))
                    .unwrap()
                    .components()
                    .get("minecraft:damage"),
                Some(&Tag::Int(1))
            );
        }
    }

    #[test]
    fn data_pack_mining_tags_control_progress_and_drops_in_session() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        use native_resources::packs::ResourceProvider;
        struct Data {
            incorrect: bool,
            sword: bool,
        }
        impl ResourceProvider for Data {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn list_data(
                &mut self,
                _: &str,
            ) -> anyhow::Result<Vec<native_resources::packs::ResourceId>> {
                Ok(Vec::new())
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                let id = if path.ends_with("/stone_stairs.json") {
                    "minecraft:stone_stairs"
                } else if path.ends_with("/stone.json") {
                    "minecraft:stone"
                } else {
                    return Ok(None);
                };
                Ok(Some(format!(r#"{{"type":"minecraft:block","pools":[{{"rolls":1,"entries":[{{"type":"minecraft:item","name":"{id}"}}]}}]}}"#).into_bytes()))
            }
            fn read_data_stack(&mut self, path: &str) -> anyhow::Result<Vec<Vec<u8>>> {
                if !path.contains("/tags/block/") {
                    return Ok(vec![]);
                }
                let selected = path.ends_with("/mineable/axe.json")
                    || (self.incorrect && path.ends_with("/incorrect_for_iron_tool.json"))
                    || (self.sword && path.ends_with("/sword_instantly_mines.json"));
                Ok(vec![if selected {
                    br#"{"replace":true,"values":["minecraft:stone","minecraft:stone_stairs"]}"#
                        .to_vec()
                } else {
                    br#"{"replace":true,"values":[]}"#.to_vec()
                }])
            }
        }
        for name in ["minecraft:stone", "minecraft:stone_stairs"] {
            for (incorrect, sword, ticks, drops, damage) in [
                (false, false, 8, 1, 1),
                (true, false, 25, 0, 1),
                (false, true, 1, 0, 2),
            ] {
                let mut data = Data { incorrect, sword };
                let registry = BTreeSet::from([
                    "minecraft:air".into(),
                    "minecraft:stone".into(),
                    "minecraft:stone_stairs".into(),
                ]);
                let tags =
                    native_resources::mining_tags::MiningTags::load(&mut data, &registry).unwrap();
                let loot = BlockLootTables::load(&mut data).unwrap();
                let mut session = session();
                session.set_vanilla_block_ids(Arc::new(registry));
                session.set_mining_tags(Arc::new(tags));
                session.set_block_loot(Arc::new(loot));
                let tool = ItemStack::new(
                    if sword {
                        "minecraft:iron_sword"
                    } else {
                        "minecraft:iron_axe"
                    }
                    .into(),
                    1,
                    1,
                    Tag::Compound(vec![]),
                )
                .unwrap();
                Arc::make_mut(&mut session.inventory).set_slot(PlayerSlot::Storage(0), Some(tool));
                let pos = IVec3::new(8, 2, 6);
                let block = if name == "minecraft:stone" {
                    session.states[3]
                } else {
                    session.intern_block(state(
                        name,
                        &[
                            ("facing", "south"),
                            ("half", "top"),
                            ("shape", "straight"),
                            ("waterlogged", "false"),
                        ],
                    ))
                };
                session.set_with_notify(pos, block, false);
                session.update(TICK * 3);
                assert!(session.player.on_ground);
                session.submit_command(PlayerCommand::Break);
                for tick in 1..=ticks {
                    session.update(TICK);
                    let after = session
                        .world
                        .block(session.origin.x + pos.x, pos.y, session.origin.z + pos.z)
                        .unwrap();
                    assert_eq!(
                        after.name,
                        if tick == ticks { "minecraft:air" } else { name },
                        "{name} incorrect={incorrect} sword={sword} tick={tick}"
                    );
                }
                assert_eq!(
                    session.dropped_items.snapshot().len(),
                    drops,
                    "{name} incorrect={incorrect} sword={sword}"
                );
                assert_eq!(
                    session
                        .inventory
                        .slot(PlayerSlot::Storage(0))
                        .unwrap()
                        .components()
                        .get("minecraft:damage"),
                    Some(&Tag::Int(damage))
                );
            }
        }
    }

    #[test]
    fn custom_tool_tag_controls_mining_and_damage_in_loaded_world() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{Tag, TagType};
        use native_resources::packs::{ResourceId, ResourceProvider};
        struct Data;
        impl ResourceProvider for Data {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn list_data(&mut self, _: &str) -> anyhow::Result<Vec<ResourceId>> {
                Ok(vec![ResourceId::parse("example:mineable").unwrap()])
            }
            fn read_data_stack(&mut self, path: &str) -> anyhow::Result<Vec<Vec<u8>>> {
                Ok(vec![
                    if path.ends_with("/example/tags/block/mineable.json") {
                        br#"{"values":["minecraft:stone"]}"#.to_vec()
                    } else {
                        br#"{"values":[]}"#.to_vec()
                    },
                ])
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(path.ends_with("/stone.json").then(|| br#"{"type":"minecraft:block","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:stone"}]}]}"#.to_vec()))
            }
        }
        for (tag, expected_break, expected_damage) in [
            ("#example:mineable", true, Some(3)),
            ("#example:missing", false, None),
        ] {
            let registry = BTreeSet::from(["minecraft:air".into(), "minecraft:stone".into()]);
            let mut data = Data;
            let tags =
                native_resources::mining_tags::MiningTags::load(&mut data, &registry).unwrap();
            let mut session = session();
            session.set_vanilla_block_ids(Arc::new(registry));
            session.set_mining_tags(Arc::new(tags));
            session.set_block_loot(Arc::new(BlockLootTables::load(&mut data).unwrap()));
            let rule = Tag::Compound(vec![
                ("blocks".into(), Tag::String(tag.into())),
                ("speed".into(), Tag::Float(6.0)),
                ("correct_for_drops".into(), Tag::Byte(1)),
            ]);
            let component = Tag::Compound(vec![
                (
                    "rules".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![rule],
                    },
                ),
                ("damage_per_block".into(), Tag::Int(3)),
            ]);
            let stack = ItemStack::new(
                "minecraft:iron_axe".into(),
                1,
                1,
                Tag::Compound(vec![("minecraft:tool".into(), component)]),
            )
            .unwrap();
            assert!(
                Arc::make_mut(&mut session.inventory).set_slot(PlayerSlot::Storage(0), Some(stack))
            );
            let pos = IVec3::new(8, 2, 6);
            session.set_with_notify(pos, session.states[3], false);
            session.update(TICK * 3);
            session.submit_command(PlayerCommand::Break);
            for _ in 0..10 {
                session.update(TICK);
            }
            let block = session
                .world
                .block(session.origin.x + pos.x, pos.y, session.origin.z + pos.z)
                .unwrap();
            assert_eq!(block.name == "minecraft:air", expected_break, "{tag}");
            assert_eq!(
                session.dropped_items.snapshot().len(),
                usize::from(expected_break)
            );
            assert_eq!(
                session
                    .inventory
                    .slot(PlayerSlot::Storage(0))
                    .unwrap()
                    .components()
                    .get("minecraft:damage")
                    .and_then(Tag::as_java_int),
                expected_damage
            );
        }
    }

    #[test]
    fn unsupported_snow_loot_does_not_destroy_block_or_damage_tool() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        use native_resources::packs::ResourceProvider;
        struct UnsupportedLoot;
        impl ResourceProvider for UnsupportedLoot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(path.ends_with("/snow.json").then(|| br#"{"type":"minecraft:block","pools":[{"rolls":1,"condition":{"type":"minecraft:location_check","predicate":{}},"entries":[{"type":"minecraft:item","name":"minecraft:diamond"}]}]}"#.to_vec()))
            }
        }
        for with_unsupported_table in [false, true] {
            let mut session = session();
            if with_unsupported_table {
                session.set_block_loot(Arc::new(
                    BlockLootTables::load(&mut UnsupportedLoot).unwrap(),
                ));
            }
            let tool = ItemStack::new("minecraft:iron_shovel".into(), 1, 1, Tag::Compound(vec![]))
                .unwrap();
            assert!(
                Arc::make_mut(&mut session.inventory).set_slot(PlayerSlot::Storage(0), Some(tool))
            );
            let relative = IVec3::new(8, 2, 6);
            let id = session.intern_block(state("minecraft:snow", &[("layers", "3")]));
            assert!(session.set(relative, id));
            session.finish_breaking(session.origin + relative);
            assert!(
                matches!(cell(&session.world, session.origin, session.bounds, relative, session.states[0]), Cell::State(current) if current == id)
            );
            assert!(
                session
                    .inventory
                    .slot(PlayerSlot::Storage(0))
                    .unwrap()
                    .components()
                    .get("minecraft:damage")
                    .is_none()
            );
            assert!(session.dropped_items.snapshot().is_empty());
        }
    }

    #[test]
    #[ignore = "requires the locally installed Minecraft 26.3 assets"]
    fn snow_block_placement_and_mining_use_vanilla_loot() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        use native_resources::{loot::BlockLootTables, packs::ResourceStack};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let mut resources = ResourceStack::open(&game).unwrap();
        let loot = Arc::new(BlockLootTables::load(&mut resources).unwrap());
        let registry = Arc::new(OxygenEnchantments::load(&mut resources).unwrap());
        for silk in [false, true] {
            let mut session = session();
            session.set_block_loot(Arc::clone(&loot));
            session
                .set_random_sequences(
                    0,
                    native_persistence::random_sequences::RandomSequences::read(None).unwrap(),
                )
                .unwrap();
            session
                .set_saved_breathing(
                    Default::default(),
                    crate::player_data::SavedAttribute::with_base(0.0),
                    Arc::clone(&registry),
                )
                .unwrap();
            let relative = IVec3::new(4, 1, 4);
            let stack = ItemStack::new("minecraft:snow_block".into(), 1, 64, Tag::Compound(vec![]))
                .unwrap();
            assert!(
                Arc::make_mut(&mut session.inventory).set_slot(PlayerSlot::Storage(0), Some(stack))
            );
            let hit = ShapeRayHit {
                position: relative + IVec3::NEG_Y,
                face: IVec3::Y,
                location: DVec3::ZERO,
                inside: false,
            };
            assert_eq!(session.place_snow_block(hit), Some(PlayerSlot::Storage(0)));
            let pos = session.origin + relative;
            let placed = session.world.block(pos.x, pos.y, pos.z).unwrap();
            assert_eq!(placed.name, "minecraft:snow_block");
            assert_eq!(
                picked_loaded_block_item(placed).unwrap().id(),
                "minecraft:snow_block"
            );
            let components = if silk {
                Tag::Compound(vec![(
                    "minecraft:enchantments".into(),
                    Tag::Compound(vec![("minecraft:silk_touch".into(), Tag::Int(1))]),
                )])
            } else {
                Tag::Compound(vec![])
            };
            let tool = ItemStack::new("minecraft:iron_shovel".into(), 1, 1, components).unwrap();
            assert!(
                Arc::make_mut(&mut session.inventory).set_slot(PlayerSlot::Storage(0), Some(tool))
            );
            session.finish_breaking(pos);
            assert_eq!(
                session.world.block(pos.x, pos.y, pos.z).unwrap().name,
                "minecraft:air"
            );
            let drops = session.dropped_items.snapshot();
            assert_eq!(drops.len(), 1);
            assert_eq!(
                drops[0].stack.id(),
                if silk {
                    "minecraft:snow_block"
                } else {
                    "minecraft:snowball"
                }
            );
            assert_eq!(drops[0].stack.count(), if silk { 1 } else { 4 });
        }
    }

    #[test]
    fn honey_block_place_uses_its_collision_shape_and_player_hand() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        for hand in [PlayerSlot::Storage(0), PlayerSlot::Offhand] {
            for mode in [
                GameMode::Survival,
                GameMode::Creative,
                GameMode::Adventure,
                GameMode::Spectator,
            ] {
                let mut test = session();
                test.set_game_mode(mode);
                assert!(test.set(IVec3::new(8, 1, 7), test.states[3]));
                let mut inventory = PlayerInventory::default();
                inventory.set_slot(
                    hand,
                    ItemStack::new("minecraft:honey_block".into(), 2, 64, Tag::Compound(vec![])),
                );
                test.set_player_inventory(inventory);
                test.submit_command(PlayerCommand::Place);
                test.update(TICK);
                let placed = test
                    .world
                    .block(test.origin.x + 8, 2, test.origin.z + 7)
                    .unwrap();
                let allowed = matches!(mode, GameMode::Survival | GameMode::Creative);
                assert_eq!(
                    placed.name,
                    if allowed {
                        "minecraft:honey_block"
                    } else {
                        "minecraft:air"
                    },
                    "{hand:?} {mode:?}"
                );
                assert_eq!(
                    test.inventory.slot(hand).unwrap().count(),
                    if mode == GameMode::Survival { 1 } else { 2 }
                );
                if allowed {
                    assert_eq!(
                        picked_loaded_block_item(placed).unwrap().id(),
                        "minecraft:honey_block"
                    );
                }
            }
        }
        let mut test = session();
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new("minecraft:honey_block".into(), 1, 64, Tag::Compound(vec![])),
        );
        test.set_player_inventory(inventory);
        let target = IVec3::new(4, 1, 4);
        let hit = ShapeRayHit {
            position: target + IVec3::NEG_Y,
            face: IVec3::Y,
            location: DVec3::ZERO,
            inside: false,
        };
        test.player.position = Vec3::new(5.25, 1.0, 4.5);
        assert_eq!(
            test.place_honey_block(hit),
            Some(PlayerSlot::Storage(0)),
            "the inset edge must not collide"
        );
        let mut blocked = session();
        blocked.set_player_inventory((*test.inventory).clone());
        blocked.player.position = Vec3::new(5.2, 1.0, 4.5);
        assert_eq!(
            blocked.place_honey_block(hit),
            None,
            "the player overlaps the honey collision shape"
        );
    }

    #[test]
    #[ignore = "requires the locally installed Minecraft 26.3 assets"]
    fn honey_block_mining_uses_vanilla_loot_and_does_not_wear_tools() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        use native_resources::{loot::BlockLootTables, packs::ResourceStack};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let mut resources = ResourceStack::open(&game).unwrap();
        let loot = Arc::new(BlockLootTables::load(&mut resources).unwrap());
        for tool in [None, Some("minecraft:iron_pickaxe")] {
            let mut test = session();
            test.set_block_loot(Arc::clone(&loot));
            test.set_random_sequences(
                0,
                native_persistence::random_sequences::RandomSequences::read(None).unwrap(),
            )
            .unwrap();
            let relative = IVec3::new(4, 1, 4);
            let mut inventory = PlayerInventory::default();
            inventory.set_slot(
                PlayerSlot::Storage(0),
                ItemStack::new("minecraft:honey_block".into(), 1, 64, Tag::Compound(vec![])),
            );
            test.set_player_inventory(inventory);
            let hit = ShapeRayHit {
                position: relative + IVec3::NEG_Y,
                face: IVec3::Y,
                location: DVec3::ZERO,
                inside: false,
            };
            assert_eq!(test.place_honey_block(hit), Some(PlayerSlot::Storage(0)));
            Arc::make_mut(&mut test.inventory).set_slot(
                PlayerSlot::Storage(0),
                tool.and_then(|id| ItemStack::new(id.into(), 1, 1, Tag::Compound(vec![]))),
            );
            let material = mining::Material::from_block_name("minecraft:honey_block").unwrap();
            assert!(
                mining::tool_progress(
                    material,
                    test.inventory.slot(PlayerSlot::Storage(0)),
                    true,
                    false
                )
                .unwrap()
                .is_infinite()
            );
            let absolute = test.origin + relative;
            test.finish_breaking(absolute);
            assert_eq!(
                test.world
                    .block(absolute.x, absolute.y, absolute.z)
                    .unwrap()
                    .name,
                "minecraft:air",
                "tool={tool:?}, errors={:?}",
                test.stream_errors
            );
            let drops = test.dropped_items.snapshot();
            assert_eq!(drops.len(), 1);
            assert_eq!(
                (drops[0].stack.id(), drops[0].stack.count()),
                ("minecraft:honey_block", 1)
            );
            if tool.is_some() {
                assert!(
                    test.inventory
                        .slot(PlayerSlot::Storage(0))
                        .unwrap()
                        .components()
                        .get("minecraft:damage")
                        .is_none()
                );
            }
        }
    }

