        test.set_crafting_recipes(recipes);
        test.set_random_sequences(
            0,
            native_persistence::random_sequences::RandomSequences::read(None).unwrap(),
        )
        .unwrap();
        assert!(test.set(IVec3::new(8, 1, 7), test.states[3]));
