    #[test]
    fn lamp_stays_on_when_repowered_or_signal_is_unknown() {
        let mut session = session();
        session.set_random_tick_speed(0);
        let lamp = IVec3::new(8, 5, 8);
        let power = lamp + IVec3::X;
        let lamp_id = session.intern_block(state("minecraft:redstone_lamp", &[("lit", "false")]));
        session.set(lamp, lamp_id);
        let source = session.intern_block(state("minecraft:redstone_block", &[]));
        session.set(power, source);
        let read = |session: &LoadedSession| {
            let p = session.origin + lamp;
            redstone_lamp_lit(session.world.block(p.x, p.y, p.z).unwrap()).unwrap()
        };
        assert!(read(&session));
        session.set(power, session.states[0]);
        session.update(TICK * 2);
        session.set(power, source);
        session.update(TICK * 5);
        assert!(read(&session));
        assert!(session.lamp_pending.is_empty());
        let unknown = session.intern_block(state("minecraft:unimplemented_source", &[]));
        session.set(lamp + IVec3::NEG_X, unknown);
        session.set(power, session.states[0]);
        session.update(TICK * 5);
        assert!(read(&session));
        session.set(lamp + IVec3::NEG_X, session.states[0]);
        for _ in 0..5 {
            session.update(TICK);
        }
        assert!(!read(&session));
    }

    #[test]
    fn removing_button_support_starts_lamp_shutdown() {
        let mut session = session();
        let lamp = IVec3::new(8, 5, 8);
        let button = lamp + IVec3::X;
        let support = button + IVec3::X;
        session.set(support, session.states[3]);
        let lamp_id = session.intern_block(state("minecraft:redstone_lamp", &[("lit", "false")]));
        session.set(lamp, lamp_id);
        let kind = native_core::button::Button::from_id("minecraft:stone_button").unwrap();
        let button_id = session.intern_block(button_state(kind, IVec3::NEG_X, 0.0).unwrap());
        session.set(button, button_id);
        assert!(session.use_button(button));
        assert!(session.set(support, session.states[0]));
        let pos = session.origin + lamp;
        assert_eq!(
            redstone_lamp_lit(session.world.block(pos.x, pos.y, pos.z).unwrap()),
            Some(true)
        );
        assert!(
            matches!(cell(&session.world, session.origin, session.bounds, button, session.states[0]), Cell::State(id) if id == session.states[0])
        );
        for _ in 0..5 {
            session.update(TICK);
        }
        assert_eq!(
            redstone_lamp_lit(session.world.block(pos.x, pos.y, pos.z).unwrap()),
            Some(false)
        );
    }

    #[test]
    fn saved_lamp_tick_is_preserved_across_chunk_unload() {
        let mut session = session();
        session.set_random_tick_speed(0);
        let home = session.player_chunk().unwrap();
        let remote = ChunkPos {
            x: home.x + 1,
            z: home.z,
        };
        let relative = IVec3::new(8, 5, 8);
        let absolute = session.origin + relative;
        let lit = session.intern_block(state("minecraft:redstone_lamp", &[("lit", "true")]));
        assert!(session.set(relative, lit));
        let tick = SavedBlockTick {
            block: "minecraft:redstone_lamp".into(),
            position: absolute.to_array(),
            delay: 2,
            priority: 0,
        };
        session.enqueue_saved_lamps(std::slice::from_ref(&tick));
        assert_eq!(session.draft_block_ticks(home).unwrap(), vec![tick]);
        session.queue_chunk_window(remote, 0);
        for _ in 0..5 {
            session.update(TICK);
        }
        assert_eq!(session.lamp_deferred.len(), 1);
        assert_eq!(session.draft_block_ticks(home).unwrap()[0].delay, -3);
        session.queue_chunk_window(home, 0);
        session.update(TICK);
        assert_eq!(
            redstone_lamp_lit(
                session
                    .world
                    .block(absolute.x, absolute.y, absolute.z)
                    .unwrap()
            ),
            Some(false)
        );
        assert!(session.lamp_pending.is_empty());
        assert!(session.draft_block_ticks(home).unwrap().is_empty());
    }

    #[test]
    #[cfg(target_os = "windows")]
    #[ignore = "requires Minecraft 26.3 and Java 25 JDK"]
    fn lamp_neighbor_and_scheduled_tick_match_java() {
        use std::{path::PathBuf, process::Command};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let _verified = native_resources::packs::ResourceStack::open(&game).unwrap();
        let temp = tempfile::tempdir().unwrap();
        let version = game.join("versions/26.3");
        let manifest: serde_json::Value =
            serde_json::from_slice(&std::fs::read(version.join("26.3.json")).unwrap()).unwrap();
        let mut paths = vec![version.join("26.3.jar"), temp.path().to_path_buf()];
        for library in manifest["libraries"].as_array().unwrap() {
            if let Some(path) = library["downloads"]["artifact"]["path"].as_str() {
                let path = game.join("libraries").join(path);
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
        let cp = std::env::join_paths(paths).unwrap();
        let java = std::env::var_os("MINECRAFT_JAVA_HOME").or_else(|| std::env::var_os("JAVA_HOME")).map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from(std::env::var_os("USERPROFILE").unwrap()).join("AppData/Local/Packages/Microsoft.4297127D64EC6_8wekyb3d8bbwe/LocalCache/Local/runtime/java-runtime-epsilon/windows-x64/java-runtime-epsilon")).join("bin");
        let source = temp.path().join("RedstoneLampOracle.java");
        let result = temp.path().join("output.json");
        std::fs::write(
            &source,
            include_str!("../tests/java/RedstoneLampOracle.java"),
        )
        .unwrap();
        let run = |command: &mut Command| {
            let output = command.output().unwrap();
            assert!(
                output.status.success(),
                "{}\n{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
        };
        run(Command::new(java.join("javac.exe"))
            .arg("-classpath")
            .arg(&cp)
            .arg(&source));
        run(Command::new(java.join("java.exe"))
            .arg("-classpath")
            .arg(&cp)
            .arg("RedstoneLampOracle")
            .arg(&result));
        let rows: Vec<serde_json::Value> =
            serde_json::from_slice(&std::fs::read(result).unwrap()).unwrap();
        assert_eq!(rows.len(), 10);
        for row in rows.iter().take(8) {
            let tick = row[0].as_bool().unwrap();
            let lit = row[1].as_bool().unwrap();
            let power = row[2].as_bool().unwrap();
            let mut session = session();
            let relative = IVec3::new(8, 5, 8);
            if power {
                let source = session.intern_block(state("minecraft:redstone_block", &[]));
                session.set(relative + IVec3::X, source);
            }
            let lamp = session.intern_block(state(
                "minecraft:redstone_lamp",
                &[("lit", if lit { "true" } else { "false" })],
            ));
            session.set(relative, lamp);
            if tick {
                let absolute = session.origin + relative;
                session.enqueue_saved_lamps(&[SavedBlockTick {
                    block: "minecraft:redstone_lamp".into(),
                    position: absolute.to_array(),
                    delay: 0,
                    priority: 0,
                }]);
                session.advance_block_ticks();
            } else {
                session.update_lamp(relative);
            }
            let absolute = session.origin + relative;
            let got = redstone_lamp_lit(
                session
                    .world
                    .block(absolute.x, absolute.y, absolute.z)
                    .unwrap(),
            )
            .unwrap();
            assert_eq!(got, row[3].as_bool().unwrap(), "{row}");
            let delay = session
                .lamp_ticks
                .first_key_value()
                .map_or(-1, |(order, _)| {
                    i64::try_from(order.0 - i128::from(session.tick)).unwrap()
                });
            assert_eq!(delay, row[4].as_i64().unwrap(), "{row}");
            assert!(matches!(row[5].as_i64().unwrap(), -1 | 2), "{row}");
        }
        for row in rows.iter().skip(8) {
            use crate::inventory::PlayerSlot;
            use native_persistence::nbt::Tag;
            let powered = row[0].as_bool().unwrap();
            let mut session = session();
            let target = IVec3::new(8, 5, 8);
            let support = target + IVec3::NEG_Z;
            session.set(support, session.states[3]);
            if powered {
                let source = session.intern_block(state("minecraft:redstone_block", &[]));
                session.set(target + IVec3::X, source);
            }
            let mut inventory = PlayerInventory::default();
            inventory.set_slot(
                PlayerSlot::Storage(0),
                ItemStack::new(
                    "minecraft:redstone_lamp".into(),
                    1,
                    64,
                    Tag::Compound(vec![]),
                ),
            );
            session.set_player_inventory(inventory);
            let hit = ShapeRayHit {
                position: support,
                face: IVec3::Z,
                location: DVec3::ZERO,
                inside: false,
            };
            assert_eq!(session.place_redstone(hit), Some(PlayerSlot::Storage(0)));
            let absolute = session.origin + target;
            let got = redstone_lamp_lit(
                session
                    .world
                    .block(absolute.x, absolute.y, absolute.z)
                    .unwrap(),
            );
            assert_eq!(got, row[1].as_bool(), "{row}");
        }
    }

    #[test]
    fn cross_chunk_block_light_is_drafted_and_rejects_stale_or_pending_data() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let mut session = session();
        let air = session.states[0];
        let home = session.player_chunk().unwrap();
        for x in -1..=1 {
            for z in -1..=1 {
                let pos = ChunkPos {
                    x: home.x + x,
                    z: home.z + z,
                };
                let sections = (0..=1)
                    .map(|y| {
                        (
                            y,
                            Arc::new(Section {
                                blocks: Some(Box::new([air; BLOCK_COUNT])),
                                biomes: None,
                                block_light: Some(Box::new([0; LIGHT_BYTES])),
                                sky_light: None,
                            }),
                        )
                    })
                    .collect();
                Arc::make_mut(&mut session.world).chunks.insert(
                    pos,
                    Arc::new(Chunk {
                        position: pos,
                        status: Some("minecraft:full".into()),
                        block_light_correct: true,
                        sections,
                    }),
                );
                session.fluid_chunks_seen.insert(pos);
            }
        }
        let lamp = session.intern_block(state("minecraft:redstone_lamp", &[("lit", "true")]));
        assert!(session.set(IVec3::new(14, 15, 8), lamp));
        assert!(session.pending_light.is_empty());
        let neighbor = ChunkPos {
            x: home.x + 1,
            z: home.z,
        };
        assert!(session.dirty_chunk_positions().contains(&neighbor));
        let source = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("xPos".into(), Tag::Int(neighbor.x)),
                ("zPos".into(), Tag::Int(neighbor.z)),
                ("Status".into(), Tag::String("minecraft:full".into())),
                ("isLightOn".into(), Tag::Byte(1)),
                (
                    "sections".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: (0..=1)
                            .map(|y| {
                                Tag::Compound(vec![
                                    ("Y".into(), Tag::Byte(y)),
                                    ("BlockLight".into(), Tag::ByteArray(vec![0; LIGHT_BYTES])),
                                    ("opaque".into(), Tag::Int(17)),
                                ])
                            })
                            .collect(),
                    },
                ),
            ]),
        };
        let draft = session
            .draft_dirty_chunk_with_lighting(neighbor, &source, &test_heightmap_tags(), |_| {
                anyhow::bail!("light-only chunk must not rebuild heightmaps")
            })
            .unwrap();
        let decoded =
            native_persistence::palette::decode_sections(&draft.document().value).unwrap();
        let current = &session.world.chunks[&neighbor];
        for section in decoded {
            assert_eq!(
                section.block_light.as_deref(),
                current.sections[&section.y]
                    .block_light
                    .as_deref()
                    .map(|a| a.as_slice())
            );
        }
        let Tag::List { values, .. } = draft.document().value.get("sections").unwrap() else {
            unreachable!()
        };
        assert!(
            values
                .iter()
                .all(|section| section.get("opaque") == Some(&Tag::Int(17)))
        );
        let mut stale = source.clone();
        let Tag::Compound(fields) = &mut stale.value else {
            unreachable!()
        };
        let Tag::List { values, .. } = &mut fields
            .iter_mut()
            .find(|(name, _)| name.matches("sections"))
            .unwrap()
            .1
        else {
            unreachable!()
        };
        let Tag::Compound(fields) = &mut values[0] else {
            unreachable!()
        };
        fields
            .iter_mut()
            .find(|(name, _)| name.matches("BlockLight"))
            .unwrap()
            .1 = Tag::ByteArray(vec![1; LIGHT_BYTES]);
        assert!(
            session
                .draft_dirty_chunk_with_lighting(neighbor, &stale, &test_heightmap_tags(), |_| Ok(
                    (true, false)
                ))
                .is_err()
        );
        session.pending_light.insert(
            BlockPosition {
                x: session.origin.x,
                y: 4,
                z: session.origin.z,
            },
            PendingLight {
                change: native_world::block_light::LightChange::unknown(),
                last_attempt: None,
            },
        );
        assert!(
            session
                .draft_dirty_chunk_with_lighting(neighbor, &source, &test_heightmap_tags(), |_| Ok(
                    (true, false)
                ))
                .is_err()
        );
    }

    #[test]
    fn powered_lamp_updates_block_light_and_preserves_old_snapshot() {
        let mut session = session();
        let air = session.states[0];
        let origin_chunk = BlockPosition {
            x: session.origin.x,
            y: 0,
            z: session.origin.z,
        }
        .chunk();
        for x in 0..=1 {
            for z in 0..=1 {
                let pos = ChunkPos {
                    x: origin_chunk.x + x,
                    z: origin_chunk.z + z,
                };
                let sections = (0..=1)
                    .map(|y| {
                        (
                            y,
                            Arc::new(Section {
                                blocks: Some(Box::new([air; BLOCK_COUNT])),
                                biomes: None,
                                block_light: Some(Box::new([0; LIGHT_BYTES])),
                                sky_light: None,
                            }),
                        )
                    })
                    .collect();
                Arc::make_mut(&mut session.world).chunks.insert(
                    pos,
                    Arc::new(Chunk {
                        block_light_correct: true,
                        position: pos,
                        status: Some("minecraft:full".into()),
                        sections,
                    }),
                );
            }
        }
        let relative = IVec3::new(15, 15, 15);
        let absolute = session.origin + relative;
        let lamp = session.intern_block(state("minecraft:redstone_lamp", &[("lit", "false")]));
        let source = session.intern_block(state("minecraft:redstone_block", &[]));
        assert!(session.set(relative, lamp));
        let old = session.world.clone();
        assert!(session.set(relative + IVec3::X, source));
        assert_eq!(
            redstone_lamp_lit(
                session
                    .world
                    .block(absolute.x, absolute.y, absolute.z)
                    .unwrap()
            ),
            Some(true)
        );
        assert_eq!(
            session
                .world
                .light(absolute.x, absolute.y + 1, absolute.z, false),
            Some(14)
        );
        assert_eq!(
            old.light(absolute.x, absolute.y + 1, absolute.z, false),
            Some(0)
        );
        assert!(session.set(relative + IVec3::X, air));
        for _ in 0..5 {
            session.update(TICK);
        }
        assert_eq!(
            session
                .world
                .light(absolute.x, absolute.y + 1, absolute.z, false),
            Some(0)
        );
        let button_pos = relative + IVec3::X;
        session.set(button_pos + IVec3::X, session.states[3]);
        let kind = native_core::button::Button::from_id("minecraft:stone_button").unwrap();
        let button = session.intern_block(button_state(kind, IVec3::NEG_X, 0.0).unwrap());
        assert!(session.set(button_pos, button));
        assert!(session.use_button(button_pos));
        assert_eq!(
            session
                .world
                .light(absolute.x, absolute.y + 1, absolute.z, false),
            Some(14)
        );
        for _ in 0..25 {
            session.update(TICK);
        }
        assert_eq!(
            session
                .world
                .light(absolute.x, absolute.y + 1, absolute.z, false),
            Some(0)
        );
    }

    #[test]
    fn loaded_session_applies_background_sky_updates_to_snapshots() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let mut session = session();
        session.set_has_skylight(true).unwrap();
        session.set_random_tick_speed(0);
        let air = session.states[0];
        let origin_chunk = BlockPosition {
            x: session.origin.x,
            y: 0,
            z: session.origin.z,
        }
        .chunk();
        for x in 0..=1 {
            for z in 0..=1 {
                let pos = ChunkPos {
                    x: origin_chunk.x + x,
                    z: origin_chunk.z + z,
                };
                let sections = (-1..=2)
                    .map(|y| {
                        (
                            y,
                            Arc::new(Section {
                                blocks: (0..=1).contains(&y).then(|| Box::new([air; BLOCK_COUNT])),
                                biomes: None,
                                block_light: Some(Box::new([0; LIGHT_BYTES])),
                                sky_light: Some(Box::new([0xff; LIGHT_BYTES])),
                            }),
                        )
                    })
                    .collect();
                Arc::make_mut(&mut session.world).chunks.insert(
                    pos,
                    Arc::new(Chunk {
                        position: pos,
                        status: Some("minecraft:full".into()),
                        block_light_correct: true,
                        sections,
                    }),
                );
            }
        }
        let stone = session.intern_block(state("minecraft:stone", &[]));
        let relative = IVec3::new(15, 15, 15);
        assert!(session.set(relative, stone));
        let absolute = session.origin + relative;
        session.update(TICK);
        let old_snapshot = session.snapshot();
        let neighbor = origin_chunk;
        session.fluid_chunks_seen.insert(neighbor);
        let source = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("xPos".into(), Tag::Int(neighbor.x)),
                ("zPos".into(), Tag::Int(neighbor.z)),
                ("Status".into(), Tag::String("minecraft:full".into())),
                ("isLightOn".into(), Tag::Byte(1)),
                (
                    "sections".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: (-1..=2)
                            .map(|y| {
                                let mut fields = vec![
                                    ("Y".into(), Tag::Byte(y)),
                                    ("BlockLight".into(), Tag::ByteArray(vec![0; LIGHT_BYTES])),
                                    ("SkyLight".into(), Tag::ByteArray(vec![0xff; LIGHT_BYTES])),
                                    ("opaque".into(), Tag::Int(17)),
                                ];
                                if (0..=1).contains(&y) {
                                    fields.push((
                                        "block_states".into(),
                                        Tag::Compound(vec![(
                                            "palette".into(),
                                            Tag::List {
                                                element_type: TagType::String,
                                                values: vec![Tag::String("minecraft:air".into())],
                                            },
                                        )]),
                                    ));
                                }
                                Tag::Compound(fields)
                            })
                            .collect(),
                    },
                ),
            ]),
        };
        assert!(
            session
                .draft_dirty_chunk_with_lighting(neighbor, &source, &test_heightmap_tags(), |_| Ok(
                    (true, false)
                ))
                .is_err()
        );
        session.sky_lighting.wait_for_worker();
        session.update(TICK);
        let new_snapshot = session.snapshot();
        let SessionWorld::Loaded(old) = &old_snapshot.world else {
            panic!("loaded world expected")
        };
        let SessionWorld::Loaded(new) = &new_snapshot.world else {
            panic!("loaded world expected")
        };
        assert_eq!(old.light(absolute.x, 14, absolute.z, true), Some(15));
        assert_eq!(new.light(absolute.x, 14, absolute.z, true), Some(14));
        assert!(new_snapshot.world_revision > old_snapshot.world_revision);
        let draft = session
            .draft_dirty_chunk_with_lighting(neighbor, &source, &test_heightmap_tags(), |state| {
                Ok((state.name.matches("minecraft:air"), false))
            })
            .unwrap();
        let sections =
            native_persistence::palette::decode_sections(&draft.document().value).unwrap();
        assert!(sections.iter().any(|section| {
            section
                .sky_light
                .as_ref()
                .is_some_and(|data| data.iter().any(|&byte| byte != 0xff))
        }));
        for section in sections {
            assert_eq!(
                section.sky_light.as_deref(),
                new.chunks[&neighbor].sections[&section.y]
                    .sky_light
                    .as_deref()
                    .map(|a| a.as_slice())
            );
        }
    }

    #[test]
    fn ore_light_changes_update_neighbor_chunks_and_preserve_snapshots() {
        let mut session = session();
        let air = session.states[0];
        let origin_chunk = BlockPosition {
            x: session.origin.x,
            y: 0,
            z: session.origin.z,
        }
        .chunk();
        for x in 0..=1 {
            for z in 0..=1 {
                let pos = ChunkPos {
                    x: origin_chunk.x + x,
                    z: origin_chunk.z + z,
                };
                let sections = (0..=1)
                    .map(|y| {
                        (
                            y,
                            Arc::new(Section {
                                blocks: Some(Box::new([air; BLOCK_COUNT])),
                                biomes: None,
                                block_light: Some(Box::new([0; LIGHT_BYTES])),
                                sky_light: None,
                            }),
                        )
                    })
                    .collect();
                Arc::make_mut(&mut session.world).chunks.insert(
                    pos,
                    Arc::new(Chunk {
                        block_light_correct: true,
                        position: pos,
                        status: Some("minecraft:full".into()),
                        sections,
                    }),
                );
            }
        }
        let ore = session.intern_block(state("minecraft:redstone_ore", &[("lit", "false")]));
        let relative = IVec3::new(15, 15, 15);
        assert!(session.set(relative, ore));
        session.dirty_chunks.clear();
        let old = session.world.clone();
        assert!(session.set_redstone_ore_lit(relative, true));
        let absolute = session.origin + relative;
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(8)
        );
        assert_eq!(
            old.light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(0)
        );
        assert!(session.dirty_chunks.contains(&ChunkPos {
            x: origin_chunk.x + 1,
            z: origin_chunk.z
        }));
        assert!(session.set_redstone_ore_lit(relative, false));
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(0)
        );

        let torch = session.intern_block(state("minecraft:torch", &[]));
        let air = session.states[0];
        assert!(session.set(relative, air));
        assert!(session.set(relative, torch));
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(13)
        );
        let stone = session.intern_block(state("minecraft:stone", &[]));
        assert!(session.set(relative, stone));
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(0)
        );
        assert!(session.set(relative, air));
        assert!(session.set(relative - IVec3::X, torch));
        let bottom = session.intern_block(state(
            "minecraft:stone_slab",
            &[("type", "bottom"), ("waterlogged", "false")],
        ));
        let top = session.intern_block(state(
            "minecraft:stone_slab",
            &[("type", "top"), ("waterlogged", "false")],
        ));
        assert!(session.set(relative, bottom));
        assert!(session.set(relative + IVec3::X, bottom));
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(12)
        );
        assert!(session.set(relative + IVec3::X, top));
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(10)
        );
        assert!(session.set(relative, top));
        let snow_1 = session.intern_block(state("minecraft:snow", &[("layers", "1")]));
        let snow_7 = session.intern_block(state("minecraft:snow", &[("layers", "7")]));
        assert!(session.set(relative + IVec3::X, snow_1));
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(12)
        );
        assert!(session.set(relative + IVec3::X, snow_7));
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(10)
        );
        let mushroom_pos = IVec3::new(15, 30, 15);
        let mushroom_absolute = session.origin + mushroom_pos;
        let mushroom = session.intern_block(state("minecraft:brown_mushroom", &[]));
        assert!(session.set(mushroom_pos, mushroom));
        assert_eq!(
            session.world.light(
                mushroom_absolute.x,
                mushroom_absolute.y,
                mushroom_absolute.z,
                false
            ),
            Some(1)
        );
        assert!(session.set(mushroom_pos, air));
        assert_eq!(
            session.world.light(
                mushroom_absolute.x,
                mushroom_absolute.y,
                mushroom_absolute.z,
                false
            ),
            Some(0)
        );
    }

    #[test]
    fn deferred_overlapping_light_changes_recover_when_neighbor_streams_in() {
        let mut session = session();
        let air = session.states[0];
        let origin_chunk = BlockPosition {
            x: session.origin.x,
            y: 0,
            z: session.origin.z,
        }
        .chunk();
        for x in 0..=1 {
            for z in 0..=1 {
                let pos = ChunkPos {
                    x: origin_chunk.x + x,
                    z: origin_chunk.z + z,
                };
                let sections = (0..=1)
                    .map(|y| {
                        (
                            y,
                            Arc::new(Section {
                                blocks: Some(Box::new([air; BLOCK_COUNT])),
                                biomes: None,
                                block_light: None,
                                sky_light: None,
                            }),
                        )
                    })
                    .collect();
                Arc::make_mut(&mut session.world).chunks.insert(
                    pos,
                    Arc::new(Chunk {
                        position: pos,
                        status: Some("minecraft:full".into()),
                        block_light_correct: true,
                        sections,
                    }),
                );
            }
        }
        let torch = session.intern_block(state("minecraft:torch", &[]));
        let a = IVec3::new(14, 15, 15);
        let b = IVec3::new(15, 15, 15);
        assert!(session.set(a, torch));
        assert!(session.set(b, torch));
        assert!(session.pending_light.is_empty());
        let before = session.world.clone();
        let neighbor = ChunkPos {
            x: origin_chunk.x + 1,
            z: origin_chunk.z,
        };
        Arc::make_mut(&mut session.world)
            .chunks
            .remove(&neighbor)
            .unwrap();
        assert!(session.set(a, air));
        assert!(session.set(b, air));
        assert_eq!(session.pending_light.len(), 2);
        let absolute = session.origin + b;
        assert_eq!(
            session
                .world
                .light(absolute.x, absolute.y, absolute.z, false),
            Some(14)
        );

        session.queue_loaded_chunk(neighbor, (*before).clone());
        session.update(TICK);
        assert!(session.pending_light.is_empty());
        assert_eq!(
            session
                .world
                .light(absolute.x, absolute.y, absolute.z, false),
            Some(0)
        );
        assert_eq!(
            session
                .world
                .light(absolute.x + 1, absolute.y, absolute.z, false),
            Some(0)
        );
        assert_eq!(
            before.light(absolute.x, absolute.y, absolute.z, false),
            Some(14)
        );
        let unknown = session.intern_block(state("minecraft:unknown_test_block", &[]));
        assert!(session.set(b, unknown));
        assert_eq!(session.pending_light.len(), 1);
        assert!(session.set(b, air));
        session.update(TICK);
        assert!(session.pending_light.is_empty());
    }

    #[test]
    fn session_updates_block_light_at_both_build_height_limits() {
        let mut session = session();
        let air = session.states[0];
        let origin_chunk = BlockPosition {
            x: session.origin.x,
            y: 0,
            z: session.origin.z,
        }
        .chunk();
        for x in 0..=1 {
            for z in 0..=1 {
                let pos = ChunkPos {
                    x: origin_chunk.x + x,
                    z: origin_chunk.z + z,
                };
                let sections = (0..=1)
                    .map(|y| {
                        (
                            y,
                            Arc::new(Section {
                                blocks: Some(Box::new([air; BLOCK_COUNT])),
                                biomes: None,
                                block_light: None,
                                sky_light: None,
                            }),
                        )
                    })
                    .collect();
                Arc::make_mut(&mut session.world).chunks.insert(
                    pos,
                    Arc::new(Chunk {
                        position: pos,
                        status: Some("minecraft:full".into()),
                        block_light_correct: true,
                        sections,
                    }),
                );
            }
        }
        let torch = session.intern_block(state("minecraft:torch", &[]));
        for y in [0, 31] {
            let relative = IVec3::new(15, y, 15);
            let absolute = session.origin + relative;
            let outside = if y == 0 { -1 } else { 32 };
            assert!(session.set(relative, torch));
            assert!(session.pending_light.is_empty());
            assert_eq!(
                session.world.light(absolute.x, outside, absolute.z, false),
                Some(13)
            );
            assert!(session.set(relative, air));
            assert_eq!(
                session.world.light(absolute.x, outside, absolute.z, false),
                Some(0)
            );
        }
    }

    #[test]
    fn player_friction_tracks_support_at_edges_and_across_rebase() {
        let mut session = session();
        let ice = session.intern_block(state("minecraft:ice", &[]));
        assert!(session.set(IVec3::new(4, 0, 4), ice));
        assert!(session.set(IVec3::new(5, 0, 4), session.states[0]));
        session.motion.position = DVec3::new(5.05, 1.0, 4.5);
        session.motion.velocity = DVec3::ZERO;
        session.motion.on_ground = false;
        session.player.position = session.motion.position.as_vec3();
        session.player.on_ground = false;
        session.update(TICK * 2);
        assert!(session.motion.on_ground);
        assert_eq!(
            session.ground_support,
            Some(session.origin + IVec3::new(4, 0, 4))
        );
        assert_eq!(session.friction_below(), 0.98);
        session.motion.velocity.z = 0.1;
        session.update(TICK);
        let expected = 0.1 * f64::from(0.98_f32 * 0.91_f32);
        assert!((session.motion.velocity.z - expected).abs() < 1.0e-10);

        let slime = session.intern_block(state("minecraft:slime_block", &[]));
        assert!(session.set(IVec3::new(4, 0, 4), slime));
        assert_eq!(session.friction_below(), 0.8);
        assert!(session.set(IVec3::new(4, 0, 4), ice));

        let support = session.ground_support;
        session.origin.x += 16;
        session.motion.position.x -= 16.0;
        assert_eq!(session.ground_support, support);
        assert_eq!(session.friction_below(), 0.98);
    }

    #[test]
    fn player_bounces_on_slime_unless_sneaking_or_suppressed() {
        for (name, sneaking, suppressed, bounces, start_y) in [
            ("minecraft:slime_block", false, false, true, 2.2),
            ("minecraft:slime_block", true, false, false, 2.2),
            ("minecraft:slime_block", false, true, false, 2.2),
            ("minecraft:stone", false, false, false, 2.2),
            ("minecraft:red_bed", false, false, true, 2.0),
        ] {
            let mut session = session();
            let block = session.intern_block(if name == "minecraft:red_bed" {
                state(
                    name,
                    &[("facing", "north"), ("part", "head"), ("occupied", "false")],
                )
            } else {
                state(name, &[])
            });
            assert!(session.set(IVec3::new(4, 1, 4), block));
            if suppressed {
                session.set_bounce_suppression_tag(Arc::new(BTreeSet::from([name.into()])));
            }
            session.motion.position = DVec3::new(4.5, start_y, 4.5);
            session.motion.velocity = DVec3::new(0.0, -0.5, 0.0);
            session.motion.on_ground = false;
            session.player.position = session.motion.position.as_vec3();
            session.player.on_ground = false;
            session.sneak = sneaking;
            session.update(TICK);
            assert!(session.motion.on_ground, "{name}");
            assert_eq!(
                session.motion.velocity.y > 0.0,
                bounces,
                "{name} sneaking={sneaking} suppressed={suppressed}"
            );
            let landed = session.motion.position.y;
            session.update(TICK);
            assert_eq!(session.motion.position.y > landed + 1e-6, bounces, "{name}");
        }
    }

    #[test]
    fn player_bounciness_tracks_saved_and_equipped_modifiers() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let document = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![(
                "attributes".into(),
                Tag::List {
                    element_type: TagType::Compound,
                    values: vec![Tag::Compound(vec![
                        ("id".into(), Tag::String("minecraft:bounciness".into())),
                        ("base".into(), Tag::Double(0.1)),
                    ])],
                },
            )]),
        };
        let mut session = session();
        session
            .set_saved_bounciness(
                crate::player_data::read_saved_bounciness_attribute(&document).unwrap(),
            )
            .unwrap();
        let component = Tag::Compound(vec![(
            "minecraft:attribute_modifiers".into(),
            Tag::List {
                element_type: TagType::Compound,
                values: vec![Tag::Compound(vec![
                    ("type".into(), Tag::String("minecraft:bounciness".into())),
                    ("id".into(), Tag::String("example:bounce".into())),
                    ("operation".into(), Tag::String("add_value".into())),
                    ("amount".into(), Tag::Double(0.4)),
                    ("slot".into(), Tag::String("head".into())),
                ])],
            },
        )]);
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            crate::inventory::PlayerSlot::Armor(0),
            ItemStack::unresolved("minecraft:iron_helmet".into(), 1, component),
        );
        session.set_player_inventory(inventory);
        session.refresh_bounciness();
        assert_eq!(session.bounciness, Some(0.5));
        let mut replacement = PlayerInventory::default();
        replacement.set_slot(
            crate::inventory::PlayerSlot::Armor(0),
            ItemStack::new("minecraft:stone".into(), 1, 64, Tag::Compound(vec![])),
        );
        assert_eq!(replacement.revision(), session.inventory.revision());
        session.set_player_inventory(replacement);
        session.refresh_bounciness();
        assert_eq!(session.bounciness, Some(0.1));
        Arc::make_mut(&mut session.inventory)
            .set_slot(crate::inventory::PlayerSlot::Armor(0), None);
        session.refresh_bounciness();
        assert_eq!(session.bounciness, Some(0.1));
    }

