    #[test]
    fn player_bounciness_reflects_from_solid_walls_and_ceilings() {
        for (wall, direction) in [
            (true, DVec3::new(0.5, 0.0, 0.0)),
            (false, DVec3::new(0.0, 0.5, 0.0)),
        ] {
            let mut session = session();
            session
                .set_saved_bounciness(crate::player_data::SavedAttribute::with_base(0.5))
                .unwrap();
            let stone = session.states[3];
            let collision = if wall {
                IVec3::new(5, 2, 4)
            } else {
                IVec3::new(4, 4, 4)
            };
            assert!(session.set(collision, stone));
            session.motion.position = if wall {
                DVec3::new(4.5, 2.2, 4.5)
            } else {
                DVec3::new(4.5, 2.0, 4.5)
            };
            session.motion.velocity = direction;
            session.motion.on_ground = false;
            session.player.position = session.motion.position.as_vec3();
            session.update(TICK);
            let component = if wall {
                session.motion.velocity.x
            } else {
                session.motion.velocity.y
            };
            assert!(component < 0.0, "wall={wall}: {component}");
        }
    }

    #[test]
    fn player_bounciness_applies_to_submerged_collisions() {
        for liquid in ["minecraft:water", "minecraft:lava"] {
            for (block, position, velocity, axis) in [
                (
                    IVec3::new(5, 2, 4),
                    DVec3::new(4.5, 2.2, 4.5),
                    DVec3::X * 0.5,
                    0,
                ),
                (
                    IVec3::new(4, 4, 4),
                    DVec3::new(4.5, 2.0, 4.5),
                    DVec3::Y * 0.5,
                    1,
                ),
                (
                    IVec3::new(4, 1, 4),
                    DVec3::new(4.5, 2.2, 4.5),
                    DVec3::Y * -0.5,
                    2,
                ),
            ] {
                let mut session = liquid_session(liquid);
                session.set_bounce_suppression_tag(Arc::new(BTreeSet::new()));
                session
                    .set_saved_bounciness(crate::player_data::SavedAttribute::with_base(0.5))
                    .unwrap();
                assert!(session.set(block, session.states[3]));
                session.motion.position = position;
                session.motion.velocity = velocity;
                session.motion.on_ground = false;
                session.player.position = position.as_vec3();
                session.update(TICK);
                let result = if axis == 0 {
                    session.motion.velocity.x
                } else {
                    session.motion.velocity.y
                };
                assert!(
                    if axis == 2 {
                        result > 0.0
                    } else {
                        result < 0.0
                    },
                    "{liquid} axis={axis}: {result}"
                );
            }
        }
    }

    fn saved_chest_fixture() -> (LoadedSession, World, IVec3, ChunkPos) {
        use native_persistence::nbt::{self, NamedTag, Tag, TagType};
        use native_world::loaded::SavedBlockEntities;
        let (mut world, origin, player) = fixture();
        let position = origin + IVec3::new(8, 2, 6);
        let home = ChunkPos {
            x: position.x.div_euclid(16),
            z: position.z.div_euclid(16),
        };
        let block = world.intern_state(state(
            "minecraft:chest",
            &[
                ("facing", "north"),
                ("type", "single"),
                ("waterlogged", "false"),
            ],
        ));
        world
            .set_block_id(position.x, position.y, position.z, block)
            .unwrap();
        let entity = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:chest".into())),
            ("x".into(), Tag::Int(position.x)),
            ("y".into(), Tag::Int(position.y)),
            ("z".into(), Tag::Int(position.z)),
            (
                "Items".into(),
                Tag::List {
                    element_type: TagType::Compound,
                    values: vec![Tag::Compound(vec![
                        ("Slot".into(), Tag::Byte(3)),
                        ("id".into(), Tag::String("minecraft:diamond".into())),
                        ("count".into(), Tag::Int(5)),
                    ])],
                },
            ),
        ]);
        let bytes = nbt::write(&NamedTag {
            name: "".into(),
            value: Tag::List {
                element_type: TagType::Compound,
                values: vec![entity],
            },
        })
        .unwrap();
        world
            .saved_block_entities
            .insert(home, SavedBlockEntities::Encoded(bytes.into()));
        let source = world.clone();
        let mut session = LoadedSession::new(
            world,
            origin,
            BuildBounds {
                min_y: 0,
                max_y: 32,
            },
            player,
        )
        .unwrap();
        session.set_falling_fire_tag(Arc::new(BTreeSet::new()));
        session.set_bounce_suppression_tag(Arc::new(BTreeSet::new()));
        session.set_farmland_maintainers(Arc::new(BTreeSet::new()));
        (session, source, position, home)
    }

    fn trapped_chest_fixture() -> (LoadedSession, IVec3, ChunkPos) {
        use native_persistence::nbt::{self, Tag};
        use native_world::loaded::SavedBlockEntities;
        let (mut session, _, position, chunk) = saved_chest_fixture();
        let id = session.intern_block(state(
            "minecraft:trapped_chest",
            &[
                ("facing", "north"),
                ("type", "single"),
                ("waterlogged", "false"),
            ],
        ));
        assert!(session.set(position - session.origin, id));
        let SavedBlockEntities::Encoded(bytes) =
            session.world.saved_block_entities.get(&chunk).unwrap()
        else {
            panic!("expected saved entity")
        };
        let mut doc = nbt::read(bytes).unwrap();
        let Tag::List { values, .. } = &mut doc.value else {
            panic!("expected list")
        };
        let Tag::Compound(fields) = &mut values[0] else {
            panic!("expected chest")
        };
        fields
            .iter_mut()
            .find(|(name, _)| name.matches("id"))
            .unwrap()
            .1 = Tag::String("minecraft:trapped_chest".into());
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(
                chunk,
                SavedBlockEntities::Encoded(nbt::write(&doc).unwrap().into()),
            );
        session.set_random_tick_speed(0);
        (session, position, chunk)
    }

    #[test]
    fn placed_chests_open_and_consume_the_correct_hand() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::Tag;
        use native_world::loaded::SavedBlockEntities;
        for name in ["minecraft:chest", "minecraft:trapped_chest"] {
            for hand in [PlayerSlot::Storage(0), PlayerSlot::Offhand] {
                for mode in [GameMode::Survival, GameMode::Creative, GameMode::Adventure] {
                    let mut session = session();
                    let chunk = session.player_chunk().unwrap();
                    Arc::make_mut(&mut session.world)
                        .saved_block_entities
                        .insert(chunk, SavedBlockEntities::Empty);
                    let mut inventory = PlayerInventory::default();
                    inventory.set_slot(
                        hand,
                        ItemStack::new(name.into(), 2, 64, Tag::Compound(vec![])),
                    );
                    session.set_player_inventory(inventory);
                    session.set_game_mode(mode);
                    session.submit_command(PlayerCommand::Place);
                    session.update(TICK);
                    let target = session.origin + IVec3::new(8, 2, 7);
                    let block = session.world.block(target.x, target.y, target.z).unwrap();
                    if mode == GameMode::Adventure {
                        assert_eq!(block.name, "minecraft:air");
                        assert_eq!(session.inventory.slot(hand).unwrap().count(), 2);
                        continue;
                    }
                    assert_eq!(block.name, name);
                    assert_eq!(
                        block.properties.get("type").map(String::as_str),
                        Some("single")
                    );
                    assert_eq!(
                        session.inventory.slot(hand).unwrap().count(),
                        if mode == GameMode::Creative { 2 } else { 1 }
                    );
                    session.submit_command(PlayerCommand::Place);
                    session.update(TICK);
                    assert!(
                        matches!(session.inventory.menu(), Some(InventoryMenu::Chest { position, other: None }) if position == target)
                    );
                    assert!(session.inventory.slot(PlayerSlot::Chest(0)).is_none());
                    if name == "minecraft:trapped_chest" {
                        assert_eq!(
                            session.redstone_source(target - session.origin, IVec3::Y),
                            Some((1, 1, false))
                        );
                    }
                    if mode == GameMode::Creative {
                        session.submit_command(PlayerCommand::ToggleInventory);
                        session.update(TICK);
                        session.submit_command(PlayerCommand::Break);
                        session.update(TICK);
                        assert_eq!(
                            session
                                .world
                                .block(target.x, target.y, target.z)
                                .unwrap()
                                .name,
                            "minecraft:air"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn placed_chests_join_and_keep_separate_inventories() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::Tag;
        use native_world::loaded::SavedBlockEntities;
        let mut session = session();
        let chunk = session.player_chunk().unwrap();
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(chunk, SavedBlockEntities::Empty);
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new("minecraft:chest".into(), 2, 64, Tag::Compound(vec![])),
        );
        session.set_player_inventory(inventory);
        for x in [5, 6] {
            let hit = ShapeRayHit {
                position: IVec3::new(x, 0, 5),
                face: IVec3::Y,
                location: DVec3::ZERO,
                inside: false,
            };
            assert_eq!(session.place_chest(hit), Some(PlayerSlot::Storage(0)));
        }
        let first = IVec3::new(5, 1, 5);
        let second = IVec3::new(6, 1, 5);
        let state_at = |relative: IVec3| {
            let p = session.origin + relative;
            session.world.block(p.x, p.y, p.z).unwrap().properties["type"].clone()
        };
        assert_eq!(state_at(first), "right");
        assert_eq!(state_at(second), "left");
        assert!(session.try_open_saved_chest(first));
        assert!(matches!(
            session.inventory.menu(),
            Some(InventoryMenu::Chest { other: Some(_), .. })
        ));
        assert!(session.inventory.slot(PlayerSlot::Chest(53)).is_none());
        let inventory = Arc::make_mut(&mut session.inventory);
        assert!(inventory.set_slot(
            PlayerSlot::Chest(0),
            ItemStack::new("minecraft:diamond".into(), 5, 64, Tag::Compound(vec![]))
        ));
        assert!(inventory.set_slot(
            PlayerSlot::Chest(27),
            ItemStack::new("minecraft:dirt".into(), 3, 64, Tag::Compound(vec![]))
        ));
        assert!(inventory.toggle());
        session.collect_closed_chest();
        session.set_game_mode(GameMode::Creative);
        let absolute = session.origin + first;
        session.finish_breaking(absolute);
        assert_eq!(
            session
                .world
                .block(absolute.x, absolute.y, absolute.z)
                .unwrap()
                .name,
            "minecraft:air"
        );
        let other = session.origin + second;
        assert_eq!(
            session
                .world
                .block(other.x, other.y, other.z)
                .unwrap()
                .properties["type"],
            "single"
        );
        assert!(session.try_open_saved_chest(second));
        assert_eq!(
            session.inventory.slot(PlayerSlot::Chest(0)).unwrap().id(),
            "minecraft:dirt"
        );
        assert_eq!(
            session
                .dropped_items
                .snapshot()
                .iter()
                .map(|item| (item.stack.id(), item.stack.count()))
                .collect::<Vec<_>>(),
            vec![("minecraft:diamond", 5)]
        );
    }

    #[test]
    fn placed_chests_preserve_literal_and_styled_names() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::{Tag, TagType};
        use native_world::loaded::SavedBlockEntities;
        let names = [
            Tag::String("보관함 ♠".into()),
            Tag::Compound(vec![
                ("text".into(), Tag::String("treasure".into())),
                ("bold".into(), Tag::Byte(1)),
            ]),
        ];
        for id in ["minecraft:chest", "minecraft:trapped_chest"] {
            for hand in [PlayerSlot::Storage(0), PlayerSlot::Offhand] {
                for name in &names {
                    let mut session = session();
                    let chunk = session.player_chunk().unwrap();
                    Arc::make_mut(&mut session.world)
                        .saved_block_entities
                        .insert(chunk, SavedBlockEntities::Empty);
                    let mut inventory = PlayerInventory::default();
                    let original = ItemStack::new(
                        id.into(),
                        1,
                        64,
                        Tag::Compound(vec![
                            ("minecraft:custom_name".into(), name.clone()),
                            (
                                "minecraft:container".into(),
                                Tag::List {
                                    element_type: TagType::Compound,
                                    values: vec![Tag::Compound(vec![
                                        ("slot".into(), Tag::Int(4)),
                                        (
                                            "item".into(),
                                            Tag::Compound(vec![
                                                (
                                                    "id".into(),
                                                    Tag::String("minecraft:diamond".into()),
                                                ),
                                                ("count".into(), Tag::Int(3)),
                                            ]),
                                        ),
                                    ])],
                                },
                            ),
                        ]),
                    )
                    .unwrap();
                    let restored = crate::player_data::read_stack(
                        &crate::player_data::encode_stack(&original, None),
                    )
                    .unwrap();
                    assert_eq!(restored.max_count(), Some(64));
                    inventory.set_slot(hand, Some(restored));
                    session.set_player_inventory(inventory);
                    session.submit_command(PlayerCommand::Place);
                    session.update(TICK);
                    let pos = session.origin + IVec3::new(8, 2, 7);
                    assert_eq!(
                        session.saved_chest(pos).unwrap().unwrap().custom_name(),
                        Some(name)
                    );
                    assert!(session.inventory.slot(hand).is_none());
                    session.submit_command(PlayerCommand::Place);
                    session.update(TICK);
                    assert!(
                        matches!(session.inventory.menu(), Some(InventoryMenu::Chest { position, .. }) if position == pos)
                    );
                    assert_eq!(
                        session.snapshot().inventory.chest_title_component(),
                        Some(name)
                    );
                    assert_eq!(
                        session.inventory.slot(PlayerSlot::Chest(4)).unwrap().id(),
                        "minecraft:diamond"
                    );
                    assert_eq!(
                        session
                            .inventory
                            .slot(PlayerSlot::Chest(4))
                            .unwrap()
                            .count(),
                        3
                    );
                    assert_eq!(
                        session.inventory.chest_title(),
                        if matches!(name, Tag::String(_)) {
                            Some("보관함 ♠")
                        } else {
                            None
                        }
                    );
                }
            }
        }
    }

