    #[test]
    fn locked_chests_check_main_hand_and_both_halves() {
        use native_persistence::nbt::{self, Tag};
        use native_world::loaded::SavedBlockEntities;
        let (mut session, _, left, chunk) = saved_chest_fixture();
        session.set_player_inventory(PlayerInventory::default());
        let SavedBlockEntities::Encoded(bytes) = &session.world.saved_block_entities[&chunk] else {
            panic!()
        };
        let mut data = nbt::read(bytes).unwrap();
        let Tag::List { values, .. } = &mut data.value else {
            panic!()
        };
        let Tag::Compound(first) = &mut values[0] else {
            panic!()
        };
        first.push((
            "lock".into(),
            Tag::Compound(vec![
                ("items".into(), Tag::String("minecraft:diamond".into())),
                (
                    "count".into(),
                    Tag::Compound(vec![("min".into(), Tag::Int(2))]),
                ),
            ]),
        ));
        first.push(("CustomName".into(), Tag::String("Left".into())));
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(
                chunk,
                SavedBlockEntities::Encoded(nbt::write(&data).unwrap().into()),
            );
        assert!(!session.try_open_saved_chest(left - session.origin));
        let message = session.locked_chest_message.as_ref().unwrap();
        assert!(!message.double_chest);
        assert_eq!(message.custom_name, Some(Tag::String("Left".into())));
        let event = session.take_locked_chest_sounds().pop().unwrap();
        assert_eq!(event.position, left.as_dvec3() + DVec3::splat(0.5));
        session.submit_command(PlayerCommand::Place);
        session.update(TICK);
        assert_eq!(
            session
                .snapshot()
                .locked_chest_message
                .as_ref()
                .unwrap()
                .custom_name,
            Some(Tag::String("Left".into()))
        );
        assert_eq!(session.take_locked_chest_sounds().len(), 1);
        let diamond =
            |count| ItemStack::new("minecraft:diamond".into(), count, 64, Tag::Compound(vec![]));
        Arc::make_mut(&mut session.inventory)
            .set_slot(crate::inventory::PlayerSlot::Offhand, diamond(3));
        assert!(!session.try_open_saved_chest(left - session.origin));
        Arc::make_mut(&mut session.inventory)
            .set_slot(crate::inventory::PlayerSlot::Storage(0), diamond(2));
        assert!(session.try_open_saved_chest(left - session.origin));
        assert!(Arc::make_mut(&mut session.inventory).toggle());
        session.collect_closed_chest();
        let right = left + IVec3::X;
        for (position, kind) in [(left, "left"), (right, "right")] {
            let id = session.intern_block(state(
                "minecraft:chest",
                &[
                    ("facing", "north"),
                    ("type", kind),
                    ("waterlogged", "false"),
                ],
            ));
            assert!(session.set(position - session.origin, id));
        }
        let Tag::List { values, .. } = &mut data.value else {
            panic!()
        };
        values.push(Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:chest".into())),
            ("x".into(), Tag::Int(right.x)),
            ("y".into(), Tag::Int(right.y)),
            ("z".into(), Tag::Int(right.z)),
            ("CustomName".into(), Tag::String("Right".into())),
            (
                "lock".into(),
                Tag::Compound(vec![
                    ("items".into(), Tag::String("minecraft:diamond".into())),
                    (
                        "count".into(),
                        Tag::Compound(vec![("min".into(), Tag::Int(3))]),
                    ),
                ]),
            ),
        ]));
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(
                chunk,
                SavedBlockEntities::Encoded(nbt::write(&data).unwrap().into()),
            );
        assert!(!session.try_open_saved_chest(left - session.origin));
        let message = session.locked_chest_message.as_ref().unwrap();
        assert!(message.double_chest);
        assert_eq!(message.custom_name, Some(Tag::String("Right".into())));
        let event = session.take_locked_chest_sounds().pop().unwrap();
        assert_eq!(
            event.position,
            (left.as_dvec3() + right.as_dvec3()) * 0.5 + DVec3::splat(0.5)
        );
        assert!(!session.try_open_saved_chest(right - session.origin));
        Arc::make_mut(&mut session.inventory)
            .set_slot(crate::inventory::PlayerSlot::Storage(0), diamond(3));
        assert!(session.try_open_saved_chest(right - session.origin));
        assert!(Arc::make_mut(&mut session.inventory).toggle());
        session.collect_closed_chest();
        Arc::make_mut(&mut session.inventory)
            .set_slot(crate::inventory::PlayerSlot::Storage(0), None);
        session.set_game_mode(GameMode::Spectator);
        assert!(session.try_open_saved_chest(left - session.origin));
    }

    #[test]
    #[cfg(target_os = "windows")]
    #[ignore = "requires Minecraft 26.3 item registry"]
    fn chest_lock_uses_active_data_pack_item_tag() {
        use native_persistence::nbt::{self, Tag};
        use native_resources::packs::{ResourceId, ResourceProvider, ResourceStack};
        use native_world::loaded::SavedBlockEntities;

        struct Tags;
        impl ResourceProvider for Tags {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn list_data(&mut self, folder: &str) -> anyhow::Result<Vec<ResourceId>> {
                Ok(if folder == "tags/item" {
                    vec![ResourceId::parse("example:keys")?]
                } else {
                    vec![]
                })
            }
            fn read_data_stack(&mut self, path: &str) -> anyhow::Result<Vec<Vec<u8>>> {
                Ok(if path == "data/example/tags/item/keys.json" {
                    vec![
                        br#"{"values":["minecraft:stone"]}"#.to_vec(),
                        br#"{"replace":true,"values":["minecraft:diamond"]}"#.to_vec(),
                    ]
                } else {
                    vec![]
                })
            }
        }

        let game = std::env::var_os("MINECRAFT_DIR")
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let mut resources = ResourceStack::open(&game).unwrap();
        let registry = Arc::new(resources.vanilla_item_registry().unwrap());
        let recipes = Arc::new(CraftingRecipes::load(&mut Tags).unwrap());
        let (mut session, _, position, chunk) = saved_chest_fixture();
        session.set_player_inventory(PlayerInventory::default());
        let SavedBlockEntities::Encoded(bytes) = &session.world.saved_block_entities[&chunk] else {
            panic!()
        };
        let mut data = nbt::read(bytes).unwrap();
        let Tag::List { values, .. } = &mut data.value else {
            panic!()
        };
        let Tag::Compound(fields) = &mut values[0] else {
            panic!()
        };
        fields.push((
            "lock".into(),
            Tag::Compound(vec![("items".into(), Tag::String("#example:keys".into()))]),
        ));
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(
                chunk,
                SavedBlockEntities::Encoded(nbt::write(&data).unwrap().into()),
            );
        let relative = position - session.origin;
        let stack = |id: &str| ItemStack::new(id.into(), 1, 64, Tag::Compound(vec![]));
        Arc::make_mut(&mut session.inventory).set_slot(
            crate::inventory::PlayerSlot::Storage(0),
            stack("minecraft:diamond"),
        );
        assert!(!session.try_open_saved_chest(relative));
        session.set_item_registry(registry);
        session.set_crafting_recipes(recipes);
        Arc::make_mut(&mut session.inventory).set_slot(
            crate::inventory::PlayerSlot::Storage(0),
            stack("minecraft:stone"),
        );
        assert!(!session.try_open_saved_chest(relative));
        assert!(session.locked_chest_message.is_some());
        Arc::make_mut(&mut session.inventory).set_slot(
            crate::inventory::PlayerSlot::Storage(0),
            stack("minecraft:diamond"),
        );
        assert!(session.try_open_saved_chest(relative));
    }

