    #[test]
    fn banner_input_preserves_components_snapshot_and_staged_chunk() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::{self, Tag, TagType};
        use native_world::loaded::SavedBlockEntities;
        for hand in [PlayerSlot::Storage(0), PlayerSlot::Offhand] {
            for mode in [GameMode::Survival, GameMode::Creative, GameMode::Adventure] {
                let mut session = session();
                let chunk = session.player_chunk().unwrap();
                Arc::make_mut(&mut session.world)
                    .saved_block_entities
                    .insert(chunk, SavedBlockEntities::Empty);
                let patterns = Tag::List {
                    element_type: TagType::Compound,
                    values: vec![Tag::Compound(vec![
                        ("pattern".into(), Tag::String("minecraft:cross".into())),
                        ("color".into(), Tag::String("blue".into())),
                    ])],
                };
                let components = Tag::Compound(vec![
                    ("minecraft:banner_patterns".into(), patterns.clone()),
                    ("minecraft:custom_name".into(), Tag::String("Named".into())),
                    (
                        "minecraft:custom_data".into(),
                        Tag::Compound(vec![("future".into(), Tag::Int(42))]),
                    ),
                ]);
                let mut inventory = PlayerInventory::default();
                inventory.set_slot(
                    hand,
                    ItemStack::new("minecraft:red_banner".into(), 2, 16, components.clone()),
                );
                session.set_player_inventory(inventory);
                session.set_game_mode(mode);
                let before = session.snapshot();
                let source = fixture_chunk_document(chunk);
                let source_bytes = nbt::write(&source).unwrap();
                session.submit_command(PlayerCommand::Place);
                session.update(TICK);
                let position = session.origin + IVec3::new(8, 2, 7);
                let state = session
                    .world
                    .block(position.x, position.y, position.z)
                    .unwrap();
                if mode == GameMode::Adventure {
                    assert_eq!(state.name, "minecraft:air");
                    assert_eq!(session.inventory.slot(hand).unwrap().count(), 2);
                    continue;
                }
                assert_eq!(state.name, "minecraft:red_wall_banner");
                assert_eq!(state.properties.get("facing").unwrap(), "south");
                assert_eq!(
                    session.inventory.slot(hand).unwrap().count(),
                    if mode == GameMode::Creative { 2 } else { 1 }
                );
                assert!(matches!(
                    before.world.loaded().unwrap().saved_block_entities[&chunk],
                    SavedBlockEntities::Empty
                ));
                assert!(
                    before
                        .world
                        .loaded()
                        .unwrap()
                        .live_block_entities
                        .is_empty()
                );
                assert!(matches!(
                    session.world.saved_block_entities[&chunk],
                    SavedBlockEntities::Empty
                ));
                let picked = crate::saved_banner::pick_item(
                    session.world.visible_block_entities(&chunk).unwrap(),
                    chunk,
                    position,
                    "minecraft:red_banner".into(),
                )
                .unwrap();
                for key in [
                    "minecraft:banner_patterns",
                    "minecraft:custom_name",
                    "minecraft:custom_data",
                ] {
                    assert_eq!(picked.components().get(key), components.get(key));
                }
                let entity = session.placed_banners[&(position.x, position.y, position.z)].clone();
                assert_eq!(entity.get("patterns"), Some(&patterns));
                assert_eq!(entity.get("CustomName"), Some(&Tag::String("Named".into())));
                assert_eq!(
                    entity
                        .get("components")
                        .unwrap()
                        .get("minecraft:custom_data"),
                    components.get("minecraft:custom_data")
                );
                let mut draft = session.draft_changed_chunk(chunk, &source).unwrap();
                session
                    .stage_banner_lifecycle(chunk, &source, &mut draft)
                    .unwrap();
                struct BannerTags;
                impl native_resources::packs::ResourceProvider for BannerTags {
                    fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                        Ok(None)
                    }
                    fn read_data_stack(&mut self, _: &str) -> anyhow::Result<Vec<Vec<u8>>> {
                        Ok(vec![br#"{"values":["minecraft:stone"]}"#.to_vec()])
                    }
                }
                let tags = HeightmapTags::load(
                    &mut BannerTags,
                    &BTreeSet::from([
                        "minecraft:air".into(),
                        "minecraft:stone".into(),
                        "minecraft:red_wall_banner".into(),
                    ]),
                )
                .unwrap();
                let combined = session
                    .draft_dirty_chunk_with_heightmaps_and_simulated_ticks(
                        chunk,
                        &source,
                        &tags,
                        |state| Ok((state.name.matches("minecraft:air"), false)),
                    )
                    .unwrap();
                assert_eq!(
                    combined.document().value.get("block_entities"),
                    draft.document().value.get("block_entities")
                );
                assert!(
                    matches!(draft.document().value.get("block_entities"),Some(Tag::List { values, .. }) if values==&vec![entity.clone()])
                );
                assert_eq!(nbt::write(&source).unwrap(), source_bytes);
                let support = IVec3::new(8, 2, 6);
                assert!(!session.set(support, session.states[0]));
                let mut stale = source.clone();
                let Tag::Compound(fields) = &mut stale.value else {
                    panic!()
                };
                fields.push((
                    "block_entities".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![entity.clone()],
                    },
                ));
                let mut stale_draft = session.draft_changed_chunk(chunk, &stale).unwrap();
                let before = stale_draft.document().clone();
                assert!(
                    session
                        .stage_banner_lifecycle(chunk, &stale, &mut stale_draft)
                        .is_err()
                );
                assert_eq!(stale_draft.document(), &before);
                session.queue_chunk_window(
                    ChunkPos {
                        x: chunk.x + 3,
                        z: chunk.z,
                    },
                    0,
                );
                session.apply_streaming();
                assert!(session.parked_chunks.contains_key(&chunk));
                session.queue_chunk_window(chunk, 0);
                session.apply_streaming();
                let picked = crate::saved_banner::pick_item(
                    session.world.visible_block_entities(&chunk).unwrap(),
                    chunk,
                    position,
                    "minecraft:red_banner".into(),
                )
                .unwrap();
                assert_eq!(
                    picked.components().get("minecraft:banner_patterns"),
                    Some(&patterns)
                );
            }
        }
    }

    #[test]
    fn banner_placement_on_floor_uses_rotation_and_rejects_unavailable_entities() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::Tag;
        use native_world::loaded::SavedBlockEntities;
        let mut session = session();
        let chunk = session.player_chunk().unwrap();
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new(
                "minecraft:white_banner".into(),
                1,
                16,
                Tag::Compound(vec![]),
            ),
        );
        session.set_player_inventory(inventory);
        let hit = ShapeRayHit {
            position: IVec3::new(4, 0, 4),
            face: IVec3::Y,
            location: DVec3::new(4.5, 1.0, 4.5),
            inside: false,
        };
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(chunk, SavedBlockEntities::Unavailable);
        assert!(session.place_banner(hit).is_none());
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(chunk, SavedBlockEntities::Empty);
        session.player.yaw = 45.0_f32.to_radians();
        assert_eq!(session.place_banner(hit), Some(PlayerSlot::Storage(0)));
        let absolute = session.origin + IVec3::new(4, 1, 4);
        let block = session
            .world
            .block(absolute.x, absolute.y, absolute.z)
            .unwrap();
        assert_eq!(block.name, "minecraft:white_banner");
        assert_eq!(block.properties["rotation"], "2");
        assert!(!session.set(IVec3::new(4, 0, 4), session.states[0]));
    }

    #[test]
    fn breaking_placed_banner_copies_selected_components_and_keeps_source() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::{Tag, TagType};
        use native_resources::{loot::BlockLootTables, packs::ResourceProvider};
        use native_world::loaded::SavedBlockEntities;
        struct Loot;
        impl ResourceProvider for Loot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok((path=="data/minecraft/loot_table/blocks/red_banner.json").then(||br#"{"type":"minecraft:block","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:red_banner","modifier":{"type":"minecraft:copy_components","source":"block_entity","include":["minecraft:banner_patterns","minecraft:custom_name"]}}]}]}"#.to_vec()))
            }
        }
        struct UnsupportedLoot;
        impl ResourceProvider for UnsupportedLoot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok((path=="data/minecraft/loot_table/blocks/red_banner.json").then(||br#"{"type":"minecraft:block","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:stone","modifier":{"type":"minecraft:copy_components","source":"block_entity","include":["minecraft:banner_patterns"]}}]}]}"#.to_vec()))
            }
        }
        let mut session = session();
        let chunk = session.player_chunk().unwrap();
        Arc::make_mut(&mut session.world)
            .saved_block_entities
            .insert(chunk, SavedBlockEntities::Empty);
        let patterns = Tag::List {
            element_type: TagType::Compound,
            values: vec![Tag::Compound(vec![
                ("pattern".into(), Tag::String("minecraft:cross".into())),
                ("color".into(), Tag::String("blue".into())),
            ])],
        };
        let name = Tag::String("Named".into());
        let components = Tag::Compound(vec![
            ("minecraft:banner_patterns".into(), patterns.clone()),
            ("minecraft:custom_name".into(), name.clone()),
            (
                "minecraft:custom_data".into(),
                Tag::Compound(vec![("future".into(), Tag::Int(42))]),
            ),
        ]);
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new("minecraft:red_banner".into(), 1, 16, components),
        );
        session.set_player_inventory(inventory);
        session.submit_command(PlayerCommand::Place);
        session.update(TICK);
        let position = session.origin + IVec3::new(8, 2, 7);
        let key = (position.x, position.y, position.z);
        assert!(session.placed_banners.contains_key(&key));
        session.finish_breaking(position);
        assert!(
            session.placed_banners.contains_key(&key),
            "unsupported loot must not erase the banner"
        );
        session.set_block_loot(Arc::new(
            BlockLootTables::load(&mut UnsupportedLoot).unwrap(),
        ));
        session.finish_breaking(position);
        assert!(
            session.placed_banners.contains_key(&key),
            "unsupported destination components must not erase the banner"
        );
        assert!(session.dropped_items.snapshot().is_empty());
        session.set_block_loot(Arc::new(BlockLootTables::load(&mut Loot).unwrap()));
        session.submit_command(PlayerCommand::Break);
        for _ in 0..200 {
            session.update(TICK);
            if !session.placed_banners.contains_key(&key) {
                break;
            }
        }
        assert_eq!(
            session
                .world
                .block(position.x, position.y, position.z)
                .unwrap()
                .name,
            "minecraft:air"
        );
        assert!(!session.placed_banners.contains_key(&key));
        assert!(!session.removed_banners.contains_key(&key));
        assert!(matches!(
            session.world.saved_block_entities[&chunk],
            SavedBlockEntities::Empty
        ));
        assert!(matches!(
            session.world.visible_block_entities(&chunk),
            Some(SavedBlockEntities::Empty)
        ));
        let drops = session.dropped_items.snapshot();
        assert_eq!(drops.len(), 1);
        let item = &drops[0].stack;
        assert_eq!(item.id(), "minecraft:red_banner");
        assert_eq!(
            item.components().get("minecraft:banner_patterns"),
            Some(&patterns)
        );
        assert_eq!(item.components().get("minecraft:custom_name"), Some(&name));
        assert!(item.components().get("minecraft:custom_data").is_none());
    }

    #[test]
    fn breaking_saved_banner_stages_exact_entity_removal_and_rejects_stale_source() {
        use native_persistence::{
            edit::{BlockChange, draft_chunk_blocks},
            nbt::{self, NamedTag, Tag, TagType},
            palette::BlockState as SavedState,
        };
        use native_world::loaded::SavedBlockEntities;
        let (mut world, origin, player) = fixture();
        let position = origin + IVec3::new(8, 2, 6);
        let chunk = ChunkPos {
            x: position.x.div_euclid(16),
            z: position.z.div_euclid(16),
        };
        let block = state("minecraft:white_banner", &[("rotation", "0")]);
        let id = world.intern_state(block);
        world
            .set_block_id(position.x, position.y, position.z, id)
            .unwrap();
        let entity = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:banner".into())),
            ("x".into(), Tag::Int(position.x)),
            ("y".into(), Tag::Int(position.y)),
            ("z".into(), Tag::Int(position.z)),
            ("unknown".into(), Tag::Int(42)),
        ]);
        let list = Tag::List {
            element_type: TagType::Compound,
            values: vec![entity.clone()],
        };
        let bytes = nbt::write(&NamedTag {
            name: "".into(),
            value: list.clone(),
        })
        .unwrap();
        world
            .saved_block_entities
            .insert(chunk, SavedBlockEntities::Encoded(bytes.clone().into()));
        let mut source = draft_chunk_blocks(
            &fixture_chunk_document(chunk),
            native_persistence::world::ChunkPos {
                x: chunk.x,
                z: chunk.z,
            },
            &[BlockChange {
                x: position.x,
                y: position.y,
                z: position.z,
                expected: SavedState {
                    name: "minecraft:stone".into(),
                    properties: Vec::new(),
                },
                replacement: SavedState {
                    name: "minecraft:white_banner".into(),
                    properties: [("rotation".into(), "0".into())].into(),
                },
            }],
        )
        .unwrap()
        .document()
        .clone();
        let Tag::Compound(fields) = &mut source.value else {
            panic!()
        };
        fields.push(("block_entities".into(), list));
        let original = nbt::write(&source).unwrap();
        let mut session = LoadedSession::new(
            world,
            origin,
            BuildBounds {
                min_y: 0,
                max_y: 32,
            },
            player,
        )
        .unwrap();
        session.set_game_mode(GameMode::Creative);
        let before = session.snapshot();
        session.finish_breaking(position);
        assert_eq!(
            session
                .world
                .block(position.x, position.y, position.z)
                .unwrap()
                .name,
            "minecraft:air"
        );
        assert!(matches!(
            session.world.visible_block_entities(&chunk),
            Some(SavedBlockEntities::Empty)
        ));
        assert_eq!(
            session.removed_banners[&(position.x, position.y, position.z)],
            entity
        );
        assert!(matches!(
            before
                .world
                .loaded()
                .unwrap()
                .visible_block_entities(&chunk),
            Some(SavedBlockEntities::Encoded(_))
        ));
        let mut draft = session.draft_changed_chunk(chunk, &source).unwrap();
        session
            .stage_banner_lifecycle(chunk, &source, &mut draft)
            .unwrap();
        assert!(
            matches!(draft.document().value.get("block_entities"),Some(Tag::List{values,..}) if values.is_empty())
        );
        assert_eq!(nbt::write(&source).unwrap(), original);
        let mut stale = source.clone();
        let Tag::Compound(fields) = &mut stale.value else {
            panic!()
        };
        let Tag::List { values, .. } = &mut fields
            .iter_mut()
            .find(|(name, _)| name.matches("block_entities"))
            .unwrap()
            .1
        else {
            panic!()
        };
        let Tag::Compound(fields) = &mut values[0] else {
            panic!()
        };
        fields.push(("changed".into(), Tag::Byte(1)));
        let mut stale_draft = session.draft_changed_chunk(chunk, &stale).unwrap();
        let unchanged = stale_draft.document().clone();
        assert!(
            session
                .stage_banner_lifecycle(chunk, &stale, &mut stale_draft)
                .is_err()
        );
        assert_eq!(stale_draft.document(), &unchanged);
    }

    #[test]
    #[cfg(target_os = "windows")]
    #[ignore = "requires Minecraft 26.3 and Java 25 JDK"]
    fn banner_support_updates_match_java() {
        use std::{path::PathBuf, process::Command};
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let version = game.join("versions/26.3");
        let metadata: serde_json::Value =
            serde_json::from_slice(&std::fs::read(version.join("26.3.json")).unwrap()).unwrap();
        let temp = tempfile::tempdir().unwrap();
        let mut paths = vec![version.join("26.3.jar"), temp.path().to_path_buf()];
        for entry in metadata["libraries"].as_array().unwrap() {
            if let Some(path) = entry["downloads"]["artifact"]["path"].as_str() {
                let path = game.join("libraries").join(path);
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
        let cp = std::env::join_paths(paths).unwrap();
        let java=std::env::var_os("MINECRAFT_JAVA_HOME").or_else(||std::env::var_os("JAVA_HOME")).map(PathBuf::from).unwrap_or_else(||PathBuf::from(std::env::var_os("USERPROFILE").unwrap()).join("AppData/Local/Packages/Microsoft.4297127D64EC6_8wekyb3d8bbwe/LocalCache/Local/runtime/java-runtime-epsilon/windows-x64/java-runtime-epsilon")).join("bin");
        let source = temp.path().join("BannerSupportOracle.java");
        let output = temp.path().join("banner-support.json");
        std::fs::write(
            &source,
            include_str!("../tests/java/BannerSupportOracle.java"),
        )
        .unwrap();
        for command in [
            Command::new(java.join("javac.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg(&source),
            Command::new(java.join("java.exe"))
                .arg("-cp")
                .arg(&cp)
                .arg("BannerSupportOracle")
                .arg(&output),
        ] {
            let result = command.output().unwrap();
            assert!(
                result.status.success(),
                "{}\n{}",
                String::from_utf8_lossy(&result.stdout),
                String::from_utf8_lossy(&result.stderr)
            );
        }
        let result: serde_json::Value =
            serde_json::from_slice(&std::fs::read(output).unwrap()).unwrap();
        assert_eq!(
            result["order"],
            serde_json::json!(["west", "east", "north", "south", "down", "up"])
        );
        for row in result["rows"].as_array().unwrap() {
            let face = row["face"].as_str().unwrap();
            let block = if face == "standing" {
                state("minecraft:white_banner", &[("rotation", "0")])
            } else {
                state("minecraft:white_wall_banner", &[("facing", face)])
            };
            let changed = match row["changed"].as_str().unwrap() {
                "down" => IVec3::NEG_Y,
                "up" => IVec3::Y,
                "north" => IVec3::NEG_Z,
                "south" => IVec3::Z,
                "west" => IVec3::NEG_X,
                "east" => IVec3::X,
                _ => unreachable!(),
            };
            assert_eq!(
                banner_support_direction(&block) == Some(changed)
                    && !row["solid"].as_bool().unwrap(),
                row["removed"].as_bool().unwrap(),
                "{row}"
            );
        }
    }

    #[test]
    fn support_removal_drops_all_banners_in_shape_order_and_preserves_sources() {
        use native_persistence::nbt::{self, NamedTag, Tag, TagType};
        use native_resources::{loot::BlockLootTables, packs::ResourceProvider};
        use native_world::loaded::SavedBlockEntities;
        struct Loot;
        impl ResourceProvider for Loot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok((path=="data/minecraft/loot_table/blocks/white_banner.json").then(||br#"{"type":"minecraft:block","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:white_banner","modifier":{"type":"minecraft:copy_components","source":"block_entity","include":["minecraft:banner_patterns","minecraft:custom_name"]}}]},{"condition":{"type":"minecraft:entity_properties","entity":"this","predicate":{}},"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:diamond"}]}]}"#.to_vec()))
            }
        }
        for enabled in [false, true] {
            for mode in [GameMode::Survival, GameMode::Creative] {
                let (mut world, origin, player) = fixture();
                let support = IVec3::new(4, 3, 4);
                let absolute = origin + support;
                let chunk = ChunkPos {
                    x: absolute.x.div_euclid(16),
                    z: absolute.z.div_euclid(16),
                };
                let stone = world.intern_state(state("minecraft:stone", &[]));
                world
                    .set_block_id(absolute.x, absolute.y, absolute.z, stone)
                    .unwrap();
                let entries = [
                    (IVec3::NEG_X, "west"),
                    (IVec3::X, "east"),
                    (IVec3::NEG_Z, "north"),
                    (IVec3::Z, "south"),
                    (IVec3::Y, "up"),
                ];
                let mut entities = Vec::new();
                for (offset, label) in entries {
                    let block = if offset == IVec3::Y {
                        state("minecraft:white_banner", &[("rotation", "0")])
                    } else {
                        state("minecraft:white_wall_banner", &[("facing", label)])
                    };
                    let id = world.intern_state(block);
                    let p = absolute + offset;
                    world.set_block_id(p.x, p.y, p.z, id).unwrap();
                    entities.push(Tag::Compound(vec![
                        ("id".into(), Tag::String("minecraft:banner".into())),
                        ("x".into(), Tag::Int(p.x)),
                        ("y".into(), Tag::Int(p.y)),
                        ("z".into(), Tag::Int(p.z)),
                        ("CustomName".into(), Tag::String(label.into())),
                        (
                            "patterns".into(),
                            Tag::List {
                                element_type: TagType::Compound,
                                values: vec![Tag::Compound(vec![
                                    ("pattern".into(), Tag::String("minecraft:cross".into())),
                                    ("color".into(), Tag::String("red".into())),
                                ])],
                            },
                        ),
                        ("future".into(), Tag::Int(42)),
                    ]));
                }
                let original = nbt::write(&NamedTag {
                    name: "".into(),
                    value: Tag::List {
                        element_type: TagType::Compound,
                        values: entities,
                    },
                })
                .unwrap();
                world
                    .saved_block_entities
                    .insert(chunk, SavedBlockEntities::Encoded(original.clone().into()));
                use native_persistence::{
                    edit::{BlockChange, draft_chunk_blocks},
                    palette::BlockState as SavedState,
                };
                let mut changes = Vec::new();
                for offset in
                    std::iter::once(IVec3::ZERO).chain(entries.iter().map(|(offset, _)| *offset))
                {
                    let p = absolute + offset;
                    let state = world.block(p.x, p.y, p.z).unwrap();
                    changes.push(BlockChange {
                        x: p.x,
                        y: p.y,
                        z: p.z,
                        expected: SavedState {
                            name: "minecraft:air".into(),
                            properties: Vec::new(),
                        },
                        replacement: SavedState {
                            name: state.name.as_str().into(),
                            properties: state
                                .properties
                                .iter()
                                .map(|(key, value)| (key.as_str().into(), value.as_str().into()))
                                .collect(),
                        },
                    });
                }
                let mut source_document = draft_chunk_blocks(
                    &fixture_chunk_document(chunk),
                    native_persistence::world::ChunkPos {
                        x: chunk.x,
                        z: chunk.z,
                    },
                    &changes,
                )
                .unwrap()
                .document()
                .clone();
                let Tag::Compound(fields) = &mut source_document.value else {
                    panic!()
                };
                fields.push(("block_entities".into(), nbt::read(&original).unwrap().value));
                let mut session = LoadedSession::new(
                    world,
                    origin,
                    BuildBounds {
                        min_y: 0,
                        max_y: 32,
                    },
                    player,
                )
                .unwrap();
                session.set_game_mode(mode);
                session.set_block_drops(enabled);
                let before = session.snapshot();
                let unknown = session.intern_block(state(
                    "minecraft:unregistered_slab",
                    &[("type", "bottom"), ("waterlogged", "false")],
                ));
                assert!(!session.set(support, unknown));
                assert!(!session.set(support, session.states[0]));
                assert!(session.dropped_items.snapshot().is_empty());
                session.set_block_loot(Arc::new(BlockLootTables::load(&mut Loot).unwrap()));
                let dirt = session.intern_block(state("minecraft:dirt", &[]));
                assert!(session.set(support, dirt));
                assert!(session.removed_banners.is_empty());
                assert!(session.set(support, session.states[0]));
                assert_eq!(session.removed_banners.len(), 5);
                for (offset, _) in entries {
                    let p = absolute + offset;
                    assert_eq!(
                        session.world.block(p.x, p.y, p.z).unwrap().name,
                        "minecraft:air"
                    );
                    assert_eq!(
                        session.removed_banners[&(p.x, p.y, p.z)].get("future"),
                        Some(&Tag::Int(42))
                    );
                }
                assert!(matches!(
                    session.world.visible_block_entities(&chunk),
                    Some(SavedBlockEntities::Empty)
                ));
                let SavedBlockEntities::Encoded(source) =
                    &session.world.saved_block_entities[&chunk]
                else {
                    panic!()
                };
                assert_eq!(&**source, original);
                let mut draft = session
                    .draft_changed_chunk(chunk, &source_document)
                    .unwrap();
                session
                    .stage_banner_lifecycle(chunk, &source_document, &mut draft)
                    .unwrap();
                assert!(
                    matches!(draft.document().value.get("block_entities"),Some(Tag::List{values,..}) if values.is_empty())
                );
                let mut stale = source_document.clone();
                let Tag::Compound(fields) = &mut stale.value else {
                    panic!()
                };
                let Tag::List { values, .. } = &mut fields
                    .iter_mut()
                    .find(|(key, _)| key.matches("block_entities"))
                    .unwrap()
                    .1
                else {
                    panic!()
                };
                let Tag::Compound(fields) = &mut values[2] else {
                    panic!()
                };
                fields.push(("changed".into(), Tag::Byte(1)));
                let mut stale_draft = session.draft_changed_chunk(chunk, &stale).unwrap();
                let unchanged = stale_draft.document().clone();
                assert!(
                    session
                        .stage_banner_lifecycle(chunk, &stale, &mut stale_draft)
                        .is_err()
                );
                assert_eq!(stale_draft.document(), &unchanged);
                assert!(matches!(
                    before
                        .world
                        .loaded()
                        .unwrap()
                        .visible_block_entities(&chunk),
                    Some(SavedBlockEntities::Encoded(_))
                ));
                let drops = session.dropped_items.snapshot();
                assert_eq!(drops.len(), if enabled { 5 } else { 0 });
                if enabled {
                    for (drop, (_, label)) in drops.iter().zip(entries) {
                        assert_eq!(drop.stack.id(), "minecraft:white_banner");
                        assert_eq!(
                            drop.stack.components().get("minecraft:custom_name"),
                            Some(&Tag::String(label.into()))
                        );
                        assert!(
                            drop.stack
                                .components()
                                .get("minecraft:banner_patterns")
                                .is_some()
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn banner_support_waits_for_named_sequence_even_when_drops_are_disabled() {
        use native_resources::{loot::BlockLootTables, packs::ResourceProvider};
        use native_world::loaded::SavedBlockEntities;
        struct Loot;
        impl ResourceProvider for Loot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(path.ends_with("/white_banner.json").then(|| br#"{"type":"minecraft:block","random_sequence":"example:banner","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:white_banner","condition":{"type":"minecraft:random_chance","chance":1.0}}]}]}"#.to_vec()))
            }
        }
        let (mut world, origin, player) = fixture();
        let support = origin + IVec3::new(4, 3, 4);
        let banner = support + IVec3::X;
        let chunk = ChunkPos {
            x: support.x.div_euclid(16),
            z: support.z.div_euclid(16),
        };
        let stone = world.intern_state(state("minecraft:stone", &[]));
        let id = world.intern_state(state("minecraft:white_wall_banner", &[("facing", "east")]));
        world
            .set_block_id(support.x, support.y, support.z, stone)
            .unwrap();
        world
            .set_block_id(banner.x, banner.y, banner.z, id)
            .unwrap();
        world
            .saved_block_entities
            .insert(chunk, SavedBlockEntities::Empty);
        let mut session = LoadedSession::new(
            world,
            origin,
            BuildBounds {
                min_y: 0,
                max_y: 32,
            },
            player,
        )
        .unwrap();
        session.set_block_drops(false);
        session.set_block_loot(Arc::new(BlockLootTables::load(&mut Loot).unwrap()));
        session.level_random = native_core::random::LegacyRandom::new(9182);
        assert!(!session.set(support - origin, session.states[0]));
        let mut expected = native_core::random::LegacyRandom::new(9182);
        assert_eq!(
            session.level_random.clone().next_double(),
            expected.clone().next_double()
        );
        assert_eq!(
            session
                .world
                .block(support.x, support.y, support.z)
                .unwrap()
                .name,
            "minecraft:stone"
        );
        assert_eq!(
            session
                .world
                .block(banner.x, banner.y, banner.z)
                .unwrap()
                .name,
            "minecraft:white_wall_banner"
        );
        session
            .set_random_sequences(
                42,
                native_persistence::random_sequences::RandomSequences::read(None).unwrap(),
            )
            .unwrap();
        assert!(session.set(support - origin, session.states[0]));
        assert_eq!(
            session
                .world
                .block(banner.x, banner.y, banner.z)
                .unwrap()
                .name,
            "minecraft:air"
        );
        assert!(session.dropped_items.snapshot().is_empty());
        assert!(session.random_sequences.as_ref().unwrap().data.is_dirty());
        for _ in 0..3 {
            expected.next_double();
        }
        assert_eq!(session.level_random.next_double(), expected.next_double());
    }

    #[cfg(target_os = "windows")]
    #[test]
    #[ignore = "requires Minecraft 26.3 and Java 25 JDK"]
    fn banner_removal_named_sequence_and_components_match_java() {
        use native_persistence::nbt::{self, NamedTag, Tag, TagType};
        use native_resources::{loot::BlockLootTables, packs::ResourceProvider};
        use native_world::loaded::SavedBlockEntities;
        use std::{path::PathBuf, process::Command};
        const TABLE: &[u8] = br#"{"type":"minecraft:block","random_sequence":"example:banner","pools":[{"rolls":1,"entries":[{"type":"minecraft:item","name":"minecraft:white_banner","condition":{"type":"minecraft:random_chance","chance":0.5},"modifier":{"type":"minecraft:copy_components","source":"block_entity","include":["minecraft:custom_name"]}}]}]}"#;
        struct Loot;
        impl ResourceProvider for Loot {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(path.ends_with("/white_banner.json").then(|| TABLE.to_vec()))
            }
        }
        let game = std::env::var_os("MINECRAFT_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| native_resources::default_minecraft_dir().unwrap());
        let version = game.join("versions/26.3");
        let metadata: serde_json::Value =
            serde_json::from_slice(&std::fs::read(version.join("26.3.json")).unwrap()).unwrap();
        let temp = tempfile::tempdir().unwrap();
        let mut paths = vec![version.join("26.3.jar"), temp.path().to_path_buf()];
        for library in metadata["libraries"].as_array().unwrap() {
            if let Some(path) = library["downloads"]["artifact"]["path"].as_str() {
                let path = game.join("libraries").join(path);
                if path.is_file() {
                    paths.push(path);
                }
            }
        }
        let cp = std::env::join_paths(paths).unwrap();
        let java = std::env::var_os("MINECRAFT_JAVA_HOME").or_else(|| std::env::var_os("JAVA_HOME")).map(PathBuf::from).unwrap_or_else(|| PathBuf::from(std::env::var_os("USERPROFILE").unwrap()).join("AppData/Local/Packages/Microsoft.4297127D64EC6_8wekyb3d8bbwe/LocalCache/Local/runtime/java-runtime-epsilon/windows-x64/java-runtime-epsilon")).join("bin");
        let source = temp.path().join("BannerRandomOracle.java");
        let input = temp.path().join("table.json");
        let output = temp.path().join("output.json");
        std::fs::write(
            &source,
            include_str!("../tests/java/BannerRandomOracle.java"),
        )
        .unwrap();
        std::fs::write(&input, TABLE).unwrap();
        let compile = Command::new(java.join("javac.exe"))
            .arg("-cp")
            .arg(&cp)
            .arg(&source)
            .output()
            .unwrap();
        assert!(
            compile.status.success(),
            "{}",
            String::from_utf8_lossy(&compile.stderr)
        );
        let result = Command::new(java.join("java.exe"))
            .arg("-cp")
            .arg(&cp)
            .arg("BannerRandomOracle")
            .arg(&input)
            .arg(&output)
            .output()
            .unwrap();
        assert!(
            result.status.success(),
            "{}\n{}",
            String::from_utf8_lossy(&result.stdout),
            String::from_utf8_lossy(&result.stderr)
        );
        let rows: Vec<serde_json::Value> =
            serde_json::from_slice(&std::fs::read(output).unwrap()).unwrap();
        assert_eq!(rows.len(), 20);
        let loot = Arc::new(BlockLootTables::load(&mut Loot).unwrap());
        let entries = [
            (IVec3::NEG_X, "west"),
            (IVec3::X, "east"),
            (IVec3::NEG_Z, "north"),
            (IVec3::Z, "south"),
            (IVec3::Y, "up"),
        ];
        for group in rows.chunks_exact(5) {
            let seed = group[0]["seed"].as_i64().unwrap();
            for mode in [GameMode::Survival, GameMode::Creative] {
                for enabled in [false, true] {
                    for player in [false, true] {
                        let (mut world, origin, original_player) = fixture();
                        let support = origin + IVec3::new(4, 3, 4);
                        let chunk = ChunkPos {
                            x: support.x.div_euclid(16),
                            z: support.z.div_euclid(16),
                        };
                        let stone = world.intern_state(state("minecraft:stone", &[]));
                        world
                            .set_block_id(support.x, support.y, support.z, stone)
                            .unwrap();
                        let mut entities = Vec::new();
                        for (offset, label) in entries {
                            let banner = if offset == IVec3::Y {
                                state("minecraft:white_banner", &[("rotation", "0")])
                            } else {
                                state("minecraft:white_wall_banner", &[("facing", label)])
                            };
                            let id = world.intern_state(banner);
                            let p = support + offset;
                            world.set_block_id(p.x, p.y, p.z, id).unwrap();
                            entities.push(Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:banner".into())),
                                ("x".into(), Tag::Int(p.x)),
                                ("y".into(), Tag::Int(p.y)),
                                ("z".into(), Tag::Int(p.z)),
                                ("CustomName".into(), Tag::String(label.into())),
                            ]));
                        }
                        let bytes = nbt::write(&NamedTag {
                            name: "".into(),
                            value: Tag::List {
                                element_type: TagType::Compound,
                                values: entities,
                            },
                        })
                        .unwrap();
                        world
                            .saved_block_entities
                            .insert(chunk, SavedBlockEntities::Encoded(bytes.into()));
                        let mut session = LoadedSession::new(
                            world,
                            origin,
                            BuildBounds {
                                min_y: 0,
                                max_y: 32,
                            },
                            original_player,
                        )
                        .unwrap();
                        session.set_game_mode(mode);
                        session.set_block_drops(enabled);
                        session.set_block_loot(Arc::clone(&loot));
                        session.level_random = native_core::random::LegacyRandom::new(9182);
                        session
                            .set_random_sequences(
                                seed,
                                native_persistence::random_sequences::RandomSequences::read(None)
                                    .unwrap(),
                            )
                            .unwrap();
                        if player {
                            for ((offset, _), row) in entries.into_iter().zip(group) {
                                session.finish_breaking(support + offset);
                                let expected = if mode == GameMode::Creative {
                                    native_core::random::LegacyRandom::new(9182).next_double()
                                } else {
                                    row["levelNext"].as_f64().unwrap()
                                };
                                assert_eq!(
                                    session.level_random.clone().next_double().to_bits(),
                                    expected.to_bits(),
                                    "{seed} {mode:?} drops={enabled} player={player}"
                                );
                            }
                        } else {
                            assert!(session.set(support - origin, session.states[0]));
                            assert_eq!(
                                session.level_random.clone().next_double().to_bits(),
                                group[4]["levelNext"].as_f64().unwrap().to_bits(),
                                "{seed} {mode:?} drops={enabled} player={player}"
                            );
                        }
                        assert_eq!(
                            session.removed_banners.len(),
                            5,
                            "{seed} {mode:?} drops={enabled} player={player}"
                        );
                        let expected: Vec<_> = if enabled && (!player || mode == GameMode::Survival)
                        {
                            group
                                .iter()
                                .filter(|row| row["drop"].as_bool().unwrap())
                                .map(|row| row["name"].as_str().unwrap().to_owned())
                                .collect()
                        } else {
                            Vec::new()
                        };
                        let actual: Vec<_> = session
                            .dropped_items
                            .snapshot()
                            .iter()
                            .map(|item| {
                                let Some(Tag::String(name)) =
                                    item.stack.components().get("minecraft:custom_name")
                                else {
                                    panic!("missing custom name")
                                };
                                String::from_utf16(&name.0).unwrap()
                            })
                            .collect();
                        assert_eq!(
                            actual, expected,
                            "{seed} {mode:?} drops={enabled} player={player}"
                        );
                        let sequences = &session.random_sequences.as_ref().unwrap().data;
                        if player && mode == GameMode::Creative {
                            assert!(!sequences.is_dirty());
                        } else {
                            let mut random = sequences.get("example:banner", seed).unwrap();
                            assert_eq!(
                                random.next_long(),
                                group[4]["next"].as_i64().unwrap(),
                                "{seed} {mode:?} drops={enabled} player={player}"
                            );
                        }
                    }
                }
            }
        }
    }

