    #[test]
    fn item_path_cache_matches_uncached_proof_and_resets_for_changed_world() {
        let mut session = session();
        let bounds = BoundingBox {
            min: DVec3::new(3.0, 3.0, 3.0),
            max: DVec3::new(3.25, 3.25, 3.25),
        };
        {
            let mut proof =
                CreatedItemPathProof::new(&session.world, session.origin, session.bounds);
            for x in -3..=17 {
                for y in [0.0, 3.0, 20.0] {
                    for z in -3..=17 {
                        let offset = DVec3::new(f64::from(x), y, f64::from(z));
                        let b = BoundingBox {
                            min: bounds.min + offset,
                            max: bounds.max + offset,
                        };
                        for actual in [
                            DVec3::ZERO,
                            DVec3::new(0.2, -0.3, 0.1),
                            DVec3::splat(f64::NAN),
                        ] {
                            assert_eq!(
                                proof.safe(b, actual),
                                created_item_path_safe(
                                    &session.world,
                                    session.origin,
                                    session.bounds,
                                    b,
                                    actual
                                )
                            );
                            assert_eq!(
                                proof.safe(b, actual),
                                created_item_path_safe(
                                    &session.world,
                                    session.origin,
                                    session.bounds,
                                    b,
                                    actual
                                )
                            );
                        }
                    }
                }
            }
            assert!(proof.safe(bounds, DVec3::ZERO));
        }
        let portal = session.intern_block(state("minecraft:nether_portal", &[("axis", "x")]));
        assert!(session.set(IVec3::new(3, 3, 3), portal));
        let mut proof = CreatedItemPathProof::new(&session.world, session.origin, session.bounds);
        assert!(!proof.safe(bounds, DVec3::ZERO));
    }

    #[test]
    fn falling_path_cache_rechecks_overlap_and_world_changes() {
        let mut session = session();
        let bounds = BoundingBox {
            min: DVec3::new(3.01, 3.0, 3.01),
            max: DVec3::new(3.99, 3.98, 3.99),
        };
        let actual = DVec3::new(0.0, -0.04, 0.0);
        let mut cache = ItemPathRegionCache::default();
        assert!(cache.safe(
            &session.world,
            session.origin,
            session.bounds,
            bounds,
            actual
        ));
        let stone = session.states[3];
        assert!(session.set(IVec3::new(3, 3, 3), stone));
        // The area remains a valid ordinary-block region, but the exact
        // starting box must be checked again even when the region is cached.
        assert!(!cache.safe(
            &session.world,
            session.origin,
            session.bounds,
            bounds,
            actual
        ));
        let portal = session.intern_block(state("minecraft:nether_portal", &[("axis", "x")]));
        assert!(session.set(IVec3::new(3, 3, 3), session.states[0]));
        assert!(session.set(IVec3::new(4, 3, 3), portal));
        cache.clear();
        assert!(!cache.safe(
            &session.world,
            session.origin,
            session.bounds,
            bounds,
            actual
        ));
    }

    #[test]
    #[ignore = "manual synthetic CPU benchmark"]
    fn benchmark_falling_block_path_cache() {
        use std::{hint::black_box, time::Instant};
        let session = session();
        let boxes: Vec<_> = (0..1000)
            .map(|i| {
                let position = DVec3::new(
                    3.5 + f64::from(i % 16) * 0.5,
                    5.0,
                    3.5 + f64::from((i / 16) % 16) * 0.5,
                );
                crate::falling_block::AirborneMotion {
                    position,
                    velocity: DVec3::ZERO,
                    age: 0,
                    no_gravity: false,
                }
                .bounds()
            })
            .collect();
        let movement = DVec3::new(0.0, -0.04, 0.0);
        for cached in [false, true] {
            let mut samples = Vec::new();
            for _ in 0..30 {
                let mut cache = ItemPathRegionCache::default();
                let start = Instant::now();
                for &bounds in &boxes {
                    let valid = if cached {
                        cache.safe(
                            &session.world,
                            session.origin,
                            session.bounds,
                            bounds,
                            movement,
                        )
                    } else {
                        created_item_path_safe(
                            &session.world,
                            session.origin,
                            session.bounds,
                            bounds,
                            movement,
                        )
                    };
                    assert!(black_box(valid));
                }
                samples.push(start.elapsed());
            }
            samples.sort_unstable();
            eprintln!(
                "1000 falling paths (cached={cached}): median {:?}, p95 {:?}",
                samples[15], samples[28]
            );
        }
    }

    #[test]
    #[ignore = "manual synthetic CPU benchmark"]
    fn benchmark_created_item_path_proof() {
        use std::{hint::black_box, time::Instant};
        let session = session();
        let boxes: Vec<_> = (0..1000)
            .map(|i| {
                let p = DVec3::new(
                    2.25 + f64::from(i % 24) * 0.48,
                    3.0,
                    2.25 + f64::from((i / 24) % 24) * 0.48,
                );
                BoundingBox {
                    min: p,
                    max: p + DVec3::splat(0.25),
                }
            })
            .collect();
        for cached in [false, true] {
            let mut samples = Vec::new();
            for _ in 0..20 {
                let mut proof =
                    CreatedItemPathProof::new(&session.world, session.origin, session.bounds);
                let start = Instant::now();
                for &bounds in &boxes {
                    let valid = if cached {
                        proof.safe(bounds, DVec3::ZERO)
                    } else {
                        created_item_path_safe(
                            &session.world,
                            session.origin,
                            session.bounds,
                            bounds,
                            DVec3::ZERO,
                        )
                    };
                    assert!(black_box(valid));
                }
                samples.push(start.elapsed().as_secs_f64() * 1000.0);
            }
            samples.sort_by(f64::total_cmp);
            eprintln!(
                "1000 created item paths (cached={cached}): p50={:.3} ms, p95={:.3} ms",
                samples[10], samples[19]
            );
        }
    }

