    #[test]
    fn picked_up_created_item_is_omitted_from_chunk_draft_and_reports_player_effect() {
        use native_persistence::nbt::Tag;
        let mut session = session();
        session.set_player_inventory(PlayerInventory::default());
        let home = session.player_chunk().unwrap();
        session
            .set_initial_entity_chunk(home, SavedEntityData::Empty)
            .unwrap();
        let position = session.origin.as_dvec3() + DVec3::new(8.5, 1.9, 8.5);
        let stack = ItemStack::new("minecraft:stone".into(), 3, 64, Tag::Compound(vec![])).unwrap();
        session
            .dropped_items
            .spawn_from_entity(position, stack.clone());
        let original = session.draft_created_item_entities(home).unwrap();
        let uuid = crate::saved_item::read(&original[0].document().value)
            .unwrap()
            .unwrap()
            .uuid
            .unwrap();
        for _ in 0..30 {
            session.update(TICK);
            if session.snapshot().dropped_items.is_empty() {
                break;
            }
        }
        assert!(session.snapshot().dropped_items.is_empty());
        assert!(matches!(
            session.take_pickup_sounds().as_slice(),
            [crate::PickupSound::Item(_)]
        ));
        assert!(session.take_pickup_sounds().is_empty());
        let group = BTreeSet::from([home]);
        assert_eq!(
            session.created_item_removal_effects(&group),
            vec![(uuid, crate::items::CreatedRemovalCause::Pickup)]
        );
        assert_eq!(
            session.created_item_pickup_effects(&group),
            vec![crate::items::CreatedItemPickup {
                uuid,
                original_stack: stack,
                transferred: 3,
                discarded: 0,
                pickup_succeeded: true,
            }]
        );
        assert_eq!(
            session
                .inventory
                .slot(crate::inventory::PlayerSlot::Storage(0))
                .unwrap()
                .count(),
            3
        );
        let drafts = session.draft_existing_entity_chunks(&group).unwrap();
        let Some(Tag::List { values, .. }) = drafts[&home].document().value.get("Entities") else {
            panic!("missing entities")
        };
        assert!(values.is_empty());
        let conflict = native_persistence::nbt::NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("Position".into(), Tag::IntArray(vec![home.x, home.z])),
                (
                    "Entities".into(),
                    Tag::List {
                        element_type: native_persistence::nbt::TagType::Compound,
                        values: vec![Tag::Compound(vec![
                            ("id".into(), Tag::String("minecraft:pig".into())),
                            ("UUID".into(), Tag::IntArray(uuid.to_vec())),
                        ])],
                    },
                ),
            ]),
        };
        session.entity_chunks.insert(
            home,
            SavedEntityData::Present(Arc::new(native_persistence::world::SavedEntityChunk {
                position: native_persistence::world::ChunkPos {
                    x: home.x,
                    z: home.z,
                },
                document: Arc::new(conflict),
            })),
        );
        assert!(
            session.draft_existing_entity_chunks(&group).is_err(),
            "a removed created UUID must not match any known saved entity"
        );
    }

    #[test]
    fn loaded_pickup_sounds_keep_tick_order_across_frame_cadences() {
        use native_persistence::nbt::Tag;
        fn prepare() -> LoadedSession {
            let mut session = session();
            session.set_player_inventory(PlayerInventory::default());
            let position =
                session.origin.as_dvec3() + session.motion.position + DVec3::new(0.0, 0.5, 0.0);
            session
                .dropped_items
                .spawn_saved(crate::saved_item::SavedItemState {
                    source: Arc::new(Tag::Compound(vec![])),
                    uuid: None,
                    position,
                    velocity: DVec3::ZERO,
                    on_ground: false,
                    no_gravity: true,
                    age: 0,
                    pickup_delay: 2,
                    health: 5,
                    fire_ticks: 0,
                    invulnerable: false,
                    invulnerable_time: 0,
                    owner: None,
                    thrower: None,
                    stack: ItemStack::new("minecraft:stone".into(), 1, 64, Tag::Compound(vec![]))
                        .unwrap(),
                });
            session
                .experience_orbs
                .spawn_saved(crate::saved_orb::SavedOrb {
                    source: Arc::new(Tag::Compound(vec![])),
                    uuid: None,
                    position,
                    velocity: DVec3::ZERO,
                    on_ground: false,
                    no_gravity: true,
                    age: 0,
                    value: 1,
                    count: 2,
                    health: 5,
                    fire_ticks: 0,
                    invulnerable: false,
                    invulnerable_time: 0,
                });
            session
        }
        let mut batched = prepare();
        let mut frequent = prepare();
        batched.update(TICK * 3);
        let batched_sounds = batched.take_pickup_sounds();
        let mut frequent_sounds = Vec::new();
        for _ in 0..3 {
            frequent.update(TICK);
            frequent_sounds.extend(frequent.take_pickup_sounds());
        }
        assert_eq!(batched_sounds, frequent_sounds);
        assert!(matches!(
            batched_sounds.as_slice(),
            [
                crate::PickupSound::Experience(_),
                crate::PickupSound::Item(_),
                crate::PickupSound::Experience(_)
            ]
        ));
        assert!(batched.take_pickup_sounds().is_empty());
    }

    #[test]
    fn saved_item_merge_is_reflected_in_the_entity_chunk_draft() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let mut session = session();
        let home = session.player_chunk().unwrap();
        let position = session.origin.as_dvec3() + DVec3::new(3.5, 2.0, 3.5);
        let make_item = |uuid: [i32; 4], count: i32| {
            Tag::Compound(vec![
                ("id".into(), Tag::String("minecraft:item".into())),
                ("UUID".into(), Tag::IntArray(uuid.to_vec())),
                (
                    "Pos".into(),
                    Tag::List {
                        element_type: TagType::Double,
                        values: position.to_array().into_iter().map(Tag::Double).collect(),
                    },
                ),
                ("NoGravity".into(), Tag::Byte(1)),
                ("future".into(), Tag::Int(42)),
                (
                    "Item".into(),
                    Tag::Compound(vec![
                        ("id".into(), Tag::String("minecraft:stone".into())),
                        ("count".into(), Tag::Int(count)),
                    ]),
                ),
            ])
        };
        let document = Arc::new(NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("Position".into(), Tag::IntArray(vec![home.x, home.z])),
                (
                    "Entities".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![make_item([1, 2, 3, 4], 1), make_item([5, 6, 7, 8], 2)],
                    },
                ),
            ]),
        });
        session
            .set_initial_entity_chunk(
                home,
                SavedEntityData::Present(Arc::new(native_persistence::world::SavedEntityChunk {
                    position: native_persistence::world::ChunkPos {
                        x: home.x,
                        z: home.z,
                    },
                    document: Arc::clone(&document),
                })),
            )
            .unwrap();
        for _ in 0..40 {
            session.update(TICK);
        }
        assert_eq!(session.snapshot().dropped_items.len(), 1);
        assert_eq!(session.snapshot().dropped_items[0].stack.count(), 3);
        let drafts = session
            .draft_existing_entity_chunks(&BTreeSet::from([home]))
            .unwrap();
        let Some(Tag::List { values, .. }) = drafts[&home].document().value.get("Entities") else {
            panic!()
        };
        assert_eq!(values.len(), 1);
        let saved = crate::saved_item::read(&values[0]).unwrap().unwrap();
        assert_eq!(saved.stack.count(), 3);
        assert_eq!(saved.source.get("future"), Some(&Tag::Int(42)));
        assert!(drafts[&home].matches_source(&document).unwrap());
    }

    #[test]
    fn saved_falling_sand_restores_and_does_not_duplicate_after_chunk_reload() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let mut session = session();
        let home = session.player_chunk().unwrap();
        let remote = ChunkPos {
            x: home.x + 1,
            z: home.z,
        };
        let position = session.origin.as_dvec3() + DVec3::new(3.5, 5.0, 3.5);
        let entity = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:falling_block".into())),
            ("UUID".into(), Tag::IntArray(vec![1, 2, 3, 4])),
            (
                "Pos".into(),
                Tag::List {
                    element_type: TagType::Double,
                    values: position.to_array().into_iter().map(Tag::Double).collect(),
                },
            ),
            (
                "BlockState".into(),
                Tag::String("minecraft:red_sand".into()),
            ),
            ("NoGravity".into(), Tag::Byte(1)),
            ("OnGround".into(), Tag::Byte(1)),
            ("Time".into(), Tag::Int(20)),
            ("DropItem".into(), Tag::Byte(0)),
        ]);
        let item_position = position + DVec3::new(4.0, 0.0, 0.0);
        let item_entity = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:item".into())),
            ("UUID".into(), Tag::IntArray(vec![5, 6, 7, 8])),
            (
                "Pos".into(),
                Tag::List {
                    element_type: TagType::Double,
                    values: item_position
                        .to_array()
                        .into_iter()
                        .map(Tag::Double)
                        .collect(),
                },
            ),
            ("NoGravity".into(), Tag::Byte(1)),
            ("PickupDelay".into(), Tag::Short(i16::MAX)),
            (
                "Item".into(),
                Tag::Compound(vec![
                    ("id".into(), Tag::String("minecraft:stone".into())),
                    ("count".into(), Tag::Int(2)),
                ]),
            ),
        ]);
        let pig = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:pig".into())),
            ("UUID".into(), Tag::IntArray(vec![9, 10, 11, 12])),
            ("unknown".into(), Tag::Long(123)),
        ]);
        let chunk = Arc::new(native_persistence::world::SavedEntityChunk {
            position: native_persistence::world::ChunkPos {
                x: home.x,
                z: home.z,
            },
            document: Arc::new(NamedTag {
                name: "".into(),
                value: Tag::Compound(vec![
                    ("DataVersion".into(), Tag::Int(5023)),
                    ("Position".into(), Tag::IntArray(vec![home.x, home.z])),
                    (
                        "Entities".into(),
                        Tag::List {
                            element_type: TagType::Compound,
                            values: vec![entity.clone(), item_entity, pig.clone()],
                        },
                    ),
                ]),
            }),
        });
        let source_chunk = Arc::clone(&chunk.document);
        session
            .set_initial_entity_chunk(home, SavedEntityData::Present(chunk))
            .unwrap();
        session.dirty_chunks.insert(home);
        session.update(TICK);
        assert_eq!(session.falling_sand.len(), 1);
        assert_eq!(session.falling_sand[0].motion.age, 21);
        assert!(!session.falling_sand[0].drop_item);
        let draft = session
            .draft_saved_falling_entity([1, 2, 3, 4])
            .unwrap()
            .unwrap();
        assert!(
            draft
                .matches_source(&NamedTag {
                    name: "".into(),
                    value: entity.clone()
                })
                .unwrap()
        );
        let saved = crate::saved_falling_block::read(&draft.document().value)
            .unwrap()
            .unwrap();
        assert_eq!(saved.time, 21);
        assert!(!saved.on_ground);
        assert_eq!(saved.position, position);
        let chunk_draft = session.draft_existing_falling_entity_chunk(home).unwrap();
        assert!(chunk_draft.matches_source(&source_chunk).unwrap());
        let Some(Tag::List { values, .. }) = chunk_draft.document().value.get("Entities") else {
            panic!("missing entity list")
        };
        assert_eq!(values[0].get("Time"), Some(&Tag::Int(21)));
        assert_eq!(entity.get("Time"), Some(&Tag::Int(20)));
        let mixed = session.draft_existing_entity_chunk(home).unwrap();
        assert!(mixed.matches_source(&source_chunk).unwrap());
        let Some(Tag::List { values, .. }) = mixed.document().value.get("Entities") else {
            panic!("missing entity list")
        };
        assert_eq!(values[0].get("Time"), Some(&Tag::Int(21)));
        assert_eq!(values[1].get("Age"), Some(&Tag::Short(1)));
        assert_eq!(values[2], pig);

        let remote_document = Arc::new(NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("Position".into(), Tag::IntArray(vec![remote.x, remote.z])),
                (
                    "Entities".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![],
                    },
                ),
            ]),
        });
        session.entity_chunks.insert(
            remote,
            SavedEntityData::Present(Arc::new(native_persistence::world::SavedEntityChunk {
                position: native_persistence::world::ChunkPos {
                    x: remote.x,
                    z: remote.z,
                },
                document: remote_document.clone(),
            })),
        );
        session.falling_sand[0].motion.position.x += 16.0;
        let both = std::collections::BTreeSet::from([home, remote]);
        let drafts = session.draft_existing_entity_chunks(&both).unwrap();
        let tracked = session.draft_tracked_entity_chunks().unwrap();
        assert_eq!(tracked.keys().copied().collect::<BTreeSet<_>>(), both);
        assert_eq!(tracked[&remote].document(), drafts[&remote].document());
        assert!(drafts[&home].matches_source(&source_chunk).unwrap());
        assert!(drafts[&remote].matches_source(&remote_document).unwrap());
        let Some(Tag::List { values, .. }) = drafts[&remote].document().value.get("Entities")
        else {
            panic!()
        };
        assert_eq!(values.len(), 1);
        assert_eq!(
            values[0].get("UUID"),
            Some(&Tag::IntArray(vec![1, 2, 3, 4]))
        );
        assert!(
            session
                .draft_existing_entity_chunks(&std::collections::BTreeSet::from([home]))
                .is_err()
        );
        session.entity_chunks.insert(remote, SavedEntityData::Empty);
        let drafts = session.draft_existing_entity_chunks(&both).unwrap();
        assert!(!drafts[&home].source_was_absent());
        assert!(drafts[&remote].source_was_absent());
        assert!(!drafts[&remote].matches_source(&remote_document).unwrap());
        let Some(Tag::List { values, .. }) = drafts[&remote].document().value.get("Entities")
        else {
            panic!()
        };
        assert_eq!(values.len(), 1);
        assert_eq!(
            values[0].get("UUID"),
            Some(&Tag::IntArray(vec![1, 2, 3, 4]))
        );
        session
            .entity_chunks
            .insert(remote, SavedEntityData::Unavailable);
        assert!(session.draft_existing_entity_chunks(&both).is_err());
        assert!(session.draft_tracked_entity_chunks().is_err());
        session.falling_sand[0].motion.position.x -= 16.0;
        session.entity_chunks.remove(&remote);

        let restored = session.falling_sand.pop().unwrap();
        assert!(session.draft_existing_falling_entity_chunk(home).is_err());
        let mut moved = restored.clone();
        moved.motion.position.x += 16.0;
        session.falling_sand.push(moved);
        assert!(session.draft_existing_falling_entity_chunk(home).is_err());
        session.falling_sand.clear();
        session.falling_sand.push(restored.clone());
        let mut created = restored;
        created.source = None;
        session.falling_sand.push(created);
        assert!(session.draft_existing_falling_entity_chunk(home).is_err());
        assert!(session.draft_tracked_entity_chunks().is_err());
        session.falling_sand.pop();
        assert_eq!(
            session.snapshot().falling_blocks[0].kind,
            FallingKind::RedSand
        );
        session.queue_chunk_window(remote, 0);
        session.update(TICK);
        assert!(session.snapshot().falling_blocks.is_empty());
        session.queue_chunk_window(home, 0);
        session.update(TICK);
        assert_eq!(session.falling_sand.len(), 1);
        assert_eq!(session.snapshot().falling_blocks.len(), 1);
        assert_eq!(session.falling_sand[0].motion.age, 22);
    }

    #[test]
    fn restored_sand_respects_saved_drop_and_cancel_flags_on_landing() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        for (drop_item, cancel) in [(false, false), (true, false), (true, true)] {
            let mut session = session();
            let home = session.player_chunk().unwrap();
            let slab = session.intern_block(state(
                "minecraft:oak_slab",
                &[("type", "bottom"), ("waterlogged", "false")],
            ));
            assert!(session.set(IVec3::new(10, 1, 8), slab));
            let position = session.origin.as_dvec3() + DVec3::new(10.5, 2.0, 8.5);
            let entity = Tag::Compound(vec![
                ("id".into(), Tag::String("minecraft:falling_block".into())),
                ("UUID".into(), Tag::IntArray(vec![1, 2, 3, 4])),
                (
                    "Pos".into(),
                    Tag::List {
                        element_type: TagType::Double,
                        values: position.to_array().into_iter().map(Tag::Double).collect(),
                    },
                ),
                ("BlockState".into(), Tag::String("minecraft:sand".into())),
                ("OnGround".into(), Tag::Byte(1)),
                ("DropItem".into(), Tag::Byte(i8::from(drop_item))),
                ("CancelDrop".into(), Tag::Byte(i8::from(cancel))),
            ]);
            let chunk = Arc::new(native_persistence::world::SavedEntityChunk {
                position: native_persistence::world::ChunkPos {
                    x: home.x,
                    z: home.z,
                },
                document: Arc::new(NamedTag {
                    name: "".into(),
                    value: Tag::Compound(vec![
                        ("DataVersion".into(), Tag::Int(5023)),
                        ("Position".into(), Tag::IntArray(vec![home.x, home.z])),
                        (
                            "Entities".into(),
                            Tag::List {
                                element_type: TagType::Compound,
                                values: vec![entity],
                            },
                        ),
                    ]),
                }),
            });
            session
                .set_initial_entity_chunk(home, SavedEntityData::Present(chunk))
                .unwrap();
            session.activate_saved_falling_sand();
            assert!(!session.uncoordinated_falling_lifecycle);
            for _ in 0..20 {
                session.advance_falling_sand();
            }
            assert!(session.falling_sand.is_empty());
            assert!(!session.uncoordinated_falling_lifecycle);
            assert_eq!(
                session.dropped_items.snapshot().len(),
                usize::from(drop_item && !cancel)
            );
            assert!(
                session.draft_tracked_entity_chunks().is_err(),
                "slab fall effects are not yet verified for saving"
            );
        }
    }

    #[test]
    fn created_falling_path_tracks_bounds_and_never_recovers_after_failure() {
        let start = DVec3::new(15.5, 5.0, 3.5);
        let end = DVec3::new(15.75, 4.9, 3.5);
        let mut created = CreatedFallingSand::new(IVec3::new(15, 5, 3), start);
        created.verify(start, end, true);
        assert!(created.valid);
        assert!(created.visited.contains(&ChunkPos { x: 0, z: 0 }));
        assert!(created.visited.contains(&ChunkPos { x: 1, z: 0 }));
        created.verify(end, end + DVec3::NEG_Y, false);
        assert!(!created.valid);
        created.verify(end, end, true);
        assert!(!created.valid);
    }

    #[test]
    fn created_falling_block_drafts_cover_spawn_and_landing() {
        use native_persistence::{
            edit::{BlockChange, draft_chunk_blocks},
            nbt::Tag,
            palette::{self, BlockState},
        };
        let mut session = session();
        let home = session.player_chunk().unwrap();
        let relative = IVec3::new(3, 5, 3);
        let absolute = session.origin + relative;
        let gravel = session.intern_block(state("minecraft:gravel", &[]));
        let chunk = Arc::make_mut(
            Arc::make_mut(&mut session.world)
                .chunks
                .get_mut(&home)
                .unwrap(),
        );
        let section = Arc::make_mut(chunk.sections.get_mut(&0).unwrap());
        section.blocks.as_mut().unwrap()[3 + 3 * 16 + 5 * 256] = gravel;
        let block = |name: &str| BlockState {
            name: name.into(),
            properties: vec![],
        };
        let source = draft_chunk_blocks(
            &fixture_chunk_document(home),
            native_persistence::world::ChunkPos {
                x: home.x,
                z: home.z,
            },
            &[BlockChange {
                x: absolute.x,
                y: absolute.y,
                z: absolute.z,
                expected: block("minecraft:air"),
                replacement: block("minecraft:gravel"),
            }],
        )
        .unwrap()
        .document()
        .clone();
        session
            .set_initial_entity_chunk(home, SavedEntityData::Empty)
            .unwrap();
        session.enqueue_saved_sand(&[SavedBlockTick {
            block: "minecraft:gravel".into(),
            position: absolute.to_array(),
            delay: 0,
            priority: 0,
        }]);
        session.advance_sand_ticks();
        assert!(session.draft_tracked_entity_chunks().is_err());
        session.advance_falling_sand();
        let uuid = session.falling_sand[0]
            .created
            .as_ref()
            .unwrap()
            .uuid
            .unwrap();
        let entity_drafts = session.draft_tracked_entity_chunks().unwrap();
        let Tag::List { values, .. } = entity_drafts[&home]
            .document()
            .value
            .get("Entities")
            .unwrap()
        else {
            panic!()
        };
        let saved = crate::saved_falling_block::read(&values[0])
            .unwrap()
            .unwrap();
        assert_eq!(saved.uuid, Some(uuid));
        assert_eq!(saved.block.name, "minecraft:gravel");
        assert_eq!(saved.time, 1);
        let original_tracking = session.falling_sand[0].created.clone();
        session.falling_sand[0]
            .created
            .as_mut()
            .unwrap()
            .verified_position
            .x += 1.0;
        assert!(session.draft_tracked_entity_chunks().is_err());
        session.falling_sand[0].created = original_tracking.clone();
        let neighbor = ChunkPos {
            x: home.x + 1,
            z: home.z,
        };
        session.falling_sand[0]
            .created
            .as_mut()
            .unwrap()
            .visited
            .insert(neighbor);
        assert!(
            session
                .draft_existing_entity_chunks(&BTreeSet::from([home]))
                .is_err()
        );
        assert!(session.draft_tracked_entity_chunks().is_err());
        session.falling_sand[0].created = original_tracking;
        let terrain = session.draft_changed_chunk(home, &source).unwrap();
        let section = palette::decode_sections(&terrain.document().value)
            .unwrap()
            .remove(0)
            .blocks
            .unwrap();
        assert_eq!(section.block(3, 5, 3).unwrap().name, "minecraft:air".into());
        session.set_player_uuid(Some(uuid));
        assert!(session.draft_tracked_entity_chunks().is_err());
        session.set_player_uuid(None);
        for _ in 0..40 {
            session.advance_falling_sand();
            if session.falling_sand.is_empty() {
                break;
            }
        }
        assert!(session.falling_sand.is_empty());
        let entity_drafts = session.draft_tracked_entity_chunks().unwrap();
        let Tag::List { values, .. } = entity_drafts[&home]
            .document()
            .value
            .get("Entities")
            .unwrap()
        else {
            panic!()
        };
        assert!(values.is_empty());
        let terrain = session.draft_changed_chunk(home, &source).unwrap();
        let section = palette::decode_sections(&terrain.document().value)
            .unwrap()
            .remove(0)
            .blocks
            .unwrap();
        assert_eq!(section.block(3, 5, 3).unwrap().name, "minecraft:air".into());
        assert_eq!(
            section.block(3, 1, 3).unwrap().name,
            "minecraft:gravel".into()
        );
        assert!(session.draft_existing_entity_chunk(home).is_err());
    }

    #[test]
    fn saved_falling_block_landing_joins_entity_and_terrain_drafts() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        use native_persistence::palette;
        let mut session = session();
        let home = session.player_chunk().unwrap();
        let position = session.origin.as_dvec3() + DVec3::new(3.5, 3.0, 3.5);
        let block = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:falling_block".into())),
            ("UUID".into(), Tag::IntArray(vec![1, 2, 3, 4])),
            (
                "Pos".into(),
                Tag::List {
                    element_type: TagType::Double,
                    values: position.to_array().into_iter().map(Tag::Double).collect(),
                },
            ),
            ("BlockState".into(), Tag::String("minecraft:sand".into())),
            ("Time".into(), Tag::Int(1)),
            ("fall_distance".into(), Tag::Double(4.25)),
            ("DropItem".into(), Tag::Byte(1)),
        ]);
        let pig = Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:pig".into())),
            ("UUID".into(), Tag::IntArray(vec![5, 6, 7, 8])),
        ]);
        let make = |falling: Tag| NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("Position".into(), Tag::IntArray(vec![home.x, home.z])),
                (
                    "Entities".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![falling, pig.clone()],
                    },
                ),
            ]),
        };
        let original = Arc::new(make(block.clone()));
        let make_chunk = |document: Arc<NamedTag>| {
            SavedEntityData::Present(Arc::new(native_persistence::world::SavedEntityChunk {
                position: native_persistence::world::ChunkPos {
                    x: home.x,
                    z: home.z,
                },
                document,
            }))
        };
        session
            .set_initial_entity_chunk(home, make_chunk(Arc::clone(&original)))
            .unwrap();
        session.activate_saved_falling_sand();
        session.advance_falling_sand();
        let saved = session
            .draft_saved_falling_entity([1, 2, 3, 4])
            .unwrap()
            .unwrap();
        let saved = crate::saved_falling_block::read(&saved.document().value)
            .unwrap()
            .unwrap();
        assert_eq!(saved.fall_distance, 4.25 + f64::from(0.04_f32));
        for _ in 0..30 {
            session.advance_falling_sand();
            if session.falling_sand.is_empty() {
                break;
            }
        }
        assert!(session.falling_sand.is_empty());
        assert!(!session.uncoordinated_falling_lifecycle);
        assert_eq!(
            session
                .world
                .block(session.origin.x + 3, 1, session.origin.z + 3)
                .unwrap()
                .name,
            "minecraft:sand"
        );
        let drafts = session.draft_tracked_entity_chunks().unwrap();
        let Tag::List { values, .. } = drafts[&home].document().value.get("Entities").unwrap()
        else {
            panic!()
        };
        assert_eq!(values, &[pig.clone()]);
        let terrain_source = fixture_chunk_document(home);
        let terrain = session.draft_changed_chunk(home, &terrain_source).unwrap();
        let section = palette::decode_sections(&terrain.document().value)
            .unwrap()
            .remove(0)
            .blocks
            .unwrap();
        assert_eq!(
            section.block(3, 1, 3).unwrap().name,
            "minecraft:sand".into()
        );
        assert!(session.dirty_chunk_positions().contains(&home));
        assert!(session.draft_existing_entity_chunk(home).is_err());
        let mut stale_block = block;
        let Tag::Compound(fields) = &mut stale_block else {
            panic!()
        };
        fields.push(("changed".into(), Tag::Int(1)));
        session
            .entity_chunks
            .insert(home, make_chunk(Arc::new(make(stale_block))));
        assert!(session.draft_tracked_entity_chunks().is_err());
        session.entity_chunks.insert(home, make_chunk(original));
        assert!(session.draft_tracked_entity_chunks().is_ok());
    }

