    #[test]
    fn unsupported_player_fire_and_lava_block_save_drafts() {
        use native_persistence::nbt::{NamedTag, Tag};
        let source = |fire: Vec<Tag>| NamedTag {
            name: "".into(),
            value: Tag::Compound(
                std::iter::once(("DataVersion".into(), Tag::Int(5023)))
                    .chain(fire.into_iter().map(|value| ("Fire".into(), value)))
                    .collect(),
            ),
        };
        let mut ordinary = session();
        ordinary.update(TICK);
        let saved = ordinary
            .draft_player_state(&source(vec![Tag::Short(-1)]))
            .unwrap();
        assert_eq!(saved.document().value.get("Fire"), Some(&Tag::Short(-20)));
        assert!(
            ordinary
                .draft_player_state(&source(vec![Tag::Short(0)]))
                .is_ok()
        );
        assert!(
            ordinary
                .draft_player_state(&source(vec![Tag::Short(-1)]))
                .is_ok()
        );
        for fire in [
            vec![Tag::Short(1)],
            vec![Tag::Int(1)],
            vec![Tag::Short(0), Tag::Short(0)],
        ] {
            assert!(ordinary.draft_player_state(&source(fire)).is_err());
        }

        let mut in_lava = session();
        let lava = in_lava.intern_block(state("minecraft:lava", &[("level", "0")]));
        for x in 7..=9 {
            for y in 1..=3 {
                for z in 7..=9 {
                    assert!(in_lava.set(IVec3::new(x, y, z), lava));
                }
            }
        }
        in_lava.update(TICK);
        assert!(in_lava.unresolved_player_fire_contact);
        let error = in_lava.draft_player_state(&source(vec![])).unwrap_err();
        assert!(error.to_string().contains("lava and fire"), "{error:#}");

        let mut crossing = session();
        let lava = crossing.intern_block(state("minecraft:lava", &[("level", "0")]));
        assert!(crossing.set(IVec3::new(10, 1, 8), lava));
        crossing.motion.velocity.x = 3.0;
        crossing.update(TICK);
        assert!(crossing.motion.position.x > 11.3);
        assert!(crossing.unresolved_player_fire_contact);
        assert!(crossing.draft_player_state(&source(vec![])).is_err());
    }

    #[test]
    fn unresolved_damage_blocks_all_player_save_drafts() {
        use native_persistence::nbt::{NamedTag, Tag};
        let source = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![("DataVersion".into(), Tag::Int(5023))]),
        };
        for cause in ["fall", "drown", "starve", "poison"] {
            let mut session = session();
            let effects = crate::survival::FallEffects {
                poison: (cause == "poison").then_some(crate::survival::EffectDuration {
                    ambient: false,
                    visible: true,
                    show_icon: true,
                    amplifier: 0,
                    duration: 25,
                    hidden: None,
                }),
                ..Default::default()
            };
            session.fall.configure(
                crate::player_data::SavedAttribute::with_base(3.0),
                crate::player_data::SavedAttribute::with_base(1.0),
                effects,
                Arc::new(OxygenEnchantments::default()),
            );
            match cause {
                "fall" => session.motion.position = DVec3::new(8.5, 9.0, 8.5),
                "drown" => {
                    let water = session.intern_block(state("minecraft:water", &[("level", "0")]));
                    for x in 7..=9 {
                        for y in 1..=3 {
                            for z in 7..=9 {
                                assert!(session.set(IVec3::new(x, y, z), water));
                            }
                        }
                    }
                    session.vitals.air = -19;
                }
                "starve" => {
                    session.set_survival_rules(crate::survival::SurvivalRules {
                        difficulty: native_persistence::world::Difficulty::Hard,
                        ..Default::default()
                    });
                    session.vitals.food = 0;
                    session.vitals.saturation = 0.0;
                    session.vitals.food_tick_timer = 79;
                }
                _ => {}
            }
            for _ in 0..40 {
                session.update(TICK);
                if session.unresolved_player_damage {
                    break;
                }
            }
            assert!(session.unresolved_player_damage, "{cause}");
            assert!(
                session
                    .stream_errors
                    .iter()
                    .any(|error| error.contains(&format!("player {cause}"))
                        || (cause == "starve" && error.contains("player starvation"))),
                "{cause}: {:?}",
                session.stream_errors
            );
            let error = session.draft_player_state(&source).unwrap_err().to_string();
            assert!(
                error.contains("player damage could not be resolved"),
                "{cause}: {error}"
            );
        }
    }

    #[test]
    fn lethal_fall_drowning_and_starvation_report_their_cause() {
        let mut falling = session();
        falling.set_player_vitals(crate::survival::PlayerVitals {
            health: 1.0,
            ..Default::default()
        });
        falling.motion.position = DVec3::new(8.5, 9.0, 8.5);
        for _ in 0..40 {
            falling.update(TICK);
            if falling.snapshot().death.is_some() {
                break;
            }
        }
        assert_eq!(
            falling.snapshot().death.unwrap().cause,
            DeathCause::FallHigh
        );
        falling.update(TICK);
        assert_eq!(
            falling.snapshot().camera.eye(0.0),
            falling.snapshot().camera.eye(1.0)
        );

        let mut drowning = session();
        let water = drowning.intern_block(state("minecraft:water", &[("level", "0")]));
        for x in 7..=9 {
            for y in 1..=3 {
                for z in 7..=9 {
                    assert!(drowning.set(IVec3::new(x, y, z), water));
                }
            }
        }
        drowning.set_player_vitals(crate::survival::PlayerVitals {
            health: 1.0,
            air: -19,
            ..Default::default()
        });
        let drowning_position = (drowning.origin.as_dvec3() + drowning.motion.position)
            .floor()
            .as_ivec3();
        drowning.update(TICK);
        assert_eq!(drowning.snapshot().death.unwrap().cause, DeathCause::Drown);
        assert!(
            matches!(&drowning.snapshot().last_death, crate::LastDeathLocation::At(target) if target.position == drowning_position && target.dimension.namespace == "minecraft" && target.dimension.path == "overworld")
        );

        let mut starving = session();
        starving.set_survival_rules(crate::survival::SurvivalRules {
            difficulty: native_persistence::world::Difficulty::Hard,
            ..Default::default()
        });
        starving.set_player_vitals(crate::survival::PlayerVitals {
            health: 1.0,
            food: 0,
            saturation: 0.0,
            food_tick_timer: 79,
            ..Default::default()
        });
        starving.update(TICK);
        assert_eq!(starving.snapshot().death.unwrap().cause, DeathCause::Starve);
        assert!(
            matches!(&starving.snapshot().last_death, crate::LastDeathLocation::At(target) if target.position == (starving.origin.as_dvec3() + starving.motion.position).floor().as_ivec3())
        );
    }

    #[test]
    fn lethal_loaded_death_honors_keep_inventory_and_message_rules() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        for keep in [false, true] {
            let mut session = session();
            let mut inventory = PlayerInventory::default();
            inventory.set_slot(
                PlayerSlot::Storage(0),
                ItemStack::new("minecraft:stone".into(), 5, 64, Tag::Compound(vec![])),
            );
            inventory.set_slot(
                PlayerSlot::Storage(10),
                ItemStack::new("minecraft:dirt".into(), 3, 64, Tag::Compound(vec![])),
            );
            inventory.set_slot(
                PlayerSlot::Offhand,
                ItemStack::new("minecraft:apple".into(), 2, 64, Tag::Compound(vec![])),
            );
            session.set_player_inventory(inventory);
            session.set_death_rules(DeathRules {
                keep_inventory: keep,
                show_death_messages: false,
                ..Default::default()
            });
            session.set_player_vitals(crate::survival::PlayerVitals {
                health: 1.0,
                ..Default::default()
            });
            session.motion.position = DVec3::new(8.5, 9.0, 8.5);
            for _ in 0..40 {
                session.update(TICK);
                if session.snapshot().death.is_some() {
                    break;
                }
            }
            let snapshot = session.snapshot();
            assert!(!snapshot.death.unwrap().show_message);
            assert!(!snapshot.death.unwrap().can_respawn);
            assert_eq!(
                snapshot.inventory.slot(PlayerSlot::Storage(0)).is_some(),
                keep
            );
            assert_eq!(snapshot.inventory.slot(PlayerSlot::Offhand).is_some(), keep);
            assert_eq!(snapshot.dropped_items.len(), if keep { 0 } else { 3 });
            if !keep {
                let names: Vec<_> = snapshot
                    .dropped_items
                    .iter()
                    .map(|item| item.stack.id())
                    .collect();
                assert_eq!(
                    names,
                    ["minecraft:stone", "minecraft:dirt", "minecraft:apple"]
                );
                for _ in 0..60 {
                    session.update(TICK);
                }
                assert_eq!(session.snapshot().dropped_items.len(), 3);
                assert!(
                    session
                        .snapshot()
                        .inventory
                        .slot(PlayerSlot::Storage(0))
                        .is_none()
                );
            }
        }
    }

