    #[test]
    fn promoted_jump_boost_updates_saved_safe_fall_modifier() {
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let modifier = |name: &str, amount| {
            Tag::Compound(vec![
                ("id".into(), Tag::String(name.into())),
                ("amount".into(), Tag::Double(amount)),
                ("operation".into(), Tag::String("add_value".into())),
            ])
        };
        let original = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                (
                    "active_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![Tag::Compound(vec![
                            ("id".into(), Tag::String("minecraft:jump_boost".into())),
                            ("duration".into(), Tag::Int(1)),
                            ("amplifier".into(), Tag::Byte(1)),
                            (
                                "hidden_effect".into(),
                                Tag::Compound(vec![("duration".into(), Tag::Int(100))]),
                            ),
                        ])],
                    },
                ),
                (
                    "attributes".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![Tag::Compound(vec![
                            (
                                "id".into(),
                                Tag::String("minecraft:safe_fall_distance".into()),
                            ),
                            ("base".into(), Tag::Double(3.0)),
                            (
                                "modifiers".into(),
                                Tag::List {
                                    element_type: TagType::Compound,
                                    values: vec![
                                        modifier("minecraft:effect.jump_boost", 2.0),
                                        modifier("example:keep", 0.5),
                                    ],
                                },
                            ),
                        ])],
                    },
                ),
            ]),
        };
        let (safe, multiplier) = crate::player_data::read_saved_fall_attributes(&original).unwrap();
        let mut session = session();
        session.fall.configure(
            safe,
            multiplier,
            crate::player_data::read_saved_fall_effects(&original).unwrap(),
            Arc::new(OxygenEnchantments::default()),
        );
        session.update(TICK);
        let draft = session.draft_player_state(&original).unwrap();
        let safe = crate::player_data::read_saved_fall_attributes(draft.document())
            .unwrap()
            .0;
        let id = |name| native_resources::packs::ResourceId::parse(name).unwrap();
        assert_eq!(
            safe.modifier(&id("minecraft:effect.jump_boost"))
                .unwrap()
                .amount,
            1.0
        );
        assert_eq!(safe.modifier(&id("example:keep")).unwrap().amount, 0.5);
        assert_eq!(
            crate::player_data::read_saved_fall_effects(draft.document()).unwrap(),
            *session.fall.effects()
        );
        assert_eq!(
            session
                .fall
                .effects()
                .jump_boost
                .as_ref()
                .unwrap()
                .amplifier,
            0
        );
    }

    #[test]
    fn eaten_rotten_flesh_preserves_stronger_hunger_and_tracks_save() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let original = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                (
                    "active_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![Tag::Compound(vec![
                            ("id".into(), Tag::String("minecraft:hunger".into())),
                            ("duration".into(), Tag::Int(100)),
                            ("amplifier".into(), Tag::Byte(1)),
                            ("ambient".into(), Tag::Byte(1)),
                            ("show_particles".into(), Tag::Byte(0)),
                        ])],
                    },
                ),
            ]),
        };
        let original_bytes = native_persistence::nbt::write(&original).unwrap();
        let seed = (0..100)
            .find(|&seed| {
                let mut random = native_core::random::LegacyRandom::new(seed);
                for _ in 0..6 {
                    crate::survival::FoodRandomEvent::ParticlePulse {
                        count: 5,
                        sound: crate::survival::FoodSound::Eat,
                        item: None,
                    }
                    .apply(&mut random);
                }
                crate::survival::FoodRandomEvent::Finish {
                    causes_hunger: true,
                    particles: true,
                    sound: crate::survival::FoodSound::Eat,
                    item: None,
                }
                .apply(&mut random)
            })
            .unwrap();
        let mut session = session();
        session.player_random = native_core::random::LegacyRandom::new(seed);
        session.fall.configure(
            crate::player_data::SavedAttribute::with_base(3.0),
            crate::player_data::SavedAttribute::with_base(1.0),
            crate::player_data::read_saved_fall_effects(&original).unwrap(),
            Arc::new(native_resources::enchantments::OxygenEnchantments::default()),
        );
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new(
                "minecraft:rotten_flesh".into(),
                1,
                64,
                Tag::Compound(vec![]),
            ),
        );
        session.set_player_inventory(inventory);
        session.set_player_vitals(crate::survival::PlayerVitals {
            food: 10,
            ..Default::default()
        });
        session.submit_command(PlayerCommand::Place);
        for _ in 0..32 {
            session.update(TICK);
        }
        let hunger = session.fall.effects().hunger.as_ref().unwrap();
        assert_eq!((hunger.duration, hunger.amplifier), (68, 1));
        let hidden = hunger.hidden.as_ref().unwrap();
        assert_eq!((hidden.duration, hidden.amplifier), (600, 0));
        assert!(!session.effect_save_invalid);
        assert_eq!(
            session
                .effect_save_tracking
                .as_ref()
                .unwrap()
                .status_updates,
            vec![crate::player_data::StatusUpdate {
                kind: crate::survival::FoodStatusKind::Hunger,
                remove: false,
                clear_all: false,
                update: crate::player_data::HungerUpdate {
                    tick: 32,
                    duration: 600,
                    amplifier: 0,
                    ambient: false,
                    visible: true,
                    show_icon: true
                }
            }]
        );
        assert_eq!(session.snapshot().vitals.food, 14);
        let draft = session.draft_player_state(&original).unwrap();
        assert_eq!(
            crate::player_data::read_saved_fall_effects(draft.document()).unwrap(),
            *session.fall.effects()
        );
        assert_eq!(
            native_persistence::nbt::write(&original).unwrap(),
            original_bytes
        );
    }

    #[test]
    fn custom_consumable_removes_and_reapplies_statuses_in_save_order() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let original = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                (
                    "active_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:hunger".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:poison".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:resistance".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:levitation".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:dolphins_grace".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:conduit_power".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                (
                                    "id".into(),
                                    Tag::String("minecraft:breath_of_the_nautilus".into()),
                                ),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                        ],
                    },
                ),
            ]),
        };
        let remove = Tag::Compound(vec![
            (
                "type".into(),
                Tag::String("minecraft:remove_effects".into()),
            ),
            (
                "effects".into(),
                Tag::List {
                    element_type: TagType::String,
                    values: vec![
                        Tag::String("minecraft:hunger".into()),
                        Tag::String("minecraft:poison".into()),
                        Tag::String("minecraft:resistance".into()),
                        Tag::String("minecraft:levitation".into()),
                        Tag::String("minecraft:dolphins_grace".into()),
                        Tag::String("minecraft:conduit_power".into()),
                        Tag::String("minecraft:breath_of_the_nautilus".into()),
                    ],
                },
            ),
        ]);
        let apply = Tag::Compound(vec![
            ("type".into(), Tag::String("minecraft:apply_effects".into())),
            (
                "effects".into(),
                Tag::List {
                    element_type: TagType::Compound,
                    values: vec![Tag::Compound(vec![
                        ("id".into(), Tag::String("minecraft:poison".into())),
                        ("duration".into(), Tag::Int(14)),
                    ])],
                },
            ),
        ]);
        let components = Tag::Compound(vec![(
            "minecraft:consumable".into(),
            Tag::Compound(vec![
                ("consume_seconds".into(), Tag::Float(0.0)),
                (
                    "on_consume_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![remove, apply],
                    },
                ),
            ]),
        )]);
        let mut session = session();
        session.fall.configure(
            crate::player_data::SavedAttribute::with_base(3.0),
            crate::player_data::SavedAttribute::with_base(1.0),
            crate::player_data::read_saved_fall_effects(&original).unwrap(),
            Arc::new(OxygenEnchantments::default()),
        );
        session.breathing_effects =
            crate::player_data::read_saved_breathing_effects(&original).unwrap();
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new("minecraft:apple".into(), 1, 64, components),
        );
        session.set_player_inventory(inventory);
        session.set_player_vitals(crate::survival::PlayerVitals {
            food: 10,
            ..Default::default()
        });
        session.submit_command(PlayerCommand::Place);
        session.update(TICK);
        assert!(!session.snapshot().hunger_effect);
        assert!(session.snapshot().poison_effect);
        assert!(session.fall.effects().resistance.is_none());
        assert!(session.fall.effects().levitation.is_none());
        assert!(session.fall.effects().dolphins_grace.is_none());
        assert!(session.breathing_effects.conduit_power.is_none());
        assert!(session.breathing_effects.breath_of_the_nautilus.is_none());
        assert_eq!(session.fall.effects().poison.as_ref().unwrap().duration, 13);
        let updates = &session
            .effect_save_tracking
            .as_ref()
            .unwrap()
            .status_updates;
        assert_eq!(
            updates
                .iter()
                .map(|update| (update.kind, update.remove))
                .collect::<Vec<_>>(),
            vec![
                (crate::survival::FoodStatusKind::Hunger, true),
                (crate::survival::FoodStatusKind::Poison, true),
                (crate::survival::FoodStatusKind::Resistance, true),
                (crate::survival::FoodStatusKind::Levitation, true),
                (crate::survival::FoodStatusKind::DolphinsGrace, true),
                (crate::survival::FoodStatusKind::ConduitPower, true),
                (crate::survival::FoodStatusKind::BreathOfTheNautilus, true),
                (crate::survival::FoodStatusKind::Poison, false),
            ]
        );
        let draft = session.draft_player_state(&original).unwrap();
        assert_eq!(
            crate::player_data::read_saved_fall_effects(draft.document()).unwrap(),
            *session.fall.effects()
        );
        assert_eq!(
            crate::player_data::read_saved_breathing_effects(draft.document()).unwrap(),
            session.breathing_effects
        );
    }

    #[test]
    fn custom_remove_movement_effects_removes_only_their_modifiers() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let modifier = |id: &str, amount| {
            Tag::Compound(vec![
                ("id".into(), Tag::String(id.into())),
                ("amount".into(), Tag::Double(amount)),
                (
                    "operation".into(),
                    Tag::String("add_multiplied_total".into()),
                ),
            ])
        };
        let original = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                (
                    "active_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: ["speed", "slowness"]
                            .into_iter()
                            .map(|id| {
                                Tag::Compound(vec![
                                    (
                                        "id".into(),
                                        Tag::String(format!("minecraft:{id}").as_str().into()),
                                    ),
                                    ("duration".into(), Tag::Int(100)),
                                ])
                            })
                            .collect(),
                    },
                ),
                (
                    "attributes".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![Tag::Compound(vec![
                            ("id".into(), Tag::String("minecraft:movement_speed".into())),
                            ("base".into(), Tag::Double(f64::from(0.1_f32))),
                            (
                                "modifiers".into(),
                                Tag::List {
                                    element_type: TagType::Compound,
                                    values: vec![
                                        modifier("minecraft:effect.speed", f64::from(0.2_f32)),
                                        modifier("minecraft:effect.slowness", f64::from(-0.15_f32)),
                                        modifier("example:keep", 0.2),
                                    ],
                                },
                            ),
                        ])],
                    },
                ),
            ]),
        };
        let component = Tag::Compound(vec![(
            "minecraft:consumable".into(),
            Tag::Compound(vec![
                ("consume_seconds".into(), Tag::Float(0.0)),
                (
                    "on_consume_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![Tag::Compound(vec![
                            (
                                "type".into(),
                                Tag::String("minecraft:remove_effects".into()),
                            ),
                            (
                                "effects".into(),
                                Tag::List {
                                    element_type: TagType::String,
                                    values: vec![
                                        Tag::String("minecraft:speed".into()),
                                        Tag::String("minecraft:slowness".into()),
                                    ],
                                },
                            ),
                        ])],
                    },
                ),
            ]),
        )]);
        let mut session = session();
        session.fall.configure(
            crate::player_data::SavedAttribute::with_base(3.0),
            crate::player_data::SavedAttribute::with_base(1.0),
            crate::player_data::read_saved_fall_effects(&original).unwrap(),
            Arc::new(OxygenEnchantments::default()),
        );
        session
            .set_saved_movement_speed(
                crate::player_data::read_loaded_movement_speed_attribute(&original).unwrap(),
            )
            .unwrap();
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new("minecraft:apple".into(), 1, 64, component),
        );
        session.set_player_inventory(inventory);
        session.vitals.food = 10;
        session.submit_command(PlayerCommand::Place);
        session.update(TICK);
        assert!(
            session.fall.effects().speed.is_none() && session.fall.effects().slowness.is_none()
        );
        let id = |name| native_resources::packs::ResourceId::parse(name).unwrap();
        assert!(
            session
                .movement_speed_attribute
                .modifier(&id("minecraft:effect.speed"))
                .is_none()
        );
        assert!(
            session
                .movement_speed_attribute
                .modifier(&id("minecraft:effect.slowness"))
                .is_none()
        );
        assert!(
            session
                .movement_speed_attribute
                .modifier(&id("example:keep"))
                .is_some()
        );
        assert_eq!(
            session.movement_speed(false),
            session.movement_speed_attribute.value(0.0, 1024.0).unwrap() as f32
        );
        let draft = session.draft_player_state(&original).unwrap();
        assert_eq!(
            crate::player_data::read_saved_movement_speed_attribute(draft.document()).unwrap(),
            session.movement_speed_attribute
        );
        assert_eq!(
            crate::player_data::read_saved_fall_effects(draft.document()).unwrap(),
            *session.fall.effects()
        );
    }

    #[test]
    fn custom_clear_all_then_apply_preserves_status_event_order() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let original = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                (
                    "active_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:hunger".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:poison".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:regeneration".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                        ],
                    },
                ),
            ]),
        };
        let components = Tag::Compound(vec![(
            "minecraft:consumable".into(),
            Tag::Compound(vec![
                ("consume_seconds".into(), Tag::Float(0.0)),
                (
                    "on_consume_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![
                            Tag::Compound(vec![(
                                "type".into(),
                                Tag::String("minecraft:clear_all_effects".into()),
                            )]),
                            Tag::Compound(vec![
                                ("type".into(), Tag::String("minecraft:apply_effects".into())),
                                (
                                    "effects".into(),
                                    Tag::List {
                                        element_type: TagType::Compound,
                                        values: vec![Tag::Compound(vec![
                                            ("id".into(), Tag::String("minecraft:poison".into())),
                                            ("duration".into(), Tag::Int(14)),
                                        ])],
                                    },
                                ),
                            ]),
                        ],
                    },
                ),
            ]),
        )]);
        let mut session = session();
        session.fall.configure(
            crate::player_data::SavedAttribute::with_base(3.0),
            crate::player_data::SavedAttribute::with_base(1.0),
            crate::player_data::read_saved_fall_effects(&original).unwrap(),
            Arc::new(OxygenEnchantments::default()),
        );
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new("minecraft:apple".into(), 1, 64, components),
        );
        session.set_player_inventory(inventory);
        session.set_player_vitals(crate::survival::PlayerVitals {
            food: 10,
            ..Default::default()
        });
        session.submit_command(PlayerCommand::Place);
        session.update(TICK);
        assert!(!session.snapshot().hunger_effect && session.snapshot().poison_effect);
        assert!(session.fall.effects().regeneration.is_none());
        assert_eq!(session.fall.effects().poison.as_ref().unwrap().duration, 13);
        let events = &session
            .effect_save_tracking
            .as_ref()
            .unwrap()
            .status_updates;
        assert_eq!(events.len(), 2);
        assert!(events[0].clear_all);
        assert!(!events[1].clear_all && !events[1].remove);
        let draft = session.draft_player_state(&original).unwrap();
        assert_eq!(
            crate::player_data::read_saved_fall_effects(draft.document()).unwrap(),
            *session.fall.effects()
        );
    }

    #[test]
    fn milk_clears_all_tracked_effects_and_replays_player_draft() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let effects = [
            "night_vision",
            "jump_boost",
            "resistance",
            "slow_falling",
            "levitation",
            "speed",
            "slowness",
            "dolphins_grace",
            "hunger",
            "poison",
            "luck",
            "unluck",
            "water_breathing",
            "conduit_power",
            "breath_of_the_nautilus",
        ]
        .into_iter()
        .map(|id| {
            Tag::Compound(vec![
                (
                    "id".into(),
                    Tag::String(format!("minecraft:{id}").as_str().into()),
                ),
                ("duration".into(), Tag::Int(200)),
                ("amplifier".into(), Tag::Byte(0)),
                (
                    "hidden_effect".into(),
                    Tag::Compound(vec![("duration".into(), Tag::Int(300))]),
                ),
            ])
        })
        .collect();
        let modifier = |id: &str, amount| {
            Tag::Compound(vec![
                ("id".into(), Tag::String(id.into())),
                ("amount".into(), Tag::Double(amount)),
                (
                    "operation".into(),
                    Tag::String("add_multiplied_total".into()),
                ),
            ])
        };
        let original = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("Health".into(), Tag::Float(1.0)),
                (
                    "active_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: effects,
                    },
                ),
                (
                    "attributes".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![Tag::Compound(vec![
                            ("id".into(), Tag::String("minecraft:movement_speed".into())),
                            ("base".into(), Tag::Double(f64::from(0.1_f32))),
                            (
                                "modifiers".into(),
                                Tag::List {
                                    element_type: TagType::Compound,
                                    values: vec![
                                        modifier("minecraft:effect.speed", f64::from(0.2_f32)),
                                        modifier("minecraft:effect.slowness", f64::from(-0.15_f32)),
                                        modifier("example:keep", 0.1),
                                    ],
                                },
                            ),
                        ])],
                    },
                ),
            ]),
        };
        let mut session = session();
        session.set_survival_rules(crate::survival::SurvivalRules {
            natural_health_regeneration: false,
            ..Default::default()
        });
        session.fall.configure(
            crate::player_data::SavedAttribute::with_base(3.0),
            crate::player_data::SavedAttribute::with_base(1.0),
            crate::player_data::read_saved_fall_effects(&original).unwrap(),
            Arc::new(OxygenEnchantments::default()),
        );
        session
            .set_saved_breathing(
                crate::player_data::read_saved_breathing_effects(&original).unwrap(),
                crate::player_data::SavedAttribute::with_base(0.0),
                Arc::new(OxygenEnchantments::default()),
            )
            .unwrap();
        session
            .set_saved_movement_speed(
                crate::player_data::read_loaded_movement_speed_attribute(&original).unwrap(),
            )
            .unwrap();
        session.set_player_vitals(crate::survival::PlayerVitals {
            health: 1.0,
            food: 20,
            saturation: 0.0,
            ..Default::default()
        });
        let mut inventory = PlayerInventory::default();
        inventory.set_slot(
            PlayerSlot::Storage(0),
            ItemStack::new("minecraft:milk_bucket".into(), 1, 1, Tag::Compound(vec![])),
        );
        session.set_player_inventory(inventory);
        session.submit_command(PlayerCommand::Place);
        for _ in 0..31 {
            session.update(TICK);
        }
        assert!(session.snapshot().poison_effect);
        session.update(TICK);
        assert_eq!(
            *session.fall.effects(),
            crate::survival::FallEffects::default()
        );
        assert_eq!(
            session.breathing_effects,
            crate::survival::BreathingEffects::default()
        );
        assert!(!session.snapshot().poison_effect && !session.snapshot().hunger_effect);
        assert_eq!(session.snapshot().night_vision_duration, None);
        assert_eq!(
            session.inventory.slot(PlayerSlot::Storage(0)).unwrap().id(),
            "minecraft:bucket"
        );
        let resource = |id| native_resources::packs::ResourceId::parse(id).unwrap();
        assert!(
            session
                .movement_speed_attribute
                .modifier(&resource("minecraft:effect.speed"))
                .is_none()
        );
        assert!(
            session
                .movement_speed_attribute
                .modifier(&resource("minecraft:effect.slowness"))
                .is_none()
        );
        assert!(
            session
                .movement_speed_attribute
                .modifier(&resource("example:keep"))
                .is_some()
        );
        let draft = session.draft_player_state(&original).unwrap();
        assert_eq!(
            crate::player_data::read_saved_fall_effects(draft.document()).unwrap(),
            *session.fall.effects()
        );
        assert_eq!(
            crate::player_data::read_saved_breathing_effects(draft.document()).unwrap(),
            session.breathing_effects
        );
        assert_eq!(
            crate::player_data::read_saved_movement_speed_attribute(draft.document()).unwrap(),
            session.movement_speed_attribute
        );
        let mut unsupported = original.clone();
        let Tag::Compound(fields) = &mut unsupported.value else {
            panic!()
        };
        let (_, Tag::List { values, .. }) = fields
            .iter_mut()
            .find(|(name, _)| name.matches("active_effects"))
            .unwrap()
        else {
            panic!()
        };
        values.push(Tag::Compound(vec![
            ("id".into(), Tag::String("minecraft:weakness".into())),
            ("duration".into(), Tag::Int(100)),
        ]));
        assert!(session.draft_player_state(&unsupported).is_err());
    }

    #[test]
    fn honey_bottle_removes_poison_and_preserves_other_saved_effects() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::{NamedTag, Tag, TagType};
        let original = NamedTag {
            name: "".into(),
            value: Tag::Compound(vec![
                ("DataVersion".into(), Tag::Int(5023)),
                ("Health".into(), Tag::Float(1.0)),
                (
                    "active_effects".into(),
                    Tag::List {
                        element_type: TagType::Compound,
                        values: vec![
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:poison".into())),
                                ("duration".into(), Tag::Int(100)),
                                (
                                    "hidden_effect".into(),
                                    Tag::Compound(vec![
                                        ("duration".into(), Tag::Int(200)),
                                        ("amplifier".into(), Tag::Byte(0)),
                                    ]),
                                ),
                            ]),
                            Tag::Compound(vec![
                                ("id".into(), Tag::String("minecraft:hunger".into())),
                                ("duration".into(), Tag::Int(100)),
                            ]),
                        ],
                    },
                ),
            ]),
        };
        for overridden in [false, true] {
            let mut session = session();
            session.set_survival_rules(crate::survival::SurvivalRules {
                natural_health_regeneration: false,
                ..Default::default()
            });
            session.fall.configure(
                crate::player_data::SavedAttribute::with_base(3.0),
                crate::player_data::SavedAttribute::with_base(1.0),
                crate::player_data::read_saved_fall_effects(&original).unwrap(),
                Arc::new(OxygenEnchantments::default()),
            );
            let components = if overridden {
                Tag::Compound(vec![("minecraft:consumable".into(), Tag::Compound(vec![]))])
            } else {
                Tag::Compound(vec![])
            };
            let mut inventory = PlayerInventory::default();
            inventory.set_slot(
                PlayerSlot::Storage(0),
                ItemStack::new("minecraft:honey_bottle".into(), 1, 16, components),
            );
            session.set_player_inventory(inventory);
            session.set_player_vitals(crate::survival::PlayerVitals {
                health: 1.0,
                food: 20,
                saturation: 0.0,
                ..Default::default()
            });
            session.submit_command(PlayerCommand::Place);
            let ticks = if overridden { 32 } else { 40 };
            for _ in 0..ticks - 1 {
                session.update(TICK);
            }
            assert!(session.snapshot().poison_effect);
            assert!(session.snapshot().first_person.item_use.is_some());
            session.update(TICK);
            assert_eq!(session.snapshot().poison_effect, overridden);
            assert!(session.snapshot().hunger_effect);
            assert_eq!(
                session
                    .snapshot()
                    .inventory
                    .slot(PlayerSlot::Storage(0))
                    .unwrap()
                    .id(),
                "minecraft:glass_bottle"
            );
            assert_eq!(session.snapshot().vitals.food, 20);
            let particles = session.take_consume_particles();
            assert_eq!(particles.len(), if overridden { 46 } else { 0 });
            assert!(
                particles
                    .iter()
                    .all(|particle| particle.item.id() == "minecraft:honey_bottle")
            );
            let sounds = session.take_consume_sounds();
            assert!(sounds.len() >= 3);
            assert_eq!(
                sounds[sounds.len() - 2].info.category,
                crate::ConsumeSoundCategory::Neutral
            );
            assert_eq!(sounds.last().unwrap().info.event, "entity.player.burp");
            assert_eq!(
                sounds[0].info.event,
                if overridden {
                    "entity.generic.eat"
                } else {
                    "item.honey_bottle.drink"
                }
            );
            let draft = session.draft_player_state(&original).unwrap();
            assert_eq!(
                crate::player_data::read_saved_fall_effects(draft.document()).unwrap(),
                *session.fall.effects()
            );
        }
    }

