    #[test]
    fn rising_lava_schedules_randomized_delay_and_preserves_rng_order() {
        use native_core::random::LegacyRandom;
        for fast in [false, true] {
            for seed in -12..=12 {
                let mut session = session();
                session.set_fast_lava(fast);
                let pos = IVec3::new(8, 2, 8);
                let current = FluidState {
                    kind: FluidKind::Lava,
                    amount: 3,
                    source: false,
                    falling: false,
                };
                let source = FluidState {
                    kind: FluidKind::Lava,
                    amount: 8,
                    source: true,
                    falling: false,
                };
                let current_id = session.intern_liquid(current);
                let source_id = session.intern_liquid(source);
                assert!(session.set_with_notify(pos, current_id, false));
                assert!(session.set_with_notify(pos + IVec3::NEG_X, source_id, false));
                assert!(session.set_with_notify(pos + IVec3::NEG_Y, session.states[3], false));
                session.fluid_ticks.clear();
                session.fluid_pending.clear();
                session.level_random = LegacyRandom::new(seed);
                let mut expected_random = LegacyRandom::new(seed);
                let multiplier = if expected_random.next_int_bound(4).unwrap() == 0 {
                    1
                } else {
                    4
                };
                session.schedule_fluid(pos, current, 0);
                session.advance_fluid_ticks();
                let absolute = session.origin + pos;
                let expected_delay = if fast { 10 } else { 30 } * multiplier;
                let due: Vec<_> = session
                    .fluid_ticks
                    .iter()
                    .filter_map(|(order, scheduled)| {
                        (scheduled.key.x == absolute.x
                            && scheduled.key.y == absolute.y
                            && scheduled.key.z == absolute.z
                            && !scheduled.key.source)
                            .then_some(order.0)
                    })
                    .collect();
                assert_eq!(due, [i128::from(expected_delay)], "fast={fast} seed={seed}");
                assert_eq!(
                    session.level_random.next_int(),
                    expected_random.next_int(),
                    "fast={fast} seed={seed}"
                );
                assert!(
                    matches!(session.simulation_cell(pos), fluid_sim::Cell::Fluid(state) if state.amount == if fast { 7 } else { 6 })
                );
            }
        }
    }

    #[test]
    fn falling_and_receding_lava_do_not_consume_delay_rng() {
        use native_core::random::LegacyRandom;
        for above in [false, true] {
            let mut session = session();
            let pos = IVec3::new(8, 2, 8);
            let current = FluidState {
                kind: FluidKind::Lava,
                amount: 3,
                source: false,
                falling: false,
            };
            let source = FluidState {
                kind: FluidKind::Lava,
                amount: 8,
                source: true,
                falling: false,
            };
            let current_id = session.intern_liquid(current);
            let source_id = session.intern_liquid(source);
            assert!(session.set_with_notify(pos, current_id, false));
            assert!(session.set_with_notify(pos + IVec3::NEG_Y, session.states[3], false));
            if above {
                assert!(session.set_with_notify(pos + IVec3::Y, source_id, false));
            }
            session.fluid_ticks.clear();
            session.fluid_pending.clear();
            session.level_random = LegacyRandom::new(90210);
            let mut expected = session.level_random.clone();
            session.schedule_fluid(pos, current, 0);
            session.advance_fluid_ticks();
            assert_eq!(
                session.level_random.next_int(),
                expected.next_int(),
                "above={above}"
            );
            assert!(if above {
                matches!(session.simulation_cell(pos), fluid_sim::Cell::Fluid(state) if state.falling)
            } else {
                session.simulation_cell(pos) == fluid_sim::Cell::Air
            });
        }
    }

    #[test]
    fn shared_clocks_advance_on_fixed_ticks_and_respect_rules() {
        use native_persistence::world::{DimensionId, SavedClock};
        let id = DimensionId::parse("minecraft:overworld").unwrap();
        let mut session = session();
        let initial = SavedClock {
            total_ticks: 10,
            partial_tick: 0.0,
            rate: 0.5,
            paused: false,
        };
        session.set_world_clocks(BTreeMap::from([(id.clone(), initial)]), true);
        session.update(TICK / 2);
        assert_eq!(session.world_clock(&id), Some(initial));
        session.update(TICK / 2);
        assert_eq!(session.world_clock(&id).unwrap().partial_tick, 0.5);
        session.update(TICK);
        assert_eq!(session.world_clock(&id).unwrap().total_ticks, 11);
        let clock = session.world_clock(&id).unwrap();
        session.set_world_clocks(BTreeMap::from([(id.clone(), clock)]), false);
        session.update(TICK * 5);
        assert_eq!(session.world_clock(&id), Some(clock));
    }

    #[test]
    fn fast_lava_timeline_tracks_the_shared_clock_before_fluid_ticks() {
        use native_persistence::world::{DimensionId, SavedClock};
        use native_resources::{
            fluid_environment::load_fast_lava_environment, packs::ResourceProvider,
        };
        struct Data;
        impl ResourceProvider for Data {
            fn read_asset(&mut self, _: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(None)
            }
            fn read_data(&mut self, path: &str) -> anyhow::Result<Option<Vec<u8>>> {
                Ok(match path {
                    "data/example/dimension_type/test.json" => Some(br#"{"timelines":["example:test"]}"#.to_vec()),
                    "data/example/timeline/test.json" => Some(br#"{"clock":"example:clock","period_ticks":10,"tracks":{"gameplay/fast_lava":{"keyframes":[{"ticks":0,"value":false},{"ticks":1,"value":true},{"ticks":3,"value":false}]}}}"#.to_vec()),
                    _ => None,
                })
            }
        }
        let environment = Arc::new(load_fast_lava_environment(&mut Data, "example:test").unwrap());
        let id = DimensionId::parse("example:clock").unwrap();
        let mut session = fluid_flow_session(FluidKind::Lava, false);
        session.set_world_clocks(BTreeMap::from([(id.clone(), SavedClock::default())]), true);
        session.set_fast_lava_environment(environment).unwrap();
        assert!(!session.fast_lava);
        let wall = IVec3::new(9, 2, 8);
        assert!(session.set(wall, session.states[0]));
        session.fluid_ticks.clear();
        session.fluid_pending.clear();
        session.schedule_fluid(
            IVec3::new(8, 2, 8),
            FluidState {
                kind: FluidKind::Lava,
                amount: 8,
                source: true,
                falling: false,
            },
            0,
        );
        session.update(TICK);
        assert!(session.fast_lava);
        assert!(
            matches!(session.simulation_cell(wall), fluid_sim::Cell::Fluid(f) if f.kind == FluidKind::Lava && f.amount == 7)
        );
        session.update(TICK);
        assert!(session.fast_lava);
        session.update(TICK);
        assert!(!session.fast_lava);
        let clock = session.world_clock(&id).unwrap();
        session.set_world_clocks(BTreeMap::from([(id, clock)]), false);
        session.update(TICK * 10);
        assert!(!session.fast_lava);
    }

    #[test]
    fn saved_source_conversion_rules_control_new_water_and_lava_sources() {
        for kind in [FluidKind::Water, FluidKind::Lava] {
            for enabled in [false, true] {
                let mut session = session();
                session.set_source_conversion(
                    kind == FluidKind::Water && enabled,
                    kind == FluidKind::Lava && enabled,
                );
                let source = FluidState {
                    kind,
                    amount: 8,
                    source: true,
                    falling: false,
                };
                let flowing = FluidState {
                    kind,
                    amount: 5,
                    source: false,
                    falling: false,
                };
                let source_id = session.intern_liquid(source);
                let flowing_id = session.intern_liquid(flowing);
                session.set(IVec3::new(7, 1, 8), source_id);
                session.set(IVec3::new(9, 1, 8), source_id);
                session.set(IVec3::new(8, 1, 8), flowing_id);
                session.fluid_ticks.clear();
                session.fluid_pending.clear();
                session.schedule_fluid(IVec3::new(8, 1, 8), flowing, 0);
                session.update(TICK);
                let fluid = match session.simulation_cell(IVec3::new(8, 1, 8)) {
                    fluid_sim::Cell::Fluid(fluid) => fluid,
                    other => panic!("expected fluid, got {other:?}"),
                };
                assert_eq!(fluid.source, enabled, "{kind:?}");
            }
        }
    }

    #[test]
    fn wet_grates_count_as_sources_without_allowing_water_through_their_faces() {
        {
            let mut session = session();
            let pos = IVec3::new(8, 3, 8);
            let water = FluidState {
                kind: FluidKind::Water,
                amount: 8,
                source: true,
                falling: false,
            };
            let water_id = session.intern_liquid(water);
            let grate =
                session.intern_block(state("minecraft:copper_grate", &[("waterlogged", "true")]));
            session.set_with_notify(pos, water_id, false);
            session.set_with_notify(pos + IVec3::NEG_Y, session.states[0], false);
            session.set_with_notify(pos + IVec3::X, session.states[0], false);
            for direction in [IVec3::NEG_X, IVec3::NEG_Z, IVec3::Z] {
                assert!(session.set_with_notify(pos + direction, grate, false));
            }
            session.fluid_ticks.clear();
            session.fluid_pending.clear();
            session.schedule_fluid(pos, water, 0);
            session.advance_fluid_ticks();
            assert!(
                matches!(session.simulation_cell(pos + IVec3::NEG_Y), fluid_sim::Cell::Fluid(f) if f.falling)
            );
            assert!(
                matches!(session.simulation_cell(pos + IVec3::X), fluid_sim::Cell::Fluid(f) if f.amount == 7)
            );
            for direction in [IVec3::NEG_X, IVec3::NEG_Z, IVec3::Z] {
                assert!(matches!(
                    session.simulation_cell(pos + direction),
                    fluid_sim::Cell::GrateWater(_)
                ));
            }
        }

        let mut session = session();
        let pos = IVec3::new(8, 3, 8);
        let water = FluidState {
            kind: FluidKind::Water,
            amount: 8,
            source: true,
            falling: false,
        };
        let source_id = session.intern_liquid(water);
        let flowing = FluidState {
            amount: 4,
            source: false,
            ..water
        };
        let flowing_id = session.intern_liquid(flowing);
        let grate = session.intern_block(state(
            "minecraft:waxed_oxidized_copper_grate",
            &[("waterlogged", "true")],
        ));
        session.set_with_notify(pos, flowing_id, false);
        session.set_with_notify(pos + IVec3::NEG_Y, grate, false);
        session.set_with_notify(pos + IVec3::NEG_X, source_id, false);
        session.set_with_notify(pos + IVec3::X, source_id, false);
        session.set_source_conversion(true, false);
        session.fluid_ticks.clear();
        session.fluid_pending.clear();
        session.schedule_fluid(pos, flowing, 0);
        session.advance_fluid_ticks();
        assert!(matches!(session.simulation_cell(pos), fluid_sim::Cell::Fluid(f) if f.source));
        assert!(matches!(
            session.simulation_cell(pos + IVec3::NEG_Y),
            fluid_sim::Cell::GrateWater(_)
        ));
    }

    #[test]
    fn waterlogged_slabs_respect_their_collision_faces_and_keep_their_block() {
        for top in [false, true] {
            let mut session = session();
            session.set_vanilla_block_ids(Arc::new(BTreeSet::from(["minecraft:oak_slab".into()])));
            let pos = IVec3::new(8, 3, 8);
            let slab = session.intern_block(state(
                "minecraft:oak_slab",
                &[
                    ("type", if top { "top" } else { "bottom" }),
                    ("waterlogged", "true"),
                ],
            ));
            session.set_with_notify(pos, slab, false);
            session.set_with_notify(pos + IVec3::NEG_Y, session.states[0], false);
            session.set_with_notify(pos + IVec3::X, session.states[0], false);
            session.set_with_notify(pos + IVec3::X + IVec3::NEG_Y, session.states[3], false);
            for direction in [IVec3::NEG_X, IVec3::NEG_Z, IVec3::Z] {
                session.set_with_notify(pos + direction, session.states[3], false);
            }
            session.fluid_ticks.clear();
            session.fluid_pending.clear();
            let water = session.simulated_fluid(slab).unwrap();
            session.schedule_fluid(pos, water, 0);
            session.advance_fluid_ticks();
            assert_eq!(
                session.simulation_cell(pos),
                fluid_sim::Cell::Slab {
                    top,
                    waterlogged: true
                }
            );
            if top {
                assert!(
                    matches!(session.simulation_cell(pos + IVec3::NEG_Y), fluid_sim::Cell::Fluid(f) if f.falling)
                );
                assert_eq!(
                    session.simulation_cell(pos + IVec3::X),
                    fluid_sim::Cell::Air
                );
            } else {
                assert_eq!(
                    session.simulation_cell(pos + IVec3::NEG_Y),
                    fluid_sim::Cell::Air
                );
                assert!(
                    matches!(session.simulation_cell(pos + IVec3::X), fluid_sim::Cell::Fluid(f) if f.amount == 7)
                );
            }
        }
    }

