    #[test]
    fn falling_sand_expires_at_java_age_boundaries_and_respects_entity_drops() {
        for (outside, age, drops) in [(true, 99, true), (true, 99, false), (false, 599, true)] {
            let mut session = session();
            session.set_entity_drops(drops);
            let relative_y = if outside {
                session.bounds.max_y - session.origin.y + 2
            } else {
                5
            };
            let position = (session.origin + IVec3::new(10, relative_y, 8)).as_dvec3()
                + DVec3::new(0.5, 0.0, 0.5);
            session.falling_sand.push(FallingSand {
                previous: position,
                fall_distance: 0.0,
                fall_distance_verified: true,
                motion: crate::falling_block::AirborneMotion {
                    position,
                    velocity: DVec3::ZERO,
                    age,
                    no_gravity: true,
                },
                kind: FallingKind::RedSand,
                drop_item: true,
                cancel_drop: false,
                on_ground: false,
                source: None,
                created: None,
            });
            session.advance_falling_sand();
            assert_eq!(session.falling_sand.len(), 1);
            assert!(session.dropped_items.snapshot().is_empty());
            session.advance_falling_sand();
            assert!(session.falling_sand.is_empty());
            let items = session.dropped_items.snapshot();
            assert_eq!(items.len(), usize::from(drops));
            if drops {
                assert_eq!(items[0].position, position);
                assert_eq!(items[0].stack.id(), "minecraft:red_sand");
            }
        }
    }

    #[test]
    fn falling_blocks_interact_with_all_snow_layer_states() {
        for layers in 1..=8 {
            for falling in ["minecraft:sand", "minecraft:red_sand", "minecraft:gravel"] {
                let mut session = session();
                let target = IVec3::new(10, 1, 8);
                let snow = session
                    .intern_block(state("minecraft:snow", &[("layers", &layers.to_string())]));
                assert!(session.set(target, snow));
                let block = session.intern_block(state(falling, &[]));
                assert!(session.set(IVec3::new(10, 2, 8), block));
                session.tick = 2;
                session.advance_sand_ticks();
                assert_eq!(session.falling_sand.len(), 1, "{layers} layers: {falling}");
                for _ in 0..40 {
                    session.advance_falling_sand();
                }
                assert!(
                    session.falling_sand.is_empty(),
                    "{layers} layers: {falling}"
                );
                let actual = session
                    .world
                    .block(
                        session.origin.x + target.x,
                        target.y,
                        session.origin.z + target.z,
                    )
                    .unwrap();
                assert_eq!(
                    actual.name,
                    if layers == 1 {
                        falling
                    } else {
                        "minecraft:snow"
                    }
                );
                let items = session.dropped_items.snapshot();
                assert_eq!(items.len(), usize::from(layers != 1));
                if layers != 1 {
                    assert_eq!(items[0].stack.id(), falling);
                }
            }
        }
    }

    #[test]
    fn player_lands_at_snow_collision_height() {
        for layers in 1..=8 {
            let mut session = session();
            let snow =
                session.intern_block(state("minecraft:snow", &[("layers", &layers.to_string())]));
            assert!(session.set(IVec3::new(4, 1, 4), snow));
            session.motion.position = DVec3::new(4.5, 3.0, 4.5);
            session.motion.velocity = DVec3::new(0.0, -1.5, 0.0);
            session.motion.on_ground = false;
            session.player.position = session.motion.position.as_vec3();
            session.player.on_ground = false;
            for _ in 0..5 {
                session.update(TICK);
                if session.motion.on_ground {
                    break;
                }
            }
            assert!(session.motion.on_ground, "{layers} layers");
            assert!(
                (session.motion.position.y - (1.0 + f64::from(layers - 1) / 8.0)).abs() < 1e-7,
                "{layers} layers: {}",
                session.motion.position.y
            );
        }
    }

    #[test]
    fn sand_landing_inside_nonreplaceable_empty_blocks_drops() {
        for block in [
            "minecraft:dandelion",
            "minecraft:poppy",
            "minecraft:torch",
            "minecraft:oak_sapling",
        ] {
            for (drops, drop_item, cancelled) in [false, true].into_iter().flat_map(|drops| {
                [false, true].into_iter().flat_map(move |drop_item| {
                    [false, true]
                        .into_iter()
                        .map(move |cancelled| (drops, drop_item, cancelled))
                })
            }) {
                for falling in ["minecraft:sand", "minecraft:red_sand", "minecraft:gravel"] {
                    let mut session = session();
                    session.set_entity_drops(drops);
                    let target = IVec3::new(10, 1, 8);
                    let plant = session.intern_block(state(block, &[]));
                    assert!(session.set(target, plant));
                    let sand = session.intern_block(state(falling, &[]));
                    assert!(session.set(IVec3::new(10, 4, 8), sand));
                    session.tick = 2;
                    session.advance_sand_ticks();
                    assert_eq!(session.falling_sand.len(), 1);
                    session.falling_sand[0].drop_item = drop_item;
                    session.falling_sand[0].cancel_drop = cancelled;
                    for _ in 0..50 {
                        session.advance_falling_sand();
                    }
                    assert!(session.falling_sand.is_empty(), "{block}");
                    assert!(
                        matches!(cell(&session.world, session.origin, session.bounds, target, session.states[0]), Cell::State(id) if id == plant),
                        "{block}"
                    );
                    let items = session.dropped_items.snapshot();
                    let expect_drop = drops && drop_item && !cancelled;
                    assert_eq!(items.len(), usize::from(expect_drop), "{block}");
                    if expect_drop {
                        assert_eq!(items[0].stack.id(), falling);
                    }
                }
            }
        }
    }

