    #[test]
    fn interactions_change_only_new_snapshots_and_keep_origin_precision() {
        let mut session = session();
        session.set_game_mode(GameMode::Creative);
        let before = session.snapshot();
        let target = session.origin + IVec3::new(8, 2, 6);
        assert_eq!(
            before
                .world
                .loaded()
                .unwrap()
                .block(target.x, target.y, target.z)
                .unwrap()
                .name,
            "minecraft:stone"
        );
        session.submit_command(PlayerCommand::Break);
        session.update(TICK);
        let after = session.snapshot();
        assert_eq!(
            before
                .world
                .loaded()
                .unwrap()
                .block(target.x, target.y, target.z)
                .unwrap()
                .name,
            "minecraft:stone"
        );
        assert_eq!(
            after
                .world
                .loaded()
                .unwrap()
                .block(target.x, target.y, target.z)
                .unwrap()
                .name,
            "minecraft:air"
        );
        assert!(!Arc::ptr_eq(
            before.world.loaded().unwrap(),
            after.world.loaded().unwrap()
        ));
        assert_eq!(after.world_revision, 1);

        let mut session = self::session();
        session.submit_command(PlayerCommand::Select(Block::Dirt));
        session.submit_command(PlayerCommand::Place);
        session.update(TICK);
        let adjacent = session.origin + IVec3::new(8, 2, 7);
        assert_eq!(
            session
                .snapshot()
                .world
                .loaded()
                .unwrap()
                .block(adjacent.x, adjacent.y, adjacent.z)
                .unwrap()
                .name,
            "minecraft:dirt"
        );
    }

    #[test]
    fn placing_a_saved_stack_respects_mode_and_preserves_old_snapshots() {
        use crate::inventory::{ItemStack, PlayerSlot};
        use native_persistence::nbt::Tag;
        for mode in [
            GameMode::Survival,
            GameMode::Creative,
            GameMode::Adventure,
            GameMode::Spectator,
        ] {
            let mut session = session();
            session.set_game_mode(mode);
            let mut inventory = PlayerInventory::default();
            inventory.set_slot(
                PlayerSlot::Storage(0),
                ItemStack::new(
                    "minecraft:stone_bricks".into(),
                    1,
                    64,
                    Tag::Compound(vec![]),
                ),
            );
            session.set_player_inventory(inventory);
            let before = session.snapshot();
            let target = session.origin + IVec3::new(8, 2, 7);
            session.submit_command(PlayerCommand::Place);
            session.update(TICK);
            let after = session.snapshot();
            let placed = matches!(mode, GameMode::Survival | GameMode::Creative);
            assert_eq!(
                after
                    .world
                    .loaded()
                    .unwrap()
                    .block(target.x, target.y, target.z)
                    .unwrap()
                    .name,
                if placed {
                    "minecraft:stone_bricks"
                } else {
                    "minecraft:air"
                }
            );
            assert_eq!(
                after.inventory.slot(PlayerSlot::Storage(0)).is_none(),
                mode == GameMode::Survival
            );
            assert_eq!(
                before
                    .inventory
                    .slot(PlayerSlot::Storage(0))
                    .unwrap()
                    .count(),
                1
            );
            assert_eq!(
                before
                    .world
                    .loaded()
                    .unwrap()
                    .block(target.x, target.y, target.z)
                    .unwrap()
                    .name,
                "minecraft:air"
            );
        }
    }

    #[test]
    fn passive_main_hand_allows_offhand_block_placement() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::Tag;
        for main in [
            "minecraft:stick",
            "minecraft:wooden_pickaxe",
            "minecraft:iron_sword",
        ] {
            for offhand in [
                "minecraft:stone_bricks",
                "minecraft:stone_button",
                "minecraft:lever",
                "minecraft:redstone_lamp",
                "minecraft:redstone_block",
            ] {
                for mode in [GameMode::Survival, GameMode::Creative] {
                    let mut session = session();
                    session.set_game_mode(mode);
                    let mut inventory = PlayerInventory::default();
                    let max = if main == "minecraft:stick" { 64 } else { 1 };
                    inventory.set_slot(
                        PlayerSlot::Storage(0),
                        ItemStack::new(main.into(), 1, max, Tag::Compound(vec![])),
                    );
                    inventory.set_slot(
                        PlayerSlot::Offhand,
                        ItemStack::new(offhand.into(), 2, 64, Tag::Compound(vec![])),
                    );
                    session.set_player_inventory(inventory);
                    session.submit_command(PlayerCommand::Place);
                    session.update(TICK);
                    let target = session.origin + IVec3::new(8, 2, 7);
                    assert_eq!(
                        session
                            .world
                            .block(target.x, target.y, target.z)
                            .unwrap()
                            .name,
                        offhand,
                        "{main} {offhand} {mode:?}"
                    );
                    assert_eq!(
                        session.first_person.swing.hand(),
                        Some(crate::animation::Hand::Off)
                    );
                    assert_eq!(
                        session
                            .inventory
                            .slot(PlayerSlot::Storage(0))
                            .unwrap()
                            .count(),
                        1
                    );
                    assert_eq!(
                        session.inventory.slot(PlayerSlot::Offhand).unwrap().count(),
                        if mode == GameMode::Survival { 1 } else { 2 }
                    );
                }
            }
        }
    }

