    #[test]
    fn slab_support_controls_button_placement_and_neighbor_updates() {
        use crate::inventory::PlayerSlot;
        use native_persistence::nbt::Tag;
        for kind in ["bottom", "top", "double"] {
            for face in [
                IVec3::X,
                IVec3::NEG_X,
                IVec3::Y,
                IVec3::NEG_Y,
                IVec3::Z,
                IVec3::NEG_Z,
            ] {
                let sturdy = kind == "double"
                    || (kind == "top" && face == IVec3::Y)
                    || (kind == "bottom" && face == IVec3::NEG_Y);
                let mut placement = session();
                let mut inventory = PlayerInventory::default();
                inventory.set_slot(
                    PlayerSlot::Storage(0),
                    ItemStack::new(
                        "minecraft:stone_button".into(),
                        1,
                        64,
                        Tag::Compound(vec![]),
                    ),
                );
                placement.set_player_inventory(inventory);
                let support = IVec3::new(8, 2, 6);
                let slab = placement.intern_block(state(
                    "minecraft:oak_slab",
                    &[("type", kind), ("waterlogged", "false")],
                ));
                assert!(placement.set(support, slab));
                if face == IVec3::NEG_Y {
                    assert!(placement.set(support + face + IVec3::NEG_Y, placement.states[0]));
                }
                let hit = ShapeRayHit {
                    position: support,
                    face,
                    location: DVec3::ZERO,
                    inside: false,
                };
                assert_eq!(
                    placement.place_button(hit).is_some(),
                    sturdy,
                    "{kind} {face:?}"
                );

                let mut changed = session();
                let button_pos = support + face;
                let button_id = changed.intern_block(stone_button_state(face, 0.0).unwrap());
                assert!(changed.set(button_pos, button_id));
                let slab_id = changed.intern_block(state(
                    "minecraft:oak_slab",
                    &[("type", kind), ("waterlogged", "false")],
                ));
                assert!(changed.set(support, slab_id));
                let Cell::State(after) = cell(
                    &changed.world,
                    changed.origin,
                    changed.bounds,
                    button_pos,
                    changed.states[0],
                ) else {
                    panic!("unloaded target")
                };
                assert_eq!(
                    after == button_id,
                    sturdy,
                    "changed support {kind} {face:?}"
                );
            }
        }
    }

    #[test]
    fn additional_supports_update_attached_buttons_on_every_face() {
        let cases = [
            state("minecraft:dirt_path", &[]),
            state("minecraft:farmland", &[("moisture", "7")]),
            state(
                "minecraft:straw_bed",
                &[("part", "head"), ("facing", "north"), ("occupied", "false")],
            ),
            state("minecraft:honey_block", &[]),
            state(
                "minecraft:oak_leaves",
                &[
                    ("distance", "1"),
                    ("persistent", "false"),
                    ("waterlogged", "false"),
                ],
            ),
            state(
                "minecraft:oak_fence",
                &[
                    ("north", "true"),
                    ("south", "false"),
                    ("west", "true"),
                    ("east", "false"),
                    ("waterlogged", "false"),
                ],
            ),
            state(
                "minecraft:glass_pane",
                &[
                    ("north", "true"),
                    ("south", "true"),
                    ("west", "false"),
                    ("east", "false"),
                    ("waterlogged", "false"),
                ],
            ),
            state(
                "minecraft:red_bed",
                &[("part", "head"), ("facing", "north"), ("occupied", "false")],
            ),
            state("minecraft:flower_pot", &[]),
        ];
        for support_state in cases {
            assert_eq!(button_can_replace(&support_state), Some(false));
            for face in [
                IVec3::X,
                IVec3::NEG_X,
                IVec3::Y,
                IVec3::NEG_Y,
                IVec3::Z,
                IVec3::NEG_Z,
            ] {
                let expected = matches!(
                    support_state.name.as_str(),
                    "minecraft:dirt_path" | "minecraft:farmland" | "minecraft:straw_bed"
                ) && face == IVec3::NEG_Y;
                assert_eq!(
                    button_support_face(&support_state, face),
                    Some(expected),
                    "{support_state:?} {face:?}"
                );
                let mut session = session();
                let support = IVec3::new(8, 2, 6);
                let button = support + face;
                let button_id = session.intern_block(stone_button_state(face, 0.0).unwrap());
                assert!(session.set(button, button_id));
                let support_id = session.intern_block(support_state.clone());
                assert!(session.set(support, support_id));
                assert!(
                    matches!(cell(&session.world, session.origin, session.bounds, button, session.states[0]), Cell::State(id) if (id == button_id) == expected),
                    "{support_state:?} {face:?}"
                );
            }
        }
    }

    #[test]
